"use client";

import React, { useState, useEffect } from "react";

import { Loader2, Building2, MapPin, Save, FileText } from "lucide-react";
import {
  ADMIN_CONTENT,
  ADMIN_PAGE_SHELL,
  AdminPageHeader,
} from "@views/components/ui/admin";
import { useToast } from "@views/components/providers/ToastProvider";
import { usePermission } from "@/controllers/hooks/usePermission";
import { api } from "@/lib";

export default function GeneralConfigPage() {
  const [companyName, setCompanyName] = useState("");
  const [companyAddress, setCompanyAddress] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const { showToast } = useToast();
  const { canAny } = usePermission();
  const canEdit = canAny(["config.access:edit", "config.role_management:edit"]);

  useEffect(() => {
    const fetchSettings = async () => {
      try {
        const res = await api.get<any>("/api/admin/settings");
        const data = res.data;
        if (data) {
          setCompanyName(data.companyName || "");
          setCompanyAddress(data.companyAddress || "");
        }
      } catch (err: any) {
        console.error("Failed to load settings", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchSettings();
  }, []);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await api.post("/api/admin/settings", { companyName, companyAddress });
      showToast("บันทึกข้อมูลเรียบร้อยแล้ว", "success");
    } catch (err: any) {
      showToast(err.message || "เกิดข้อผิดพลาดในการบันทึก", "error");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className={ADMIN_PAGE_SHELL}>
      <AdminPageHeader
        breadcrumb={
          <nav className="flex items-center gap-1.5 text-xs text-slate-400">
            <span>Admin</span>
            <span>/</span>
            <span className="text-slate-500">Config</span>
            <span>/</span>
            <span className="text-slate-800 font-bold">General</span>
          </nav>
        }
        title="General Settings"
        subtitle="ตั้งค่าทั่วไปของระบบและข้อมูลองค์กร"
      />

      <div className={ADMIN_CONTENT}>
        <div className="max-w-3xl mt-6">
          <div className="bg-white border border-slate-200/60 rounded-2xl shadow-sm overflow-hidden flex flex-col">
            {/* Card Header */}
            <div className="px-6 py-6 sm:px-8 sm:py-8 border-b border-slate-100">
              <div className="flex items-start gap-4">
                <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center text-blue-600 shrink-0 border border-blue-100/50">
                  <Building2 className="w-6 h-6" />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-slate-800 mb-1">
                    ข้อมูลบริษัท (Company Identity)
                  </h2>
                  <p className="text-sm text-slate-500 leading-relaxed max-w-xl">
                    ข้อมูลที่ตั้งค่าในส่วนนี้จะถูกนำไปใช้เป็นส่วนหัว (Header)
                    ของเอกสารแบบฟอร์มต่างๆ ภายในระบบโดยอัตโนมัติ เช่น ใบขอซื้อ
                    (PR) และ ใบสั่งซื้อ (PO)
                  </p>
                </div>
              </div>
            </div>

            {/* Form Content */}
            <div className="px-6 py-8 sm:px-8 flex-1">
              {isLoading ? (
                <div className="space-y-6 animate-pulse">
                  <div>
                    <div className="h-4 w-24 bg-slate-200 rounded mb-2"></div>
                    <div className="h-12 w-full bg-slate-100 rounded-xl"></div>
                  </div>
                  <div>
                    <div className="h-4 w-48 bg-slate-200 rounded mb-2"></div>
                    <div className="h-32 w-full bg-slate-100 rounded-xl"></div>
                  </div>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="group">
                    <label className="flex items-center gap-2 text-sm font-bold text-slate-700 mb-2">
                      <FileText className="w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                      ชื่อบริษัท (Company Name)
                    </label>
                    <input
                      type="text"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      className="w-full px-4 py-3 bg-slate-50/50 border border-slate-200 rounded-xl text-sm focus:bg-white focus:outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all text-slate-700 font-medium placeholder:text-slate-400 placeholder:font-normal"
                      placeholder="เช่น บริษัท นิสซุย (ประเทศไทย) จำกัด"
                    />
                  </div>

                  <div className="group">
                    <label className="flex items-center gap-2 text-sm font-bold text-slate-700 mb-2">
                      <MapPin className="w-4 h-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                      ที่อยู่และเลขประจำตัวผู้เสียภาษี
                    </label>
                    <textarea
                      value={companyAddress}
                      onChange={(e) => setCompanyAddress(e.target.value)}
                      rows={4}
                      className="w-full px-4 py-3 bg-slate-50/50 border border-slate-200 rounded-xl text-sm focus:bg-white focus:outline-none focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 transition-all resize-none text-slate-700 font-medium placeholder:text-slate-400 placeholder:font-normal leading-relaxed"
                      placeholder="เช่น เลขที่ 123 อาคารนิสซุย กรุงเทพมหานคร 10110&#10;เลขประจำตัวผู้เสียภาษี: 0105559000123"
                    />
                    <p className="text-xs text-slate-400 mt-2 flex items-center gap-1">
                      * สามารถเว้นวรรคหรือขึ้นบรรทัดใหม่ได้ตามต้องการ
                      ระบบจะแสดงผลตามรูปแบบที่จัดไว้
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* Footer Action */}
            <div className="bg-slate-50 px-6 py-4 sm:px-8 border-t border-slate-100 flex justify-end items-center gap-3">
              <button
                onClick={handleSave}
                disabled={!canEdit || isSaving || isLoading}
                className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm hover:shadow active:scale-[0.98]"
              >
                {isSaving ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin" /> กำลังบันทึก...
                  </>
                ) : (
                  <>
                    <Save className="w-4 h-4" /> บันทึกการเปลี่ยนแปลง
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

   
   
   
   
   
   
import React from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import {
  ChevronRight,
  Shield,
  ShieldPlus,
  UserCheck,
  UserPlus,
  UserX,
  Users,
} from "lucide-react";
import { AppStatCard, StatCardGrid } from '@views/components/ui/AppStatCard';
import { APP_CARD } from '@views/components/ui/design-system';
import {
  ADMIN_CONTENT,
  ADMIN_PAGE_SHELL,
  AdminPageHeader,
} from '@views/components/ui/admin';
import { adminService } from "@/controllers/services/admin.service";

const ACTION_CARDS = [
  {
    title: "สร้าง Role",
    subtitle: "กำหนดสิทธิ์และระดับการเข้าถึง",
    icon: ShieldPlus,
    href: "/admin/config/roles?mode=new",
    iconBg: "bg-indigo-50",
    iconColor: "text-indigo-600",
  },
  {
    title: "สร้างผู้ใช้งาน",
    subtitle: "เพิ่มบัญชีผู้ใช้งานใหม่",
    icon: UserPlus,
    href: "/admin/config/users?mode=new",
    iconBg: "bg-blue-50",
    iconColor: "text-blue-600",
  },
] as const;

const NAV_CARDS = [
  {
    title: "จัดการ Roles",
    description: "ดู สร้าง แก้ไข และกำหนดสิทธิ์การเข้าถึงแต่ละบทบาท",
    href: "/admin/config/roles",
    icon: Shield,
    iconBg: "bg-indigo-50",
    iconColor: "text-indigo-600",
    badgeBg: "bg-indigo-50 text-indigo-700 ring-indigo-100",
    countKey: "totalRoles" as const,
    countLabel: "บทบาท",
  },
  {
    title: "จัดการ Users",
    description: "ดู สร้าง แก้ไข และจัดการบัญชีผู้ใช้งานในระบบ",
    href: "/admin/config/users",
    icon: Users,
    iconBg: "bg-blue-50",
    iconColor: "text-blue-600",
    badgeBg: "bg-blue-50 text-blue-700 ring-blue-100",
    countKey: "totalUsers" as const,
    countLabel: "ผู้ใช้งาน",
  },
] as const;

export default function ConfigPage() {
  const router = useRouter();

  const [stats, setStats] = React.useState({
    totalRoles: 0,
    totalUsers: 0,
    activeUsers: 0,
    inactiveUsers: 0,
  });

  React.useEffect(() => {
    Promise.all([
      adminService.getRolesList(),
      adminService.getUsersList()
    ]).then(([roles, users]) => {
      const activeUsers = users.filter((u: any) => u.is_active).length;
      setStats({
        totalRoles: roles.length,
        totalUsers: users.length,
        activeUsers,
        inactiveUsers: users.length - activeUsers,
      });
    }).catch(() => {});
  }, []);

  return (
    <div className={ADMIN_PAGE_SHELL}>
      <div className={ADMIN_CONTENT}>
        <AdminPageHeader
          breadcrumb={
            <nav className="flex items-center gap-1.5 text-xs text-slate-400">
              <span>Admin</span>
              <span>/</span>
              <span className="font-medium text-slate-600">การตั้งค่า</span>
            </nav>
          }
          title="การตั้งค่าระบบ"
          subtitle="In-memory demo — resets on refresh"
        />

        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
          {ACTION_CARDS.map((card) => {
            const Icon = card.icon;
            return (
              <button
                key={card.title}
                type="button"
                onClick={() => router.push(card.href)}
                className={`flex items-center gap-4 text-left transition-colors hover:border-blue-200 hover:bg-blue-50/30 ${APP_CARD}`}
              >
                <div
                  className={`flex size-9 shrink-0 items-center justify-center rounded-xl ${card.iconBg}`}
                >
                  <Icon className={`size-5 ${card.iconColor}`} />
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-800">{card.title}</p>
                  <p className="text-xs text-slate-500">{card.subtitle}</p>
                </div>
              </button>
            );
          })}
        </div>

        <StatCardGrid columns={4}>
          <AppStatCard
            label="บทบาททั้งหมด"
            value={stats.totalRoles}
            icon={Shield}
            iconBg="bg-indigo-50"
            iconColor="text-indigo-600"
          />
          <AppStatCard
            label="ผู้ใช้งานทั้งหมด"
            value={stats.totalUsers}
            icon={Users}
            iconBg="bg-blue-50"
            iconColor="text-blue-600"
          />
          <AppStatCard
            label="ใช้งาน"
            value={stats.activeUsers}
            icon={UserCheck}
            iconBg="bg-emerald-50"
            iconColor="text-emerald-600"
          />
          <AppStatCard
            label="ปิดใช้งาน"
            value={stats.inactiveUsers}
            icon={UserX}
            iconBg="bg-rose-50"
            iconColor="text-rose-600"
          />
        </StatCardGrid>

        <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
          {NAV_CARDS.map((card) => {
            const Icon = card.icon;
            const count = stats[card.countKey];
            return (
              <Link
                key={card.href}
                href={card.href}
                className={`group flex items-start gap-4 transition-colors hover:bg-blue-50/30 ${APP_CARD}`}
              >
                <div
                  className={`flex size-11 shrink-0 items-center justify-center rounded-xl ${card.iconBg}`}
                >
                  <Icon className={`size-6 ${card.iconColor}`} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <h2 className="text-base font-bold text-slate-800">{card.title}</h2>
                    <span
                      className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-bold ring-1 ${card.badgeBg}`}
                    >
                      {count} {card.countLabel}
                    </span>
                  </div>
                  <p className="mt-1 text-sm text-slate-500">{card.description}</p>
                </div>
                <ChevronRight className="mt-1 size-5 shrink-0 text-slate-300 transition-colors group-hover:text-blue-600" />
              </Link>
            );
          })}
        </div>
      </div>
    </div>
  );
}

