"use client";

import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { Suspense, useEffect, useMemo, useState } from "react";
import {
  Briefcase,
  Building2,
  Inbox,
  LayoutTemplate,
  ListOrdered,
  Loader2,
  Plus,
  Signature,
  Workflow,
  X,
} from "lucide-react";
import { useToast } from "@views/components/providers/ToastProvider";
import { swalConfirm } from "@/lib/swal";
import { useSidebar } from "@views/components/providers/SidebarProvider";
import { useAuth } from "@views/components/providers/AuthProvider";
import { api } from "@/lib";
import { adminService } from "@/controllers/services/admin.service";
import {
  ROLE_OPTIONS,
  type DepartmentRecord,
  type DocumentTypeRecord,
  type MasterDocumentTypeRecord,
  type PositionRecord,
  type RoleOption,
  type SignatureRecord,
  type WorkflowRecord,
} from "@views/features/master-data";
import {
  countUsersInDepartment,
  countUsersWithPosition,
  formatApproverLabel,
  getApproverUsers,
  LEVEL_OPTIONS,
} from "@views/features/roles-users";
import {
  DocumentRunningTab,
  WorkflowTab,
} from "@views/features/master-data/components";
import { useSignatures } from "@views/components/providers/SignatureProvider";
import {
  InactiveFilterCheckbox,
  MD_MASTER_ADD_BTN,
  MD_SECTION,
  MD_SIDEBAR_ICON,
  MD_SIDEBAR_ITEM,
  MD_SIDEBAR_ITEM_ACTIVE,
  MD_SIDEBAR_NAV,
  MD_TD,
  MD_TD_ACTION,
  MD_TD_MUTED,
  MD_TD_NUM,
  MD_TD_NUM_RIGHT,
  MD_TD_STATUS,
  MD_TD_STICKY,
  MD_TH,
  MD_TH_ACTION,
  MD_TH_RIGHT,
  MD_TH_STATUS,
  MD_TH_STICKY,
  MD_TABLE,
  MD_THEAD,
  MD_TR,
  MasterDataLayout,
  MasterDataMobileCardList,
  MasterDataTableWrap,
  RowActions,
  StatCards,
  StatusBadge,
  StatusFormToggle,
} from "@views/components/ui/admin";

type TabKey =
  "doctype" | "department" | "position" | "workflow" | "signature" | "running";
type DataTabKey = Exclude<TabKey, "running">;

interface DocTypeRow extends MasterDocumentTypeRecord {}
interface DepartmentRow extends DepartmentRecord {}
interface PositionRow extends PositionRecord {}
interface WorkflowRow extends WorkflowRecord {}
interface SignatureRow extends SignatureRecord {}

type TabData = {
  doctype: DocTypeRow[];
  department: DepartmentRow[];
  position: PositionRow[];
  workflow: WorkflowRow[];
  signature: SignatureRow[];
};

const TABS: { key: TabKey; label: string; icon: React.ElementType }[] = [
  { key: "department", label: "แผนก", icon: Building2 },
  { key: "position", label: "ตำแหน่ง", icon: Briefcase },
  { key: "workflow", label: "Workflow", icon: Workflow },
  { key: "signature", label: "ลายเซ็น", icon: Signature },
];

function uid() {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

const EMPTY_TAB_DATA: TabData = {
  doctype: [],
  department: [],
  position: [],
  workflow: [],
  signature: [],
};
const APPROVER_USERS: any[] = [];

type FormState = {
  name: string;
  prefix: string;
  docCount: string;
  code: string;
  fieldsCount: string;
  employeeCount: string;
  level: string;
  department: string;
  levels: string;
  approverCount: string;
  approverName: string;
  position: string;
  signedCount: string;
  imageUrl?: string;
  isActive: boolean;
  workflowApprovers: string[];
  workflowSteps: RoleOption[];
};

type FormErrors = Record<string, string>;

const PREFIX_RE = /^[A-Z0-9]{2,5}$/;
const DEPT_CODE_RE = /^[A-Z]{2,6}$/;

function syncApproverRows(levelCount: number, current: string[]): string[] {
  if (current.length === levelCount) return current;
  if (current.length > levelCount) return current.slice(0, levelCount);
  return [...current, ...Array(levelCount - current.length).fill("")];
}

function validateDoctypeName(name: string): string | undefined {
  const trimmed = name.trim();
  if (!trimmed) return "กรุณากรอกชื่อประเภทเอกสาร";
  if (trimmed.length < 2) return "ชื่อต้องมีอย่างน้อย 2 ตัวอักษร";
  if (trimmed.length > 50) return "ชื่อต้องไม่เกิน 50 ตัวอักษร";
  return undefined;
}

function validateDoctypePrefix(
  prefix: string,
  rows: DocTypeRow[],
  editingId: string | null,
): string | undefined {
  const normalized = prefix.trim().toUpperCase();
  if (!normalized) return "กรุณากรอก Prefix";
  if (!PREFIX_RE.test(normalized))
    return "Prefix ต้องเป็นตัวอักษรหรือตัวเลข 2-5 ตัว";
  if (
    rows.some(
      (r) => r.prefix.toUpperCase() === normalized && r.id !== editingId,
    )
  ) {
    return "รหัสนี้ถูกใช้งานแล้ว";
  }
  return undefined;
}

function validateDoctypeForm(
  form: FormState,
  rows: DocTypeRow[],
  editingId: string | null,
): FormErrors {
  const errors: FormErrors = {};
  const nameError = validateDoctypeName(form.name);
  const prefixError = validateDoctypePrefix(form.prefix, rows, editingId);
  if (nameError) errors.name = nameError;
  if (prefixError) errors.prefix = prefixError;
  return errors;
}

function doctypeFormSnapshot(form: FormState) {
  return JSON.stringify({
    name: form.name,
    prefix: form.prefix,
    isActive: form.isActive,
  });
}

function modalFormSnapshot(form: FormState, tab: TabKey): string {
  switch (tab) {
    case "doctype":
      return doctypeFormSnapshot(form);
    case "department":
      return JSON.stringify({
        name: form.name,
        code: form.code,
        isActive: form.isActive,
      });
    case "position":
      return JSON.stringify({
        name: form.name,
        level: form.level,
        department: form.department,
        isActive: form.isActive,
      });
    case "workflow": {
      const levelCount = Number(form.levels) === 4 ? 4 : 3;
      return JSON.stringify({
        name: form.name,
        levels: form.levels,
        workflowApprovers: form.workflowApprovers.slice(0, levelCount),
        isActive: form.isActive,
      });
    }
    case "signature":
      return JSON.stringify({
        approverName: form.approverName,
        isActive: form.isActive,
      });
    default:
      return "";
  }
}

function validateDepartmentName(
  name: string,
  rows: DepartmentRow[],
  editingId: string | null,
): string | undefined {
  const trimmed = name.trim();
  if (!trimmed) return "กรุณากรอกชื่อแผนก";
  if (trimmed.length < 2) return "ชื่อแผนกต้องมีอย่างน้อย 2 ตัวอักษร";
  if (trimmed.length > 50) return "ชื่อแผนกต้องไม่เกิน 50 ตัวอักษร";
  if (rows.some((r) => r.name === trimmed && r.id !== editingId)) {
    return "ชื่อแผนกนี้ถูกใช้แล้ว";
  }
  return undefined;
}

function validateDepartmentCode(
  code: string,
  rows: DepartmentRow[],
  editingId: string | null,
): string | undefined {
  const normalized = code.trim().toUpperCase();
  if (!normalized) return "กรุณากรอกรหัส";
  if (!DEPT_CODE_RE.test(normalized)) return "รหัสต้องเป็นตัวพิมพ์ใหญ่ 2-6 ตัว";
  if (
    rows.some((r) => r.code.toUpperCase() === normalized && r.id !== editingId)
  ) {
    return "รหัสนี้ถูกใช้งานแล้ว";
  }
  return undefined;
}

function validateDepartmentForm(
  form: FormState,
  rows: DepartmentRow[],
  editingId: string | null,
): FormErrors {
  const errors: FormErrors = {};
  const nameError = validateDepartmentName(form.name, rows, editingId);
  const codeError = validateDepartmentCode(form.code, rows, editingId);
  if (nameError) errors.name = nameError;
  if (codeError) errors.code = codeError;
  return errors;
}

function validatePositionName(
  name: string,
  rows: PositionRow[],
  editingId: string | null,
): string | undefined {
  const trimmed = name.trim();
  if (!trimmed) return "กรุณากรอกชื่อตำแหน่ง";
  if (trimmed.length < 2) return "ชื่อตำแหน่งต้องมีอย่างน้อย 2 ตัวอักษร";
  if (rows.some((r) => r.name === trimmed && r.id !== editingId)) {
    return "ชื่อตำแหน่งนี้ถูกใช้แล้ว";
  }
  return undefined;
}

function validatePositionForm(
  form: FormState,
  rows: PositionRow[],
  editingId: string | null,
): FormErrors {
  const errors: FormErrors = {};
  const nameError = validatePositionName(form.name, rows, editingId);
  if (nameError) errors.name = nameError;
  return errors;
}

function validateWorkflowForm(
  form: FormState,
  rows: WorkflowRow[],
  editingId: string | null,
): FormErrors {
  const errors: FormErrors = {};
  const name = form.name.trim();

  if (!name) errors.name = "กรุณากรอกชื่อ Workflow";
  else if (name.length < 2) errors.name = "ชื่อต้องมีอย่างน้อย 2 ตัวอักษร";
  else if (rows.some((r) => r.name === name && r.id !== editingId)) {
    errors.name = "ชื่อ Workflow นี้ถูกใช้แล้ว";
  }

  return errors;
}

function validateSignatureForm(
  form: FormState,
  rows: SignatureRow[],
  editingId: string | null,
): FormErrors {
  const errors: FormErrors = {};

  if (!form.approverName) errors.approverName = "กรุณาเลือกผู้อนุมัติ";
  else if (
    rows.some((r) => r.approverName === form.approverName && r.id !== editingId)
  ) {
    errors.approverName = "ผู้อนุมัตินี้มีลายเซ็นในระบบแล้ว";
  }

  return errors;
}

const emptyForm = (): FormState => ({
  name: "",
  prefix: "PR",
  docCount: "0",
  code: "",
  fieldsCount: "0",
  employeeCount: "0",
  level: "L1",
  department: "",
  levels: "3",
  approverCount: "1",
  approverName: "",
  position: "",
  signedCount: "0",
  imageUrl: "",
  isActive: true,
  workflowApprovers: ["", "", ""],
  workflowSteps: ["หัวหน้าแผนก", "ผู้บริหาร", "ผู้ดูแลระบบ"],
});

function buildEmptyForm(departments: DepartmentRow[]): FormState {
  const base = emptyForm();
  const firstDept = departments.find((d) => d.isActive);
  return {
    ...base,
    department: firstDept?.name ?? "",
    workflowApprovers: syncApproverRows(3, []),
  };
}

function getDeleteGuard(
  tab: DataTabKey,
  row: TabData[DataTabKey][number],
  data: TabData,
): { blocked: boolean; tooltip: string } {
  if (tab === "department") {
    const r = row as DepartmentRow;
    const n = Math.max(r.employeeCount, countUsersInDepartment(r.name));
    if (n > 0) {
      return {
        blocked: true,
        tooltip: `ไม่สามารถลบได้ เนื่องจากมีพนักงาน ${n} คนอยู่ในแผนกนี้ — กรุณาปิดใช้งานแทน`,
      };
    }
  }
  if (tab === "position") {
    const r = row as PositionRow;
    const n = countUsersWithPosition(r.name);
    if (n > 0) {
      return {
        blocked: true,
        tooltip: `ไม่สามารถลบได้ เนื่องจากมีพนักงาน ${n} คนใช้ตำแหน่งนี้อยู่ — กรุณาปิดใช้งานแทน`,
      };
    }
  }
  if (tab === "signature") {
    // Note: Signature dependencies should be checked via backend API eventually.
  }
  return { blocked: false, tooltip: "ลบรายการ" };
}

export default function MasterDataPage() {
  return (
    <Suspense fallback={<div className="h-fit w-full" />}>
      <MasterDataPageContent />
    </Suspense>
  );
}

function MasterDataPageContent() {
  const searchParams = useSearchParams();
  const { showToast } = useToast();
  const { isOpen } = useSidebar();
  const { user } = useAuth();
  const hasPerm = (itemKey: string, action: string = "view") =>
    user?.role === "Administrator" ||
    !!user?.permissions?.includes(`masterdata.${itemKey}:${action}`);

  const { signatures, saveSignatureRecord, toggleSignatureActive } =
    useSignatures();
  const [activeTab, setActiveTab] = useState<TabKey>("department");
  const [roleNames, setRoleNames] = useState<string[]>([]);
  useEffect(() => {
    api
      .get<any[]>("/api/admin/roles")
      .then((r) =>
        setRoleNames(
          r.data.filter((role) => role.is_active).map((role) => role.name),
        ),
      )
      .catch(() => {});
  }, []);
  const [data, setData] = useState<TabData>(EMPTY_TAB_DATA);
  const [showDeleted, setShowDeleted] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(emptyForm());
  const [formErrors, setFormErrors] = useState<FormErrors>({});
  const [modalBaseline, setModalBaseline] = useState("");
  const [saving, setSaving] = useState(false);
  const [previewSignatureUrl, setPreviewSignatureUrl] = useState<string | null>(
    null,
  );
  const [previewSignatureName, setPreviewSignatureName] = useState<string>("");

  useEffect(() => {
    const tab = searchParams.get("tab");
    const valid: TabKey[] = [
      "department",
      "position",
      "workflow",
      "signature",
      "running",
    ];
    if (tab === "formtype") {
      setActiveTab("department");
    } else if (tab && valid.includes(tab as TabKey)) {
      setActiveTab(tab as TabKey);
    }
  }, [searchParams]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [depts, pos, docTs, wfs, sigs] = await Promise.all([
          adminService.getDepartmentsList().catch(() => []),
          adminService.getPositionsList().catch(() => []),
          adminService.getDocumentTypesList().catch(() => []),
          adminService.getApprovalWorkflowsList().catch(() => []),
          adminService.getSignaturesList().catch(() => []),
        ]);

        setData((prev) => ({
          ...prev,
          department:
            depts.length > 0
              ? depts.map((d: any) => ({
                  id: d.id,
                  name: d.name,
                  code:
                    d.code && d.code !== "แผน"
                      ? d.code
                      : (() => {
                          const name = d.name || "";
                          if (name.includes("คลัง") || name.includes("จัดส่ง"))
                            return "WH";
                          if (name.includes("จัดซื้อ")) return "PUR";
                          if (name.includes("ทรัพยากรบุคคล")) return "HR";
                          if (
                            name.includes("เทคโนโลยี") ||
                            name.includes("สารสนเทศ")
                          )
                            return "IT";
                          if (
                            name.includes("บัญชี") ||
                            name.includes("การเงิน")
                          )
                            return "ACC";
                          if (name.includes("ผลิต")) return "PROD";
                          if (
                            name.includes("วิศวกรรม") ||
                            name.includes("ซ่อมบำรุง")
                          )
                            return "ENG";
                          if (name.includes("บริหาร")) return "GA";
                          if (name.includes("ประกันคุณภาพ")) return "QA";
                          const clean = name.replace(/^แผนก/, "").trim();
                          return clean.substring(0, 4).toUpperCase() || "DEPT";
                        })(),
                  employeeCount: d.employeeCount || 0,
                  isActive: d.is_active,
                }))
              : prev.department,
          position:
            pos.length > 0
              ? pos.map((p: any) => ({
                  id: p.id,
                  name: p.name,
                  level: p.level || "L1",
                  isActive: p.is_active,
                  employeeCount: p._count?.users || 0,
                }))
              : prev.position,
          doctype:
            docTs.length > 0
              ? docTs.map((dt: any) => ({
                  id: dt.id,
                  name: dt.type_name,
                  prefix: dt.prefix,
                  docCount: dt.doc_count || 0,
                  isActive: dt.is_active,
                }))
              : prev.doctype,
          workflow: (wfs as any[]).length > 0 ? (wfs as any[]) : prev.workflow,
          signature:
            (sigs as any[]).length > 0 ? (sigs as any[]) : prev.signature,
        }));
      } catch (err) {
        console.error("Failed to fetch master data", err);
      }
    };

    fetchData();
  }, []);

  const effectiveSignatures = useMemo(() => {
    return data.signature.length > 0 ? data.signature : signatures;
  }, [data.signature, signatures]);

  const rows = useMemo(() => {
    if (activeTab === "running") return [];
    const list =
      activeTab === "signature"
        ? effectiveSignatures
        : data[activeTab as DataTabKey];
    return showDeleted
      ? list.filter((r) => !r.isActive)
      : list.filter((r) => r.isActive);
  }, [data, activeTab, showDeleted, effectiveSignatures]);

  const tabLabel =
    TABS.find((t) => t.key === activeTab)?.label ?? "Master Data";
  const tabStats = useMemo(() => {
    if (activeTab === "running") return { total: 0, active: 0, deleted: 0 };
    const list =
      activeTab === "signature"
        ? effectiveSignatures
        : data[activeTab as DataTabKey];
    return {
      total: list.length,
      active: list.filter((r) => r.isActive).length,
      deleted: list.filter((r) => !r.isActive).length,
    };
  }, [data, activeTab, effectiveSignatures]);

  const openAdd = () => {
    setEditingId(null);
    const nextForm = buildEmptyForm(data.department);
    setForm(nextForm);
    setFormErrors({});
    setModalBaseline(modalFormSnapshot(nextForm, activeTab));
    setModalOpen(true);
  };

  const openEdit = (id: string) => {
    setEditingId(id);
    const list =
      activeTab === "signature"
        ? effectiveSignatures
        : data[activeTab as DataTabKey];
    const row = list.find((r) => r.id === id);
    if (!row) return;

    let nextForm: FormState;

    if (activeTab === "workflow") {
      const wf = row as WorkflowRow;
      const initialSteps: RoleOption[] =
        wf.steps && wf.steps.length > 0
          ? [...wf.steps]
          : ["หัวหน้าแผนก", "ผู้บริหาร", "ผู้ดูแลระบบ"];
      while (initialSteps.length < wf.levels) {
        initialSteps.push(ROLE_OPTIONS[0]);
      }
      nextForm = {
        name: wf.name,
        prefix: wf.prefix || "PR",
        docCount: "0",
        code: "",
        fieldsCount: "0",
        employeeCount: "0",
        level: "L1",
        department: "",
        levels: String(wf.levels),
        approverCount: String(wf.approverCount),
        approverName: "",
        position: "",
        signedCount: "0",
        isActive: wf.isActive,
        workflowApprovers: syncApproverRows(wf.levels, [...wf.approvers]),
        workflowSteps: initialSteps.slice(0, wf.levels),
      };
    } else if (activeTab === "signature") {
      const sig = row as SignatureRow;
      nextForm = {
        name: "",
        prefix: "",
        docCount: "0",
        code: "",
        fieldsCount: "0",
        employeeCount: "0",
        level: "L1",
        department: "",
        levels: "3",
        approverCount: "1",
        approverName: sig.approverName,
        position: sig.position,
        signedCount: String(sig.signedCount),
        imageUrl: sig.imageUrl || "",
        isActive: sig.isActive,
        workflowApprovers: ["", "", ""],
        workflowSteps: ["หัวหน้าแผนก", "ผู้บริหาร"],
      };
    } else {
      nextForm = {
        name: "name" in row ? row.name : "",
        prefix: "prefix" in row ? row.prefix : "",
        docCount: "docCount" in row ? String(row.docCount) : "0",
        code: "code" in row ? row.code : "",
        fieldsCount: "fieldsCount" in row ? String(row.fieldsCount) : "0",
        employeeCount: "employeeCount" in row ? String(row.employeeCount) : "0",
        level: "level" in row ? row.level : "L1",
        department: "department" in row ? String(row.department) : "",
        levels: "levels" in row ? String(row.levels) : "3",
        approverCount: "approverCount" in row ? String(row.approverCount) : "1",
        approverName: "approverName" in row ? row.approverName : "",
        position: "position" in row ? row.position : "",
        signedCount: "signedCount" in row ? String(row.signedCount) : "0",
        isActive: row.isActive,
        workflowApprovers: ["", "", ""],
        workflowSteps: ["หัวหน้าแผนก", "ผู้บริหาร"],
      };
    }

    setForm(nextForm);
    setModalBaseline(modalFormSnapshot(nextForm, activeTab));
    setFormErrors({});
    setModalOpen(true);
  };

  const isModalDirty = useMemo(() => {
    if (!modalOpen) return false;
    return modalFormSnapshot(form, activeTab) !== modalBaseline;
  }, [modalOpen, form, activeTab, modalBaseline]);

  const isModalValid = useMemo(() => {
    switch (activeTab) {
      case "doctype":
        return (
          Object.keys(validateDoctypeForm(form, data.doctype, editingId))
            .length === 0
        );
      case "department":
        return (
          Object.keys(validateDepartmentForm(form, data.department, editingId))
            .length === 0
        );
      case "position":
        return (
          Object.keys(validatePositionForm(form, data.position, editingId))
            .length === 0
        );
      case "workflow":
        return (
          Object.keys(validateWorkflowForm(form, data.workflow, editingId))
            .length === 0
        );
      case "signature":
        return (
          Object.keys(validateSignatureForm(form, data.signature, editingId))
            .length === 0
        );
      default:
        return true;
    }
  }, [activeTab, form, data, editingId]);

  const closeModal = async () => {
    if (isModalDirty) {
      const confirmed = await swalConfirm({
        title: "ปิดหน้าต่างโดยไม่บันทึก?",
        text: "ข้อมูลที่คุณแก้ไขยังไม่ได้บันทึก คุณต้องการปิดหน้าต่างนี้หรือไม่?",
        confirmButtonText: "ปิดหน้าต่าง",
        cancelButtonText: "ยกเลิก",
        icon: "warning",
      });
      if (!confirmed) return;
    }
    setModalOpen(false);
    setEditingId(null);
    setForm(buildEmptyForm(data.department));
    setFormErrors({});
    setModalBaseline("");
  };

  const validateCurrentTab = (): FormErrors => {
    switch (activeTab) {
      case "doctype":
        return validateDoctypeForm(form, data.doctype, editingId);
      case "department":
        return validateDepartmentForm(form, data.department, editingId);
      case "position":
        return validatePositionForm(form, data.position, editingId);
      case "workflow":
        return validateWorkflowForm(form, data.workflow, editingId);
      case "signature":
        return validateSignatureForm(form, data.signature, editingId);
      default:
        return {};
    }
  };

  const handleSave = async () => {
    const errors = validateCurrentTab();
    setFormErrors(errors);
    if (Object.keys(errors).length > 0) return;

    const wasEditing = !!editingId;
    setSaving(true);

    let persistedId = editingId;
    try {
      if (activeTab === "department") {
        if (wasEditing && editingId) {
          await adminService.updateDepartment(editingId, {
            name: form.name.trim(),
            is_active: form.isActive,
          });
        } else {
          persistedId = (await adminService.createDepartment(form.name.trim()))
            .id;
        }
      } else if (activeTab === "position") {
        if (wasEditing && editingId) {
          await adminService.updatePosition(editingId, {
            name: form.name.trim(),
            level: form.level,
            is_active: form.isActive,
          });
        } else {
          persistedId = (
            await adminService.createPosition({
              name: form.name.trim(),
              level: form.level,
            })
          ).id;
        }
      } else if (activeTab === "doctype") {
        if (wasEditing && editingId) {
          await adminService.updateDocumentType(editingId, {
            type_name: form.name.trim(),
            prefix: form.prefix.trim().toUpperCase(),
            is_active: form.isActive,
          });
        } else {
          persistedId = (
            await adminService.createDocumentType({
              type_name: form.name.trim(),
              prefix: form.prefix.trim().toUpperCase(),
            })
          ).id;
        }
      } else if (activeTab === "workflow") {
        const num = Number(form.levels);
        const levels = num >= 1 && num <= 4 ? num : 3;
        const steps =
          form.workflowSteps && form.workflowSteps.length > 0
            ? [...form.workflowSteps.slice(0, levels)]
            : [];
        // Ensure steps array is filled up to levels
        while (steps.length < levels)
          steps.push((roleNames[0] || "") as RoleOption);

        const prefix = form.prefix || "PR";
        const docType = data.doctype.find(
          (d: any) =>
            d.id === editingId ||
            d.prefix === prefix ||
            d.typeName === form.name,
        );
        const targetDocTypeId = editingId || docType?.id;
        if (targetDocTypeId) {
          await adminService.updateApprovalWorkflow(targetDocTypeId, {
            levels,
            steps,
          });
        }
      } else if (activeTab === "signature") {
        const signatureId =
          editingId ||
          signatures.find((row) => row.approverName === form.approverName)?.id;
        if (!signatureId) throw new Error("กรุณาเลือกผู้ใช้ที่มีอยู่ในระบบ");
        if (form.imageUrl?.startsWith("data:") || !form.isActive)
          await api.patch(`/api/admin/signatures/${signatureId}`, {
            imageUrl: form.isActive ? form.imageUrl : null,
          });
        persistedId = signatureId;
      }
    } catch (err) {
      showToast(`Failed to save to database: ${String(err)}`, "error");
      setSaving(false);
      return; // Do not update local state on failure
    }

    const id = persistedId ?? editingId ?? uid();

    setData((prev) => {
      switch (activeTab) {
        case "doctype": {
          const list = [...prev.doctype];
          const idx = list.findIndex((r) => r.id === id);
          const row: DocTypeRow = {
            id,
            name: form.name.trim(),
            prefix: form.prefix.trim().toUpperCase(),
            docCount: idx >= 0 ? list[idx].docCount : 0,
            isActive: form.isActive,
          };
          if (idx >= 0) list[idx] = row;
          else list.push(row);
          return { ...prev, doctype: list };
        }
        case "department": {
          const list = [...prev.department];
          const idx = list.findIndex((r) => r.id === id);
          const row: DepartmentRow = {
            id,
            name: form.name.trim(),
            code: form.code.trim().toUpperCase(),
            employeeCount: idx >= 0 ? list[idx].employeeCount : 0,
            isActive: form.isActive,
          };
          if (idx >= 0) list[idx] = row;
          else list.push(row);
          return { ...prev, department: list };
        }
        case "position": {
          const list = [...prev.position];
          const idx = list.findIndex((r) => r.id === id);
          const row: PositionRow = {
            id,
            name: form.name.trim(),
            level: form.level,
            isActive: form.isActive,
          };
          if (idx >= 0) list[idx] = row;
          else list.push(row);
          return { ...prev, position: list };
        }
        case "workflow": {
          const list = [...prev.workflow];
          const idx = list.findIndex((r) => r.id === id);
          const num = Number(form.levels);
          const levels = num >= 1 && num <= 4 ? num : 3;
          const prefix = form.prefix || "PR";
          const steps: RoleOption[] =
            form.workflowSteps && form.workflowSteps.length > 0
              ? [...form.workflowSteps.slice(0, levels)]
              : [ROLE_OPTIONS[0]];
          while (steps.length < levels) {
            steps.push((roleNames[0] || "") as RoleOption);
          }

          const docType = data.doctype.find((d) => d.prefix === prefix);
          const documentTypeId =
            docType?.id ?? `doc-type-${prefix.toLowerCase()}`;

          const row: WorkflowRow = {
            id,
            documentTypeId,
            name: form.name.trim(),
            prefix,
            levels,
            approverCount: levels,
            approvers: idx >= 0 ? list[idx].approvers : [],
            steps,
            isActive: form.isActive,
          };
          if (idx >= 0) list[idx] = row;
          else list.push(row);

          return { ...prev, workflow: list };
        }
        case "signature": {
          const existing = signatures.find((r) => r.id === id);
          const row: SignatureRow = {
            id,
            approverName: form.approverName,
            position: form.position,
            signedCount: existing ? existing.signedCount : 0,
            isActive: form.isActive,
            imageUrl: form.imageUrl || existing?.imageUrl,
          };
          return {
            ...prev,
            signature: prev.signature.some((s) => s.id === row.id)
              ? prev.signature.map((s) => (s.id === row.id ? row : s))
              : [...prev.signature, row],
          };
        }
        default:
          return prev;
      }
    });

    setSaving(false);
    setModalOpen(false);
    setEditingId(null);
    setForm(buildEmptyForm(data.department));
    setFormErrors({});
    setModalBaseline("");
    showToast(
      wasEditing ? `แก้ไข${tabLabel}สำเร็จ` : `เพิ่ม${tabLabel}สำเร็จ`,
      "success",
    );
  };

  const softDelete = async (id: string) => {
    if (activeTab === "running") return;
    if (activeTab === "signature") {
      try {
        await api.patch(`/api/admin/signatures/${id}`, { imageUrl: null });
        toggleSignatureActive(id);
        setData((prev) => ({
          ...prev,
          signature: prev.signature.map((s) =>
            s.id === id ? { ...s, imageUrl: undefined, isActive: false } : s,
          ),
        }));
        showToast("ปิดใช้งานลายเซ็นแล้ว", "success");
      } catch (error) {
        showToast(String(error), "error");
      }
      return;
    }
    const row = data[activeTab as DataTabKey].find((r) => r.id === id);
    if (!row) return;
    const guard = getDeleteGuard(activeTab as DataTabKey, row, data);
    if (guard.blocked) return;
    if (!confirm("ยืนยันการลบรายการนี้?")) return;

    try {
      if (activeTab === "position") {
        await adminService.deletePosition(id);
      } else if (activeTab === "department") {
        await adminService.deleteDepartment(id);
      } else if (activeTab === "doctype") {
        await adminService.updateDocumentType(id, { is_active: false });
      } else if (activeTab === "workflow") {
        await api.patch(`/api/admin/workflows/${id}`, { is_active: false });
      }

      setData((prev) => ({
        ...prev,
        [activeTab]: prev[activeTab as DataTabKey].map((r) =>
          r.id === id ? { ...r, isActive: false } : r,
        ),
      }));
      showToast("ลบข้อมูลสำเร็จ", "success");
    } catch (err) {
      showToast("เกิดข้อผิดพลาดในการลบข้อมูล", "error");
    }
  };

  const restore = async (id: string) => {
    if (activeTab === "signature") {
      showToast("กรุณาแก้ไขและอัปโหลดรูปใหม่เพื่อเปิดใช้งานลายเซ็น", "error");
      return;
    }
    try {
      if (activeTab === "position") {
        await adminService.updatePosition(id, { is_active: true });
      } else if (activeTab === "department") {
        await adminService.updateDepartment(id, { is_active: true });
      } else if (activeTab === "doctype") {
        await adminService.updateDocumentType(id, { is_active: true });
      } else if (activeTab === "workflow") {
        await api.patch(`/api/admin/workflows/${id}`, { is_active: true });
      }

      setData((prev) => ({
        ...prev,
        [activeTab]: prev[activeTab as DataTabKey].map((r) =>
          r.id === id ? { ...r, isActive: true } : r,
        ),
      }));
      showToast("กู้คืนข้อมูลสำเร็จ", "success");
    } catch (err) {
      showToast("เกิดข้อผิดพลาดในการกู้คืนข้อมูล", "error");
    }
  };

  const signatureGuardData = useMemo(
    () => ({ ...data, signature: effectiveSignatures }),
    [data, effectiveSignatures],
  );

  const mobileRows = useMemo(() => {
    if (activeTab === "running" || activeTab === "workflow") return [];

    return rows.map((row) => {
      let canEdit = false;
      let canDelete = false;
      if (activeTab === "department") {
        canEdit = hasPerm("departments", "edit");
        canDelete = hasPerm("departments", "delete");
      } else if (activeTab === "position") {
        canEdit = hasPerm("positions", "edit");
        canDelete = hasPerm("positions", "delete");
      } else if (activeTab === "doctype") {
        canEdit = hasPerm("doc_types", "edit");
        canDelete = hasPerm("doc_types", "delete");
      } else if (activeTab === "signature") {
        canEdit = hasPerm("signatures", "edit");
        canDelete = hasPerm("signatures", "delete");
      }

      const guard = getDeleteGuard(
        activeTab as DataTabKey,
        row,
        signatureGuardData,
      );
      const actions =
        activeTab === "signature" ? undefined : row.isActive ? (
          <RowActions
            onEdit={canEdit ? () => openEdit(row.id) : undefined}
            onDelete={
              canDelete && activeTab !== "position"
                ? () => softDelete(row.id)
                : undefined
            }
            deleteBlocked={guard.blocked}
            deleteTooltip={guard.tooltip}
          />
        ) : (
          <RowActions onRestore={() => restore(row.id)} />
        );

      switch (activeTab) {
        case "doctype": {
          const r = row as DocTypeRow;
          return {
            id: r.id,
            title: r.name,
            badge: <StatusBadge active={r.isActive} />,
            fields: [
              { label: "Prefix", value: r.prefix },
              { label: "จำนวนเอกสาร", value: r.docCount },
            ],
            actions,
          };
        }
        case "department": {
          const r = row as DepartmentRow;
          return {
            id: r.id,
            title: r.name,
            badge: <StatusBadge active={r.isActive} />,
            fields: [
              { label: "รหัส", value: r.code },
              { label: "จำนวนพนักงาน", value: r.employeeCount },
            ],
            actions,
          };
        }
        case "position": {
          const r = row as PositionRow;
          return {
            id: r.id,
            title: r.name,
            badge: <StatusBadge active={r.isActive} />,
            fields: [
              { label: "ระดับ", value: r.level },
              { label: "จำนวนพนักงาน", value: r.employeeCount },
            ],
            actions,
          };
        }
        default: {
          const r = row as SignatureRow;
          return {
            id: r.id,
            title: r.approverName,
            badge: <StatusBadge active={r.isActive} />,
            fields: [
              { label: "ตำแหน่ง", value: r.position },
              { label: "จำนวนลงนาม", value: r.signedCount },
            ],
            actions,
          };
        }
      }
    });
  }, [rows, activeTab, signatureGuardData]);

  const inputCls =
    "w-full rounded-md border border-gray-200 px-3 py-2 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500";
  const thCls = MD_TH;
  const thSticky = MD_TH_STICKY;
  const thRight = MD_TH_RIGHT;
  const thAction = MD_TH_ACTION;
  const tdCls = MD_TD;
  const tdSticky = MD_TD_STICKY;
  const tdMuted = MD_TD_MUTED;
  const tdNum = MD_TD_NUM_RIGHT;

  const renderCells = (row: TabData[DataTabKey][number]) => {
    switch (activeTab) {
      case "doctype": {
        const r = row as DocTypeRow;
        return (
          <>
            <td className={tdSticky}>{r.name}</td>
            <td className={tdMuted}>{r.prefix}</td>
            <td className={tdNum}>{r.docCount}</td>
          </>
        );
      }
      case "department": {
        const r = row as DepartmentRow;
        const count = Math.max(
          Number(r.employeeCount || 0),
          countUsersInDepartment(r.name),
        );
        return (
          <>
            <td className={tdSticky}>{r.name}</td>
            <td className={tdMuted}>{r.code}</td>
            <td className={tdNum}>{count}</td>
          </>
        );
      }
      case "position": {
        const r = row as PositionRow;
        return (
          <>
            <td className={tdSticky}>{r.name}</td>
            <td className={tdNum}>{r.employeeCount || 0}</td>
          </>
        );
      }
      case "workflow": {
        const r = row as WorkflowRow;
        return (
          <>
            <td className={tdSticky}>{r.name}</td>
            <td className={MD_TD_NUM}>{r.levels}</td>
            <td className={tdNum}>{r.approverCount}</td>
          </>
        );
      }
      default: {
        const r = row as SignatureRow;
        return (
          <>
            <td className={tdSticky}>
              <div className="flex items-center gap-2.5">
                <div className="flex size-7 shrink-0 items-center justify-center rounded-full bg-blue-100 text-xs font-bold text-blue-700">
                  {r.approverName.slice(0, 2)}
                </div>
                <span className="font-medium text-slate-800">
                  {r.approverName}
                </span>
              </div>
            </td>
            <td className={tdMuted}>{r.position || "—"}</td>
            <td className={tdCls}>
              {r.imageUrl ? (
                <div className="flex items-center gap-2">
                  {/* Watermarked Thumbnail wrapper ready for backend integration */}
                  {/* Note for BE: The API endpoint rendering this image should return a dynamically watermarked image by default */}
                  <div className="relative overflow-hidden rounded border border-slate-200 bg-white p-1 shadow-2xs hover:scale-105 transition-transform cursor-pointer">
                    <img
                      src={r.imageUrl}
                      alt={r.approverName}
                      onClick={() => {
                        setPreviewSignatureUrl(r.imageUrl || null);
                        setPreviewSignatureName(r.approverName);
                      }}
                      className="h-8 max-w-[120px] object-contain opacity-75"
                      title="คลิกเพื่อดูภาพขนาดใหญ่"
                    />
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none select-none bg-red-500/5">
                      <span className="text-[7px] font-extrabold text-red-600/30 uppercase tracking-tighter rotate-[-12deg] whitespace-nowrap">
                        PREVIEW ONLY
                      </span>
                    </div>
                  </div>
                  <span className="text-[11px] font-medium text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded border border-emerald-200/60">
                    มีลายเซ็น
                  </span>
                </div>
              ) : (
                <span className="inline-flex items-center gap-1 text-[11px] font-medium text-slate-400 bg-slate-100 px-2.5 py-1 rounded-md border border-slate-200/60">
                  ยังไม่อัปโหลด
                </span>
              )}
            </td>
            <td className={tdNum}>{r.signedCount}</td>
          </>
        );
      }
    }
  };

  const renderHeaders = () => {
    switch (activeTab) {
      case "doctype":
        return (
          <>
            <th className={thSticky}>ชื่อ</th>
            <th className={thCls}>Prefix</th>
            <th className={thRight}>จำนวนเอกสาร</th>
          </>
        );
      case "department":
        return (
          <>
            <th className={thSticky}>ชื่อแผนก</th>
            <th className={thCls}>รหัส</th>
            <th className={thRight}>จำนวนพนักงาน</th>
          </>
        );
      case "position":
        return (
          <>
            <th className={thSticky}>ชื่อตำแหน่ง</th>
            <th className={thRight}>จำนวนพนักงาน</th>
          </>
        );
      case "workflow":
        return (
          <>
            <th className={thSticky}>ชื่อ Workflow</th>
            <th className={`${thCls} text-center`}>จำนวน Level</th>
            <th className={thRight}>ผู้อนุมัติ</th>
          </>
        );
      default:
        return (
          <>
            <th className={thSticky}>ชื่อผู้ลงนาม / พนักงาน</th>
            <th className={thCls}>ตำแหน่ง</th>
            <th className={thCls}>ตัวอย่างลายเซ็น</th>
            <th className={thRight}>จำนวนลงนาม</th>
          </>
        );
    }
  };

  const inputErrorCls =
    "w-full rounded-md border border-red-300 px-3 py-2 text-sm text-slate-700 outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500";

  const activeDepartments = useMemo(
    () => data.department.filter((d) => d.isActive),
    [data.department],
  );

  const setFieldError = (key: string, err: string | undefined) => {
    setFormErrors((prev) => {
      const next = { ...prev };
      if (err) next[key] = err;
      else delete next[key];
      return next;
    });
  };

  const clearError = (key: string) => {
    if (formErrors[key]) {
      setFormErrors((e) => {
        const next = { ...e };
        delete next[key];
        return next;
      });
    }
  };

  const renderStatusToggle = () => (
    <StatusFormToggle
      active={form.isActive}
      onChange={(isActive) => setForm((f) => ({ ...f, isActive }))}
    />
  );

  const renderReadOnlyCount = (label: string, value: string, hint: string) => (
    <div className="mb-3">
      <label className="mb-1.5 block text-xs text-slate-500">{label}</label>
      <div className="w-full rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-slate-500">
        {value}
      </div>
      <p className="mt-1 text-xs text-slate-400">{hint}</p>
    </div>
  );

  const renderFormFields = () => {
    if (activeTab === "doctype") {
      const prefixPreview = form.prefix.trim().toUpperCase() || "XX";
      return (
        <>
          <div className="mb-3">
            <label className="mb-1.5 block text-xs text-slate-500">ชื่อ</label>
            <div className="relative">
              <input
                type="text"
                value={form.name}
                maxLength={50}
                onChange={(e) => {
                  const value = e.target.value.slice(0, 50);
                  setForm((f) => ({ ...f, name: value }));
                  if (formErrors.name) {
                    const err = validateDoctypeName(value);
                    setFormErrors((prev) => {
                      const next = { ...prev };
                      if (err) next.name = err;
                      else delete next.name;
                      return next;
                    });
                  }
                }}
                onBlur={() => {
                  const err = validateDoctypeName(form.name);
                  setFormErrors((prev) => {
                    const next = { ...prev };
                    if (err) next.name = err;
                    else delete next.name;
                    return next;
                  });
                }}
                className={`${formErrors.name ? inputErrorCls : inputCls} pr-14`}
              />
              <span className="pointer-events-none absolute bottom-2 right-2 text-xs text-slate-400">
                {form.name.length}/50
              </span>
            </div>
            {formErrors.name && (
              <p className="mt-1 text-xs text-red-500">{formErrors.name}</p>
            )}
          </div>
          <div className="mb-3">
            <label className="mb-1.5 block text-xs text-slate-500">
              Prefix
            </label>
            <input
              type="text"
              value={form.prefix}
              maxLength={5}
              onChange={(e) => {
                const value = e.target.value
                  .toUpperCase()
                  .replace(/[^A-Z0-9]/g, "")
                  .slice(0, 5);
                setForm((f) => ({ ...f, prefix: value }));
                if (formErrors.prefix) {
                  const err = validateDoctypePrefix(
                    value,
                    data.doctype,
                    editingId,
                  );
                  setFormErrors((prev) => {
                    const next = { ...prev };
                    if (err) next.prefix = err;
                    else delete next.prefix;
                    return next;
                  });
                }
              }}
              onBlur={() => {
                const err = validateDoctypePrefix(
                  form.prefix,
                  data.doctype,
                  editingId,
                );
                setFormErrors((prev) => {
                  const next = { ...prev };
                  if (err) next.prefix = err;
                  else delete next.prefix;
                  return next;
                });
              }}
              className={formErrors.prefix ? inputErrorCls : inputCls}
            />
            <p className="mt-1 text-xs text-slate-400">
              ตัวอย่าง: {prefixPreview}-2569-0001
            </p>
            {formErrors.prefix && (
              <p className="mt-1 text-xs text-red-500">{formErrors.prefix}</p>
            )}
          </div>
          {editingId &&
            renderReadOnlyCount(
              "จำนวนเอกสาร",
              form.docCount,
              "นับอัตโนมัติจากเอกสารที่ใช้ประเภทนี้",
            )}
          {renderStatusToggle()}
        </>
      );
    }
    if (activeTab === "department") {
      return (
        <>
          <div className="mb-3">
            <label className="mb-1.5 block text-xs text-slate-500">
              ชื่อแผนก
            </label>
            <div className="relative">
              <input
                type="text"
                value={form.name}
                maxLength={50}
                onChange={(e) => {
                  const value = e.target.value.slice(0, 50);
                  setForm((f) => ({ ...f, name: value }));
                  if (formErrors.name) {
                    setFieldError(
                      "name",
                      validateDepartmentName(value, data.department, editingId),
                    );
                  }
                }}
                onBlur={() =>
                  setFieldError(
                    "name",
                    validateDepartmentName(
                      form.name,
                      data.department,
                      editingId,
                    ),
                  )
                }
                className={`${formErrors.name ? inputErrorCls : inputCls} pr-14`}
              />
              <span className="pointer-events-none absolute bottom-2 right-2 text-xs text-slate-400">
                {form.name.length}/50
              </span>
            </div>
            {formErrors.name && (
              <p className="mt-1 text-xs text-red-500">{formErrors.name}</p>
            )}
          </div>
          <div className="mb-3">
            <label className="mb-1.5 block text-xs text-slate-500">รหัส</label>
            <input
              type="text"
              value={form.code}
              maxLength={6}
              onChange={(e) => {
                const value = e.target.value
                  .toUpperCase()
                  .replace(/[^A-Z]/g, "")
                  .slice(0, 6);
                setForm((f) => ({ ...f, code: value }));
                if (formErrors.code) {
                  setFieldError(
                    "code",
                    validateDepartmentCode(value, data.department, editingId),
                  );
                }
              }}
              onBlur={() =>
                setFieldError(
                  "code",
                  validateDepartmentCode(form.code, data.department, editingId),
                )
              }
              className={formErrors.code ? inputErrorCls : inputCls}
            />
            {formErrors.code && (
              <p className="mt-1 text-xs text-red-500">{formErrors.code}</p>
            )}
          </div>
          {editingId &&
            renderReadOnlyCount(
              "จำนวนพนักงาน",
              form.employeeCount,
              "นับอัตโนมัติจากพนักงานในแผนก",
            )}
          {renderStatusToggle()}
        </>
      );
    }
    if (activeTab === "position") {
      return (
        <>
          <Field
            label="ชื่อตำแหน่ง"
            value={form.name}
            onChange={(v) => {
              setForm((f) => ({ ...f, name: v }));
              if (formErrors.name) {
                setFieldError(
                  "name",
                  validatePositionName(v, data.position, editingId),
                );
              }
            }}
            onBlur={() =>
              setFieldError(
                "name",
                validatePositionName(form.name, data.position, editingId),
              )
            }
            inputClassName={formErrors.name ? inputErrorCls : inputCls}
            error={formErrors.name}
          />

          {renderStatusToggle()}
        </>
      );
    }
    if (activeTab === "workflow") {
      const levelCount = Number(form.levels) || 3;
      const currentSteps: RoleOption[] =
        form.workflowSteps && form.workflowSteps.length > 0
          ? [...form.workflowSteps]
          : ["หัวหน้าแผนก", "ผู้บริหาร", "ผู้ดูแลระบบ"];
      const steps = currentSteps.slice(0, levelCount);

      const updateStepRole = (idx: number, role: RoleOption) => {
        const nextSteps: RoleOption[] = [...currentSteps];
        nextSteps[idx] = role;
        setForm((f) => ({ ...f, workflowSteps: nextSteps }));
      };

      return (
        <>
          <Field
            label="ชื่อ Workflow"
            value={form.name}
            onChange={(v) => {
              setForm((f) => ({ ...f, name: v }));
              if (formErrors.name) {
                const err = validateWorkflowForm(
                  { ...form, name: v },
                  data.workflow,
                  editingId,
                ).name;
                setFieldError("name", err);
              }
            }}
            onBlur={() => {
              setFieldError(
                "name",
                validateWorkflowForm(form, data.workflow, editingId).name,
              );
            }}
            inputClassName={formErrors.name ? inputErrorCls : inputCls}
            error={formErrors.name}
          />

          <div className="mb-3">
            <label className="mb-1.5 block text-xs text-slate-500">
              ประเภทเอกสารที่ผูก (Prefix)
            </label>
            <select
              className={inputCls}
              value={form.prefix || "PR"}
              onChange={(e) => {
                const prefix = e.target.value;
                setForm((f) => ({ ...f, prefix }));
              }}
            >
              <option value="PR">ใบขอซื้อ (PR)</option>
              <option value="PO">ใบสั่งซื้อ (PO)</option>
              <option value="BK">บันทึกข้อความ (BK)</option>
              <option value="DOC">เอกสารทั่วไป (DOC)</option>
            </select>
          </div>

          <div className="mb-3">
            <label className="mb-1.5 block text-xs text-slate-500">
              จำนวน Level (ระดับการตรวจอนุมัติ)
            </label>
            <select
              className={inputCls}
              value={form.levels}
              onChange={(e) => {
                const levelsNum = Number(e.target.value);
                setForm((f) => {
                  const nextSteps: RoleOption[] = [...(f.workflowSteps || [])];
                  while (nextSteps.length < levelsNum) {
                    nextSteps.push((roleNames[0] || "") as RoleOption);
                  }
                  return {
                    ...f,
                    levels: e.target.value,
                    workflowSteps: nextSteps,
                  };
                });
              }}
            >
              <option value="1">1 ระดับ</option>
              <option value="2">2 ระดับ</option>
              <option value="3">3 ระดับ</option>
              <option value="4">4 ระดับ</option>
            </select>
          </div>

          <div className="mb-3 rounded-lg border border-slate-200 bg-slate-50/70 p-3">
            <label className="mb-2 block text-xs font-semibold text-slate-700">
              สายการอนุมัติ (กำหนดบทบาทผู้อนุมัติในแต่ละระดับ)
            </label>
            <div className="space-y-2">
              {Array.from({ length: levelCount }).map((_, idx) => (
                <div key={idx} className="flex items-center gap-2">
                  <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-blue-600 text-xs font-bold text-white">
                    {idx + 1}
                  </span>
                  <div className="flex-1">
                    <select
                      className={inputCls}
                      value={steps[idx] || roleNames[0] || ""}
                      onChange={(e) =>
                        updateStepRole(idx, e.target.value as RoleOption)
                      }
                    >
                      {roleNames.map((role) => (
                        <option key={role} value={role}>
                          {role}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
            </div>

            {/* Step flow preview */}
            <div className="mt-3 overflow-x-auto rounded-md border border-blue-100 bg-blue-50/50 p-2.5">
              <p className="mb-1.5 text-[11px] font-medium text-blue-600">
                ตัวอย่างสายการอนุมัติ:
              </p>
              <div className="flex flex-wrap items-center gap-1 text-xs">
                {steps.map((s, i) => (
                  <span key={i} className="flex items-center gap-1">
                    <span className="rounded bg-white px-2 py-0.5 font-medium text-blue-700 border border-blue-200">
                      {s}
                    </span>
                    {i < steps.length - 1 && (
                      <span className="text-slate-400 font-bold">›</span>
                    )}
                  </span>
                ))}
              </div>
            </div>
          </div>

          {renderStatusToggle()}
        </>
      );
    }
    return (
      <>
        <div className="mb-3">
          <label className="mb-1.5 block text-xs text-slate-500">
            ชื่อผู้อนุมัติ
          </label>
          {editingId ? (
            <div className="w-full rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-slate-500 font-medium">
              {form.approverName}
            </div>
          ) : (
            <select
              className={formErrors.approverName ? inputErrorCls : inputCls}
              value={form.approverName}
              onChange={(e) => {
                const name = e.target.value;
                const user = APPROVER_USERS.find((u) => u.name === name);
                setForm((f) => ({
                  ...f,
                  approverName: name,
                  position: user?.position ?? "",
                }));
                if (formErrors.approverName) {
                  setFieldError(
                    "approverName",
                    validateSignatureForm(
                      {
                        ...form,
                        approverName: name,
                        position: user?.position ?? "",
                      },
                      data.signature,
                      editingId,
                    ).approverName,
                  );
                }
              }}
              onBlur={() =>
                setFieldError(
                  "approverName",
                  validateSignatureForm(form, data.signature, editingId)
                    .approverName,
                )
              }
            >
              <option value="">เลือกผู้อนุมัติ</option>
              {APPROVER_USERS.map((user) => (
                <option key={user.name} value={user.name}>
                  {formatApproverLabel(user)}
                </option>
              ))}
            </select>
          )}
          {formErrors.approverName && !editingId && (
            <p className="mt-1 text-xs text-red-500">
              {formErrors.approverName}
            </p>
          )}
        </div>
        <div className="mb-3">
          <label className="mb-1.5 block text-xs text-slate-500">ตำแหน่ง</label>
          <div className="w-full rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-slate-500">
            {form.position || "—"}
          </div>
        </div>
        <div className="mb-3">
          <label className="mb-1.5 block text-xs text-slate-500">
            อัปโหลดไฟล์ลายเซ็น (PNG/JPG/SVG)
          </label>
          <input
            type="file"
            accept="image/*"
            className="w-full text-xs text-slate-500 file:mr-3 file:py-1.5 file:px-3 file:rounded-md file:border-0 file:text-xs file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100 cursor-pointer"
            onChange={(e) => {
              const file = e.target.files?.[0];
              if (!file) return;
              const reader = new FileReader();
              reader.onload = () => {
                if (typeof reader.result === "string") {
                  setForm((f) => ({ ...f, imageUrl: reader.result as string }));
                }
              };
              reader.readAsDataURL(file);
            }}
          />
          {form.imageUrl && (
            <div className="mt-2 flex items-center justify-center p-3 border border-slate-200 rounded-lg bg-slate-50">
              <img
                src={form.imageUrl}
                alt="Signature Preview"
                className="max-h-16 object-contain"
              />
            </div>
          )}
        </div>
        {editingId &&
          renderReadOnlyCount(
            "จำนวนลงนาม",
            form.signedCount,
            "นับอัตโนมัติจากการใช้ลายเซ็น",
          )}
        {renderStatusToggle()}
      </>
    );
  };

  const TabIcon = TABS.find((t) => t.key === activeTab)?.icon ?? Building2;

  if (!hasPerm("access", "view")) {
    return (
      <div className="flex flex-col items-center justify-center p-12 text-slate-400 mt-12">
        <p className="text-sm font-bold">ไม่มีสิทธิ์เข้าถึงหน้า Master Data</p>
      </div>
    );
  }

  return (
    <>
      <MasterDataLayout
        breadcrumb={
          <nav className="flex items-center gap-1.5 text-xs text-slate-400">
            <span>Admin</span>
            <span>/</span>
            <span className="text-slate-500">Master Data</span>
            <span>/</span>
            <span className="font-medium text-slate-600">{tabLabel}</span>
          </nav>
        }
        title="Master Data"
        actions={(() => {
          let canAdd = false;
          if (activeTab === "department")
            canAdd = hasPerm("departments", "create");
          else if (activeTab === "position")
            canAdd = hasPerm("positions", "create");
          else if (activeTab === "doctype")
            canAdd = hasPerm("doc_types", "create");
          else if (activeTab === "workflow")
            canAdd = hasPerm("workflow", "create");
          else if (activeTab === "signature")
            canAdd = hasPerm("signatures", "create");

          if (!canAdd || activeTab === "running" || activeTab === "workflow")
            return undefined;
          return (
            <button
              type="button"
              onClick={openAdd}
              className={MD_MASTER_ADD_BTN}
            >
              <Plus className={MD_SIDEBAR_ICON} strokeWidth={1.75} />
              เพิ่ม
            </button>
          );
        })()}
        sidebar={
          <nav className={MD_SIDEBAR_NAV}>
            {TABS.map(({ key, label, icon: Icon }) => (
              <button
                key={key}
                type="button"
                onClick={() => setActiveTab(key)}
                className={
                  activeTab === key ? MD_SIDEBAR_ITEM_ACTIVE : MD_SIDEBAR_ITEM
                }
              >
                <Icon className={MD_SIDEBAR_ICON} strokeWidth={1.75} />
                {label}
              </button>
            ))}
          </nav>
        }
      >
        <section className={MD_SECTION}>
          {modalOpen ? (
            <div className="rounded-xl border border-slate-200 bg-white p-6 shadow-xs">
              <div className="flex items-center justify-between pb-4 border-b border-slate-100 mb-6">
                <div>
                  <h3 className="text-base font-bold text-slate-800">
                    {editingId ? "แก้ไข" : "เพิ่ม"} {tabLabel}
                  </h3>
                  <p className="text-xs text-slate-400 mt-1">
                    กรอกรายละเอียดข้อมูล {tabLabel} ที่คุณต้องการ{" "}
                    {editingId ? "แก้ไข" : "สร้างใหม่"}
                  </p>
                </div>
                <button
                  type="button"
                  onClick={closeModal}
                  disabled={saving}
                  className="rounded-md p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 disabled:opacity-50"
                  aria-label="ปิด"
                >
                  <X className="size-4" />
                </button>
              </div>

              <div
                className={`space-y-4 ${activeTab === "workflow" ? "max-w-xl" : "max-w-md"}`}
              >
                {renderFormFields()}
              </div>

              <div className="mt-8 pt-4 border-t border-slate-100 flex justify-end gap-2">
                <button
                  type="button"
                  onClick={closeModal}
                  disabled={saving}
                  className="rounded-xl px-5 py-2.5 text-sm font-bold text-slate-600 transition-colors hover:bg-slate-100 disabled:opacity-50"
                >
                  ยกเลิก
                </button>
                <button
                  type="button"
                  onClick={handleSave}
                  disabled={saving || !isModalValid}
                  className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-bold text-white transition-colors hover:bg-blue-700 disabled:opacity-60"
                >
                  {saving && <Loader2 className="size-4 animate-spin" />}
                  {saving ? "กำลังบันทึก..." : "บันทึกข้อมูล"}
                </button>
              </div>
            </div>
          ) : activeTab === "running" ? (
            <DocumentRunningTab showToast={showToast} />
          ) : activeTab === "workflow" ? (
            <WorkflowTab
              rows={rows as WorkflowRow[]}
              docTypes={data.doctype as any}
              showDeleted={showDeleted}
              onShowDeletedChange={setShowDeleted}
              stats={tabStats}
              onEdit={openEdit}
              onDelete={softDelete}
              onRestore={restore}
              canEdit={hasPerm("workflow", "edit")}
              canDelete={hasPerm("workflow", "delete")}
            />
          ) : (
            <>
              <div className="flex flex-wrap items-center justify-between gap-4">
                <h2 className="text-sm font-medium text-slate-800">
                  {tabLabel}
                </h2>
                <InactiveFilterCheckbox
                  checked={showDeleted}
                  onChange={setShowDeleted}
                />
              </div>

              <MasterDataTableWrap
                empty={rows.length === 0}
                emptyContent={
                  <div className="flex flex-col items-center justify-center gap-3 px-6 py-12 text-center">
                    <Inbox className="size-10 text-slate-300" />
                    <p className="text-sm text-slate-500">
                      {showDeleted ? "ไม่มีรายการที่ปิดใช้งาน" : "ไม่มีข้อมูล"}
                    </p>
                    <p className="text-xs text-slate-400">
                      {showDeleted
                        ? "รายการที่กู้คืนจะแสดงในรายการปกติ"
                        : activeTab === "signature"
                          ? "เพิ่มลายเซ็นได้ที่หน้าโปรไฟล์"
                          : "กดปุ่ม เพิ่ม เพื่อสร้างรายการใหม่"}
                    </p>
                  </div>
                }
                mobile={<MasterDataMobileCardList rows={mobileRows} />}
              >
                <table className={MD_TABLE}>
                  <thead className={MD_THEAD}>
                    <tr>
                      {renderHeaders()}
                      <th className={MD_TH_STATUS}>สถานะ</th>
                      <th className={thAction}>จัดการ</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row) => (
                      <tr key={row.id} className={`group ${MD_TR}`}>
                        {renderCells(row)}
                        <td className={MD_TD_STATUS}>
                          <StatusBadge active={row.isActive} />
                        </td>
                        <td className={MD_TD_ACTION}>
                          {row.isActive ? (
                            (() => {
                              let canEdit = false;
                              let canDelete = false;
                              if (activeTab === "department") {
                                canEdit = hasPerm("departments", "edit");
                                canDelete = hasPerm("departments", "delete");
                              } else if (activeTab === "position") {
                                canEdit = hasPerm("positions", "edit");
                                canDelete = hasPerm("positions", "delete");
                              } else if (activeTab === "doctype") {
                                canEdit = hasPerm("doc_types", "edit");
                                canDelete = hasPerm("doc_types", "delete");
                              } else if (activeTab === "signature") {
                                canEdit = hasPerm("signatures", "edit");
                                canDelete = hasPerm("signatures", "delete");
                              }

                              const guard = getDeleteGuard(
                                activeTab as DataTabKey,
                                row,
                                signatureGuardData,
                              );
                              return (
                                <RowActions
                                  onEdit={
                                    canEdit ? () => openEdit(row.id) : undefined
                                  }
                                  onDelete={
                                    canDelete && activeTab !== "position"
                                      ? () => softDelete(row.id)
                                      : undefined
                                  }
                                  deleteBlocked={guard.blocked}
                                  deleteTooltip={guard.tooltip}
                                />
                              );
                            })()
                          ) : (
                            <RowActions onRestore={() => restore(row.id)} />
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </MasterDataTableWrap>
            </>
          )}
        </section>
      </MasterDataLayout>
      {previewSignatureUrl && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4 sm:p-6 backdrop-blur-xs"
          style={{
            paddingLeft: isOpen
              ? "calc(16rem + 1.5rem)"
              : "calc(5rem + 1.5rem)",
          }}
          onClick={() => setPreviewSignatureUrl(null)}
        >
          <div
            className="relative flex flex-col max-h-[85vh] w-full max-w-sm rounded-2xl border border-slate-200 bg-white p-6 shadow-2xl items-center"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex w-full shrink-0 items-start justify-between gap-3 pb-3 border-b border-slate-100">
              <h2 className="text-sm font-bold text-slate-800">
                ตัวอย่างลายเซ็นของ {previewSignatureName}
              </h2>
              <button
                type="button"
                onClick={() => setPreviewSignatureUrl(null)}
                className="rounded-md p-1 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                aria-label="ปิด"
              >
                <X className="size-4" />
              </button>
            </div>
            <div className="my-8 flex w-full items-center justify-center rounded-xl border border-slate-200 bg-slate-50/50 p-6 shadow-inner relative overflow-hidden select-none">
              <img
                src={previewSignatureUrl}
                alt={previewSignatureName}
                className="h-32 max-w-full object-contain pointer-events-none"
              />
              {/* Security Watermark Overlay */}
              <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center rotate-[-15deg] opacity-20 font-black text-rose-600 text-xs sm:text-sm tracking-widest uppercase select-none leading-relaxed text-center p-2">
                <span>FOR PREVIEW ONLY</span>
                <span>ห้ามคัดลอก / ตัวอย่างลายเซ็นระบบ</span>
                <span className="text-[10px]">SECURITY WATERMARK</span>
              </div>
            </div>
            <button
              type="button"
              onClick={() => setPreviewSignatureUrl(null)}
              className="w-full rounded-xl bg-slate-100 py-2.5 text-xs font-bold text-slate-700 hover:bg-slate-200 transition-colors"
            >
              ปิดหน้าต่าง
            </button>
          </div>
        </div>
      )}
    </>
  );
}

function Field({
  label,
  value,
  onChange,
  type = "text",
  inputClassName,
  error,
  maxLength,
  onBlur,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  inputClassName?: string;
  error?: string;
  maxLength?: number;
  onBlur?: () => void;
}) {
  return (
    <div className="mb-3">
      <label className="mb-1.5 block text-xs text-slate-500">{label}</label>
      <input
        type={type}
        className={
          inputClassName ??
          "w-full rounded-md border border-gray-200 px-3 py-2 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
        }
        value={value}
        maxLength={maxLength}
        onChange={(e) => onChange(e.target.value)}
        onBlur={onBlur}
      />
      {error && <p className="mt-1 text-xs text-red-500">{error}</p>}
    </div>
  );
}

