// ---- Safe API Wrapper ----
const API_BASE = typeof window !== "undefined" ? "" : "http://127.0.0.1:4000";

type ApiResponse<T> = { data: T };

/** Retry on ECONNREFUSED (server not yet ready) with exponential backoff */
async function withRetry<T>(fn: () => Promise<T>, maxAttempts = 1): Promise<T> {
  let lastErr: unknown;
  for (let i = 0; i < maxAttempts; i++) {
    try {
      return await fn();
    } catch (err: unknown) {
      lastErr = err;
      const msg = (err as any)?.message?.toLowerCase() ?? "";
      const isConnErr =
        msg.includes("econnrefused") ||
        msg.includes("failed to fetch") ||
        msg.includes("network request failed") ||
        (err as any)?.name === "TypeError";
      if (!isConnErr || i === maxAttempts - 1) break;
      // Removed exponential backoff to prevent sluggish UI
    }
  }
  throw lastErr;
}

async function request<T>(
  method: string,
  path: string,
  body?: unknown,
): Promise<ApiResponse<T>> {
  return withRetry(async () => {
    const isFormData = body instanceof FormData;
    const headers: Record<string, string> = {};
    if (!isFormData) {
      headers["Content-Type"] = "application/json";
    }

    try {
      const res = await fetch(`${API_BASE}${path}`, {
        method,
        headers,
        credentials: "include", // Crucial for sending/receiving HttpOnly cookies
        body: isFormData
          ? (body as any)
          : body
            ? JSON.stringify(body)
            : undefined,
      });

      if (!res.ok) {
        if (res.status === 401) {
          if (
            typeof window !== "undefined" &&
            !window.location.pathname.startsWith("/login") &&
            !path.includes("login") &&
            !path.includes("password")
          ) {
            window.location.href = "/login";
          }
        }
        if (res.status >= 500) {
          return Promise.reject(new Error("ไม่สามารถเชื่อมต่อกับ server ได้"));
        }

        let serverMessage = `API Error: ${res.status} ${res.statusText}`;
        if (res.status === 401) {
          serverMessage = "ชื่อผู้ใช้งานหรือรหัสผ่านไม่ถูกต้อง";
        }

        try {
          const errorData = await res.json();
          if (errorData?.message) {
            serverMessage = Array.isArray(errorData.message)
              ? errorData.message.join(", ")
              : errorData.message;
          }
        } catch {}

        // Use Promise.reject with string to avoid Next.js Red Screen of Death
        return Promise.reject(new Error(serverMessage));
      }

      const data = await res.json();
      return { data };
    } catch (err: unknown) {
      if (
        (err as any)?.name === "TypeError" ||
        (err as any)?.message?.toLowerCase().includes("fetch")
      ) {
        return Promise.reject(new Error("ไม่สามารถเชื่อมต่อกับ server ได้"));
      }
      return Promise.reject(err);
    }
  });
}

export const api = {
  get: <T>(path: string) => request<T>("GET", path),
  post: <T>(path: string, body?: unknown) => request<T>("POST", path, body),
  put: <T>(path: string, body?: unknown) => request<T>("PUT", path, body),
  patch: <T>(path: string, body?: unknown) => request<T>("PATCH", path, body),
  delete: <T>(path: string) => request<T>("DELETE", path),
};

"use client";

import React, { useEffect, useMemo, useState } from "react";
import { ResponsiveContainer, PieChart, Pie, Cell } from "recharts";
import { DocumentTypeBreakdown } from '@views/features/documents/types';

type DocumentTypesChartProps = {
  data: DocumentTypeBreakdown[];
};

export function DocumentTypesChart({ data }: DocumentTypesChartProps) {
  const [mounted, setMounted] = useState(false);
  const total = useMemo(() => data.reduce((sum, item) => sum + item.value, 0), [data]);

  useEffect(() => {
   
    setMounted(true);
  }, []);

  return (
    <div className="bg-white rounded-2xl p-10 border border-slate-100 shadow-sm flex flex-col justify-between h-full">
      <div>
        <h3 className="text-lg font-bold text-slate-950">Document Types</h3>
        <p className="text-sm text-slate-400 font-medium">Breakdown of submitted request formats</p>
      </div>

      <div className="my-8 flex items-center justify-center relative h-52">
        {mounted ? (
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={data}
                cx="50%"
                cy="50%"
                innerRadius="65%"
                outerRadius="85%"
                paddingAngle={2}
                dataKey="value"
              >
                {data.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        ) : (
          <div className="w-32 h-32 rounded-full border-8 border-slate-100 animate-pulse" />
        )}

        <div className="absolute flex flex-col items-center justify-center pointer-events-none">
          <span className="text-3xl font-black text-slate-900">{total}</span>
          <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">
            Documents
          </span>
        </div>
      </div>

      <div className="space-y-2 pt-3 border-t border-slate-50">
        {data.map((item, index) => {
          const percentage = total > 0 ? Math.round((item.value / total) * 100) : 0;
          return (
            <div key={index} className="flex items-center justify-between text-sm font-semibold">
              <div className="flex items-center gap-2.5">
                <span className="h-2.5 w-2.5 rounded-full shrink-0" style={{ backgroundColor: item.color }} />
