                      <th className="py-3 px-4 font-bold text-[11px] uppercase tracking-wider text-slate-400 w-[30%]">ชื่อเรื่อง / แผนก</th>
                      <th className="py-3 px-4 font-bold text-[11px] uppercase tracking-wider text-slate-400 w-[15%]">กิจกรรม</th>
                      <DataTableHeader title="สถานะ" sortKey="status" currentSortKey={sortKey} currentDirection={sortDirection} onSort={handleSort} className="py-3 px-4 w-[10%]" />
                      <DataTableHeader title="ผู้ส่ง" sortKey="submittedBy" currentSortKey={sortKey} currentDirection={sortDirection} onSort={handleSort} className="py-3 px-4 w-[15%]" />
                      <DataTableHeader title="วันที่" sortKey="date" currentSortKey={sortKey} currentDirection={sortDirection} onSort={handleSort} className="py-3 pr-5 pl-4 w-[15%]" />
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50/80">
                    {recentActivity.filter(d => d.status !== 'Approved').slice(0, 5).map((doc, index) => {
                      let activityText = 'อัปเดตเอกสาร';
                      if (doc.status === 'Pending') activityText = 'ส่งขออนุมัติ';
                      else if (doc.status === 'Returned') activityText = 'ส่งกลับแก้ไข';
                      else if (doc.status === 'Rejected') activityText = 'ไม่อนุมัติ';
                      else if (doc.status === 'Draft') activityText = 'บันทึกร่าง';

                      return (
                      <tr key={doc.id || index} className={`${MD_TR} group`}>
                        <td className="py-3 pl-5 text-sm font-bold text-slate-500">
                          <Link href={`/documents/${doc.id}`} className="hover:text-amber-600 transition-colors">
                            {doc.id}
                          </Link>
                        </td>
                        <td className="py-3 px-4">
                          <Link href={`/documents/${doc.id}`} className="flex flex-col">
                            <span className="text-sm font-bold text-slate-800 group-hover:text-amber-600 transition-colors truncate block">{doc.title}</span>
                            <span className="text-[10px] font-semibold text-slate-400 mt-0.5">{doc.type} • {doc.department}</span>
                          </Link>
                        </td>
                        <td className={`py-3 px-4 text-xs font-semibold ${
                            doc.status === 'Pending' ? 'text-amber-600' :
                            doc.status === 'Returned' || doc.status === 'Rejected' ? 'text-rose-600' :
                            'text-slate-600'
                          }`}>{activityText}</td>
                        <td className="py-3 px-4">
                          <span className={`inline-flex px-2 py-0.5 rounded text-[10px] font-bold border ${
                            doc.status === 'Pending' ? 'bg-amber-50 text-amber-700 border-amber-200' :
                            doc.status === 'Returned' || doc.status === 'Rejected' ? 'bg-rose-50 text-rose-700 border-rose-200' :
                            'bg-slate-50 text-slate-700 border-slate-200'
                          }`}>
                            {doc.status}
                          </span>
                        </td>
                        <td className="py-3 px-4 text-sm font-semibold text-slate-700">{doc.submittedBy}</td>
                        <td className="py-3 pr-5 pl-4 text-xs text-slate-400 font-medium">{formatThaiDate(doc.date)}</td>
                      </tr>
                    )})}
                    {recentActivity.filter(d => d.status !== 'Approved').length === 0 && (
                      <tr><td colSpan={6} className="py-8 text-center text-sm text-slate-400">ไม่มีประวัติการส่งเรื่องล่าสุด</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
      
      {showBottlenecks && bottlenecks.length > 0 && (
        <div className={`mb-6 ${APP_TABLE_CARD} flex flex-col border-rose-100 overflow-hidden`}>
          <div className="bg-rose-50 border-b border-rose-100 text-rose-700 p-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <AlertCircle className="w-5 h-5 text-rose-500" />
              <div>
                <h3 className="text-sm font-bold">เอกสารค้างนานผิดปกติ (เกิน 7 วัน)</h3>
                <p className="text-xs font-medium opacity-80">พบ {bottlenecks.length} รายการที่กำลังรอการอนุมัติและเกินกำหนดเวลามาตรฐาน</p>
              </div>
            </div>
            <Link href="/documents?status=Pending&overdue=true" className="px-4 py-1.5 bg-rose-600 hover:bg-rose-700 text-white text-xs font-bold rounded-lg transition-colors">
              ดูทั้งหมด
            </Link>
          </div>
          
          <div className="overflow-x-auto w-full">
            <table className="w-full table-fixed min-w-[900px] text-left border-collapse whitespace-nowrap">
              <thead>
                <tr className={MD_THEAD}>
                  <th className="pl-6 py-4 w-[12%] font-bold text-[11px] uppercase tracking-wider text-slate-400">รหัสเอกสาร</th>
                  <th className="py-4 px-4 w-[30%] font-bold text-[11px] uppercase tracking-wider text-slate-400">ชื่อเรื่อง / แผนก</th>
                  <th className="py-4 px-4 w-[12%] font-bold text-[11px] uppercase tracking-wider text-slate-400">จำนวนวันค้าง</th>
                  <th className="py-4 px-4 w-[16%] font-bold text-[11px] uppercase tracking-wider text-slate-400">ผู้สร้าง</th>
                  <th className="py-4 px-4 w-[18%] font-bold text-[11px] uppercase tracking-wider text-slate-400">ผู้อนุมัติ</th>
                  <th className="py-4 pr-6 pl-4 w-[12%] font-bold text-[11px] uppercase tracking-wider text-slate-400">วันที่ส่ง</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50/80 bg-white">
                {(() => {
                  const itemsPerPage = 5;
                  const totalPages = Math.ceil(bottlenecks.length / itemsPerPage);
                  const startIndex = (bottleneckPage - 1) * itemsPerPage;
                  const paginated = bottlenecks.slice(startIndex, startIndex + itemsPerPage);

                  return paginated.map((doc, index) => {
                    const daysPending = Math.floor((new Date().getTime() - new Date(doc.date).getTime()) / (1000 * 3600 * 24));
                    const approverText = (doc.approvers && doc.approvers.length > 0) ? doc.approvers.join(', ') : '-';
                    return (
                      <tr key={doc.id || index} className={`${MD_TR} group hover:bg-rose-50/30`}>
                        <td className="py-4 pl-6 text-sm font-bold text-slate-500">
                          <Link href={`/documents/${doc.id}`} className="hover:text-blue-600 transition-colors">
                            {doc.id}
                          </Link>
                        </td>
                        <td className="py-4 px-4">
                          <Link href={`/documents/${doc.id}`} className="flex flex-col">
                            <span className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors truncate block">{doc.title}</span>
                            <span className="text-[10px] font-semibold text-slate-400 mt-0.5">{doc.type} • {doc.department}</span>
                          </Link>
                        </td>
                        <td className="py-4 px-4">
                          <span className="inline-flex px-2.5 py-1 rounded-md text-[11px] font-bold border bg-rose-50 text-rose-700 border-rose-200">
                            {daysPending} วัน
                          </span>
                        </td>
                        <td className="py-4 px-4 text-sm font-semibold text-slate-700">{doc.submittedBy}</td>
                        <td className="py-4 px-4 text-sm font-semibold text-slate-700 truncate" title={approverText}>{approverText}</td>
                        <td className="py-4 pr-6 pl-4 text-sm text-slate-400 font-medium">{formatThaiDate(doc.date)}</td>
                      </tr>
                    );
                  });
                })()}
              </tbody>
            </table>
          </div>
          {bottlenecks.length > 5 && (
            <div className="flex justify-end p-4 border-t border-slate-100 bg-white">
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  onClick={() => setBottleneckPage(p => Math.max(1, p - 1))}
                  disabled={bottleneckPage === 1}
                  className="p-1 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 disabled:opacity-50 disabled:hover:bg-transparent"
                >
                  <ChevronLeft className="w-4 h-4" />
                </button>
                <span className="text-xs font-semibold text-slate-600 px-2">
                  หน้า {bottleneckPage} จาก {Math.ceil(bottlenecks.length / 5)}
                </span>
                <button
                  type="button"
                  onClick={() => setBottleneckPage(p => Math.min(Math.ceil(bottlenecks.length / 5), p + 1))}
                  disabled={bottleneckPage === Math.ceil(bottlenecks.length / 5)}
                  className="p-1 rounded-md text-slate-400 hover:text-blue-600 hover:bg-blue-50 disabled:opacity-50 disabled:hover:bg-transparent"
                >
                  <ChevronRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </>
  );
}

"use client";

import React from "react";
import { Search } from "lucide-react";
import { Badge } from '@views/components/ui/badge';
import { Document } from '@views/features/documents/types';
import { getStatusVariant } from "@/lib/document-status";
import { DocumentTypeIcon } from "@/lib/document-type-icon";

interface RecentDocumentsTableProps {
  documents: Document[];
  statusFilter: string;
  onStatusFilterChange: (status: string) => void;
  searchQuery: string;
  onSearchQueryChange: (query: string) => void;
}

export function RecentDocumentsTable({
  documents,
  statusFilter,
  onStatusFilterChange,
  searchQuery,
  onSearchQueryChange,
}: RecentDocumentsTableProps) {
  return (
    <div className="bg-white rounded-2xl p-10 border border-slate-100 shadow-sm flex flex-col">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-5">
        <div>
          <h3 className="text-lg font-bold text-slate-950">Recent Documents</h3>
          <p className="text-sm text-slate-400 font-medium">Tracking newly submitted and updated workflows</p>
        </div>

        {/* Status Quick Filter Buttons */}
        <div className="flex flex-wrap gap-1.5 items-center">
          {["All", "Pending", "Approved", "Returned for Revision", "Draft"].map((status) => (
            <button
              key={status}
              onClick={() => onStatusFilterChange(status)}
              className={`px-3 py-2 rounded-lg text-sm font-semibold transition-all border ${
                statusFilter === status
                  ? "bg-indigo-600 text-white border-indigo-600 shadow-sm"
                  : "bg-white text-slate-500 border-slate-100 hover:bg-slate-50"
              }`}
            >
              {status === "Returned for Revision" ? "Returned" : status}
            </button>
          ))}

  // eslint-disable-next-line @next/next/no-html-link-for-pages
  {/* eslint-disable-next-line @next/next/no-html-link-for-pages */}
          <a
            href="/documents"
            className="px-3 py-2 rounded-lg text-sm font-semibold bg-slate-900 text-white border border-slate-900 hover:bg-slate-800 transition-all shadow-xs ml-auto sm:ml-0"
          >
            See all
          </a>
        </div>
      </div>

      {/* Internal Search bar for smaller screens/table specific */}
      <div className="relative mb-4 sm:hidden">
        <span className="absolute inset-y-0 left-0 flex items-center pl-3.5 pointer-events-none text-slate-400">
          <Search className="w-5 h-5" />
        </span>
        <input
          type="text"
          placeholder="Search within recent..."
          value={searchQuery}
          onChange={(e) => onSearchQueryChange(e.target.value)}
          className="w-full bg-slate-50/50 border border-slate-100/80 rounded-xl py-3 pl-10 pr-4 text-base font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-indigo-500/20"
        />
      </div>

      {/* Table Container */}
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[500px]">
          <thead>
            <tr className="border-b border-slate-100 text-xs font-bold text-slate-400 uppercase tracking-wider">
              <th className="pb-3 pl-2">Document Name</th>
              <th className="pb-3">Doc Number</th>
              <th className="pb-3">Submitter</th>
              <th className="pb-3">Submitted Date</th>
              <th className="pb-3 pr-2 text-right">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50/80">
            {documents.length > 0 ? (
   
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              documents.map((doc, index) => (
                <tr key={(doc as any).real_id || `${doc.id}-${index}`} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="py-4 pl-2 flex items-center gap-3">
                    <DocumentTypeIcon type={doc.type} size="md" />
                    <div>
                      <p className="text-base font-bold text-slate-800 group-hover:text-indigo-600 transition-colors">
                        {doc.name}
                      </p>
                      <span className="text-xs font-bold text-slate-400">
                        {doc.amount !== "-" ? `Value: ${doc.amount}` : "No Financial Value"}
                      </span>
                    </div>
                  </td>
                  <td className="py-4 text-base font-semibold text-slate-500">{doc.id}</td>
                  <td className="py-4 text-base font-medium text-slate-600">{doc.sender}</td>
                  <td className="py-4 text-base text-slate-400 font-medium">{doc.submittedDate}</td>
                  <td className="py-4 pr-2 text-right">
                    <Badge variant={getStatusVariant(doc.status)}>
                      {doc.status}
                    </Badge>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={5} className="py-12 text-center text-base font-medium text-slate-400">
                  No documents found matching the active filters.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

