                />
                <YAxis
                  axisLine={false}
                  tickLine={false}
                  ticks={[0, 8, 16, 24, 32]}
                  domain={[0, 32]}
                  tick={{ fill: "#94A3B8", fontSize: 11, fontWeight: 500 }}
                />
                <Tooltip content={<TrendTooltip />} cursor={{ stroke: "#E2E8F0", strokeDasharray: "3 3" }} />
                <Area
                  type="monotone"
                  dataKey="approvals"
                  name="Approvals"
                  stroke="#3B82F6"
                  strokeWidth={2}
                  fill="url(#trendApprovals)"
                  dot={false}
                  activeDot={{ r: 3.5, strokeWidth: 2, fill: "#ffffff" }}
                />
                <Area
                  type="monotone"
                  dataKey="documents"
                  name="Documents"
                  stroke="#10B981"
                  strokeWidth={2}
                  fill="url(#trendDocuments)"
                  dot={false}
                  activeDot={{ r: 3.5, strokeWidth: 2, fill: "#ffffff" }}
                />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full w-full bg-slate-50 rounded-xl animate-pulse" />
          )}
        </div>
      </CardContent>
    </Card>
  );
}

export default WorkflowTrendChart;

"use client";

import React, { useState } from "react";
import { XCircle, X } from "lucide-react";
import { Document } from "@views/features/documents/types";
import { api } from "@/lib";
import { useAuth } from "../providers/AuthProvider";

interface CancelDocumentButtonProps {
  document: Document;
}

export function CancelDocumentButton({ document }: CancelDocumentButtonProps) {
  const { user } = useAuth();
  const [showModal, setShowModal] = useState(false);
  const [reason, setReason] = useState("");
  const [isCancelled, setIsCancelled] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Conditions: only Pending or Draft, and we assume current user is the owner for mock purposes.
  // In a real app, we would check `document.creator_id === currentUser.id`.
  if (
    !user ||
    (document as Document & { creator_id?: string }).creator_id !== user.id ||
    !user.permissions?.some((p) =>
      [
        "submissions.delete_document:delete",
        "document.delete_document:delete",
        "submissions.cancel_document:delete",
        "document.recall_document:edit",
      ].includes(p),
    ) ||
    !["Pending", "Draft", "Returned"].includes(document.status)
  ) {
    return null;
  }

  // Hide button if already cancelled in this session
  if (isCancelled) {
    return null;
  }

  const handleCancel = async () => {
    setIsSubmitting(true);
    const targetId = document.real_id || document.id;
    let success = false;
    try {
      success = (
        await api.post<{ success: boolean }>(
          `/api/documents/${encodeURIComponent(targetId)}/cancel`,
          { reason },
        )
      ).data.success;
    } catch (error) {
      alert(error instanceof Error ? error.message : String(error));
    }
    setIsSubmitting(false);

    if (success) {
      setIsCancelled(true);
      setShowModal(false);
      alert(`เอกสาร ${document.id} ถูกยกเลิก/ลบเรียบร้อยแล้ว`);
      window.location.href = "/documents";
    } else {
      alert("เกิดข้อผิดพลาดในการยกเลิกเอกสาร");
    }
  };

  return (
    <>
      <button
        onClick={() => setShowModal(true)}
        className="flex items-center gap-1.5 px-3 py-1.5 bg-rose-50 hover:bg-rose-100 text-rose-600 font-bold rounded-lg text-xs transition-colors border border-rose-200"
      >
        <XCircle className="w-4 h-4" />
        ยกเลิกเอกสาร (Cancel Request)
      </button>

      {/* Confirmation Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white rounded-3xl w-full max-w-md shadow-2xl overflow-hidden flex flex-col">
            <div className="flex items-center justify-between px-6 py-5 border-b border-slate-100 bg-rose-50/50">
              <h3 className="text-lg font-black text-rose-700">
                ยืนยันการยกเลิกเอกสาร
              </h3>
              <button
                onClick={() => setShowModal(false)}
                className="p-2 rounded-xl hover:bg-rose-100 text-rose-500 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div className="flex items-start gap-4 p-4 bg-amber-50 rounded-xl border border-amber-200 text-amber-800 text-sm font-semibold">
                {}
                การกระทำนี้ไม่สามารถย้อนกลับได้! เอกสารจะถูกเปลี่ยนสถานะเป็น
                "ยกเลิก" และยุติสายการอนุมัติทั้งหมด
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-bold text-slate-700">
                  เหตุผลที่ยกเลิก (ไม่บังคับ)
                </label>
                <textarea
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder="ระบุเหตุผลที่ต้องการยกเลิก..."
                  className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:border-rose-500 focus:ring-1 focus:ring-rose-500 transition-colors resize-none h-24 text-sm font-medium"
                />
              </div>
            </div>

            <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
              <button
                onClick={() => setShowModal(false)}
                className="px-5 py-2.5 bg-white border border-slate-200 hover:bg-slate-100 text-slate-700 font-bold rounded-xl text-sm transition-colors"
              >
                ปิด (Close)
              </button>
              <button
                onClick={handleCancel}
                className="px-5 py-2.5 bg-rose-600 hover:bg-rose-700 text-white font-bold rounded-xl text-sm transition-colors shadow-sm"
              >
                ยืนยันการยกเลิก
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

