"use client";

import React, { useState } from "react";
import { X, Upload, FileText, AlertCircle } from "lucide-react";
import { uploadNewDocumentVersion } from "@/views/features/documents/api";
import { useToast } from '@views/components/providers/ToastProvider';
import type { Document } from "@/views/features/documents/types";

interface DocumentEditModalProps {
  isOpen: boolean;
  onClose: () => void;
  document: Document | null;
  onSuccess: () => void;
}

export function DocumentEditModal({
  isOpen,
  onClose,
  document,
  onSuccess,
}: DocumentEditModalProps) {
  const { showToast } = useToast();
  const [title, setTitle] = useState(document?.name || "");
  const [file, setFile] = useState<File | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  React.useEffect(() => {
    if (document) setTitle(document.name);
  }, [document]);

  if (!isOpen || !document) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) {
      showToast("กรุณาแนบไฟล์เอกสาร PDF เวอร์ชันใหม่", "error");
      return;
    }

    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append("file", file);
      formData.append("title", title);

      await uploadNewDocumentVersion(document.real_id || document.id, formData);
      showToast("อัปโหลดเอกสารเวอร์ชันใหม่และส่งกลับเป็น Draft สำเร็จ", "success");
      onSuccess();
      onClose();
    } catch (err: any) {
      showToast(err.message || "เกิดข้อผิดพลาดในการอัปโหลดไฟล์", "error");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/60 backdrop-blur-xs p-4 sm:p-6 animate-in fade-in">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg flex flex-col overflow-hidden animate-in zoom-in-95">
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-slate-50">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-amber-50 text-amber-600">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-800">
                แก้ไขและส่งเอกสารใหม่
              </h3>
              <p className="text-xs text-slate-500 font-medium">
                {document.id} (ปัจจุบัน: {document.status})
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-full hover:bg-slate-200 text-slate-400 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          <div className="p-4 rounded-xl bg-amber-50 border border-amber-100 flex gap-3 text-amber-800">
            <AlertCircle className="w-5 h-5 shrink-0 text-amber-600" />
            <div className="text-sm">
              <p className="font-bold">คำแนะนำ:</p>
              <p className="opacity-90 mt-0.5">
                การอัปโหลดไฟล์ใหม่จะทำให้เอกสารขยับเป็นเวอร์ชันใหม่ และสถานะจะกลับไปเป็น Draft เพื่อให้คุณตรวจสอบก่อนส่งอนุมัติอีกครั้ง
              </p>
            </div>
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1.5">
              ชื่อเอกสาร (Title)
            </label>
            <input
              type="text"
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full px-4 py-2.5 rounded-xl border border-slate-200 focus:border-blue-500 focus:ring-4 focus:ring-blue-500/10 outline-none transition-all text-sm font-medium"
            />
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1.5">
              ไฟล์ PDF เวอร์ชันใหม่ <span className="text-rose-500">*</span>
            </label>
            <div className="relative group cursor-pointer">
              <input
                type="file"
                accept="application/pdf"
                onChange={(e) => setFile(e.target.files?.[0] || null)}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                required
              />
              <div
                className={`w-full px-4 py-8 rounded-xl border-2 border-dashed flex flex-col items-center justify-center transition-all ${
                  file
                    ? "border-blue-500 bg-blue-50/50"
                    : "border-slate-200 bg-slate-50 group-hover:border-blue-400 group-hover:bg-blue-50/30"
                }`}
              >
                <div
                  className={`w-12 h-12 rounded-full flex items-center justify-center mb-3 ${
                    file ? "bg-blue-100 text-blue-600" : "bg-white shadow-xs text-slate-400"
                  }`}
                >
                  <Upload className="w-6 h-6" />
                </div>
                {file ? (
                  <div className="text-center">
                    <p className="text-sm font-bold text-slate-700">{file.name}</p>
                    <p className="text-xs text-slate-500 font-medium mt-1">
                      {(file.size / 1024 / 1024).toFixed(2)} MB
                    </p>
                  </div>
                ) : (
                  <div className="text-center">
                    <p className="text-sm font-bold text-slate-700">คลิกหรือลากไฟล์ PDF มาวางที่นี่</p>
                    <p className="text-xs text-slate-400 font-medium mt-1">
                      รองรับไฟล์ขนาดไม่เกิน 20MB
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="flex justify-end gap-2 pt-4 border-t border-slate-100">
            <button
              type="button"
              onClick={onClose}
              disabled={isSubmitting}
              className="px-5 py-2.5 rounded-xl font-bold text-sm text-slate-600 hover:bg-slate-100 transition-colors"
            >
              ยกเลิก
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !file}
              className="px-5 py-2.5 rounded-xl font-bold text-sm bg-blue-600 hover:bg-blue-700 text-white shadow-md shadow-blue-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {isSubmitting ? "กำลังอัปโหลด..." : "อัปโหลดและส่งกลับ (Draft)"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import { Download, FileText } from "lucide-react";
import { downloadDocument } from "@views/features/documents/api";
import { useAuth } from "@views/components/providers/AuthProvider";
import { useToast } from "@views/components/providers/ToastProvider";
import PRForm from "@views/components/forms/PRForm";
import POForm from "@views/components/forms/POForm";
import BKForm from "@views/components/forms/BKForm";

interface DocumentPreviewProps {
  doc: any;
  versionId?: string;
  hideHeader?: boolean;
  isViewer?: boolean;
  tempSignature?: boolean;
  onSignClick?: () => void;
}

export function DocumentPreview({
  doc: initialDoc,
  versionId,
  hideHeader,
  isViewer,
  tempSignature,
  onSignClick,
}: DocumentPreviewProps) {
  let doc = initialDoc as any;
  const rawType = doc?.type || doc?.doc_type;
  const rawPrefix =
    (typeof rawType === "object" ? rawType?.prefix : rawType) ||
    (doc?.doc_number || doc?.id || "").split("-")[0] ||
    "OTHER";
  const resolvedTypePrefix = String(rawPrefix).toUpperCase();

  if (versionId && doc?.versions) {
    const version = doc.versions.find(
      (v: any) =>
        v.id === versionId ||
        v.version_number?.toString() === versionId.toString(),
    );
    const docTypePrefix = resolvedTypePrefix;
    if (version && version.form_data) {
      doc = { ...doc };
      const vFormData = version.form_data;
      const meta = vFormData._meta;
      doc = {
        ...doc,
        ...(meta ?? {}),
        _meta: meta,
        workflow: meta?.workflow ?? null,
        creator: meta?.creator ?? doc.creator,
        department: meta?.creator?.department?.name ?? doc.department,
        doc_number: meta?.doc_number ?? doc.doc_number,
        title: meta?.title ?? doc.title,
      };
      if (!["PR", "PO", "BK", "MEMO"].includes(docTypePrefix))
        doc.fileUrl = version.download_url;
      if (docTypePrefix === "PR") {
        doc.pr_form =
          vFormData.items &&
          Array.isArray(vFormData.items) &&
          vFormData.items.length > 0
            ? vFormData
            : { ...vFormData, items: [] };
      } else if (docTypePrefix === "PO") {
        doc.po_form =
          vFormData.items &&
          Array.isArray(vFormData.items) &&
          vFormData.items.length > 0
            ? vFormData
            : { ...vFormData, items: [] };
      } else if (docTypePrefix === "BK" || docTypePrefix === "MEMO") {
        doc.bk_form = vFormData;
      }
    }
  }
  // PR Form Renderer (A4 Style)
  const renderPRForm = () => {
    const form = doc.pr_form;
    if (!form)
      return (
        <div className="text-center p-8 text-slate-500">
          ไม่พบข้อมูล PR Form
        </div>
      );
    return (
      <div className="w-full relative">
        <PRForm
          isViewer={true}
          tempSignature={tempSignature}
          onSignClick={onSignClick}
          initialData={doc}
          currentStep={1}
          runningNumberPreview={doc.doc_number || doc.id}
          onSubmit={() => {}}
          onCancel={() => {}}
          onNext={() => {}}
          onBack={() => {}}
        />
      </div>
    );
  };

  // PO Form Renderer (A4 Style)
  const renderPOForm = () => {
    const form = doc.po_form;
    if (!form)
      return (
        <div className="text-center p-8 text-slate-500">
          ไม่พบข้อมูล PO Form
        </div>
      );
    return (
      <div className="w-full relative">
        <POForm
          isViewer={true}
          tempSignature={tempSignature}
          onSignClick={onSignClick}
          initialData={doc}
          currentStep={1}
          runningNumberPreview={doc.doc_number || doc.id}
          onSubmit={() => {}}
          onCancel={() => {}}
          onNext={() => {}}
          onBack={() => {}}
        />
      </div>
    );
  };

  // BK Form Renderer (A4 Style)
  const renderBKForm = () => {
    return (
      <div className="w-full relative">
        <BKForm
          isViewer={true}
          tempSignature={tempSignature}
          onSignClick={onSignClick}
          initialData={doc}
          currentStep={1}
          runningNumberPreview={doc.doc_number || doc.id}
          onSubmit={() => {}}
          onCancel={() => {}}
          onNext={() => {}}
          onBack={() => {}}
        />
      </div>
    );
  };

  const type = versionId ? "PDF" : resolvedTypePrefix;
  const { user } = useAuth();
  const { showToast } = useToast();
  const canPreview = user?.permissions?.some((p) =>
    [
      "document.preview_document:view",
      "approvals.open_doc_detail:view",
    ].includes(p),
  );
  const canDownload = user?.permissions?.some((p) =>
    [
      "document.download_document:view",
      "submissions.download_document:view",
      "approvals.download_document:view",
    ].includes(p),
  );

  // PDF Renderer
  const renderPDF = () => {
    const docId = doc?.real_id || doc?.id;
    const matchedVersion = doc.versions?.find(
      (v: any) =>
        v.id === versionId || String(v.version_number) === String(versionId),
    );
    const vParam = matchedVersion ? `?v=${matchedVersion.version_number}` : "";
    const fileUrl = versionId
      ? matchedVersion
        ? matchedVersion.download_url ||
          `/api/documents/${docId}/download${vParam}`
        : null
      : doc?.fileUrl || (docId ? `/api/documents/${docId}/download` : null);

    return (
      <div className="bg-slate-200/70 rounded-xl p-4 sm:p-8 border border-slate-200 min-h-[400px] flex flex-col relative overflow-hidden">
        <div className="flex justify-between items-center bg-white p-4 rounded-t-xl border-b border-slate-200">
          <div className="flex items-center gap-2 text-slate-600">
            <FileText className="w-5 h-5 text-rose-500" />
            <span className="font-bold text-sm">PDF Document Viewer</span>
          </div>
          {docId && canDownload && (
            <button
              type="button"
              onClick={() => {
                downloadDocument(
                  docId,
                  matchedVersion?.version_number,
                  `${doc.doc_number || doc.id}.pdf`,
                ).catch((e) =>
                  showToast(
                    e instanceof Error ? e.message : String(e),
                    "error",
                  ),
                );
              }}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-lg text-xs transition-colors cursor-pointer"
            >
              <Download className="w-3.5 h-3.5" />
              ดาวน์โหลด (Download)
            </button>
          )}
        </div>
        <div className="flex-1 bg-white rounded-b-xl overflow-hidden relative flex flex-col items-center justify-center">
          {!canPreview ? (
            <p className="p-8 text-slate-500">ไม่มีสิทธิ์พรีวิวเอกสาร</p>
          ) : fileUrl ? (
            <iframe
              src={`${fileUrl}#toolbar=0`}
              className="w-full h-full min-h-[600px] border-none"
              title="PDF Preview"
            />
          ) : (
            <div className="text-center p-12 text-slate-400">
              <FileText className="w-12 h-12 mx-auto text-slate-300 mb-3" />
              <p className="font-bold text-slate-500">ยังไม่มีไฟล์เอกสารแนบ</p>
              <p className="text-sm mt-1">
                No document file uploaded for this transaction.
              </p>
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className={hideHeader ? "" : "space-y-4"}>
      {/* HEADER */}
      {!hideHeader && (
        <div className="flex justify-between items-center bg-white p-4 rounded-xl border border-slate-100 shadow-sm">
          <div>
            <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider">
              Document Content Preview
            </h4>
            <p className="text-xs text-slate-400 font-medium mt-0.5">
              แสดงเนื้อหาแบบฟอร์มเอกสารหรือไฟล์แนบ (Zero-Click Preview)
            </p>
          </div>
        </div>
      )}

      {(!doc._meta || doc._meta.legacy_snapshot) && (
        <p className="rounded-xl bg-amber-50 p-3 text-xs text-amber-800">
          เอกสารรุ่นเดิมอาจไม่มีภาพลายเซ็นหรือข้อมูลต้นฉบับครบถ้วน
          ระบบแสดงเฉพาะข้อมูลที่บันทึกไว้
        </p>
      )}
      {/* CONTENT */}
      {type === "PR"
        ? renderPRForm()
        : type === "PO"
          ? renderPOForm()
          : type === "บันทึก" || type === "BK"
            ? renderBKForm()
            : renderPDF()}
    </div>
  );
}

"use client";

import React from "react";
import { Folder, VISIBILITY_LABEL, VISIBILITY_COLOR } from "@views/features/folders/types";
   
   
import { MoreVertical, Edit2, Trash2, Pin } from "lucide-react";
import { FolderIconRenderer } from "./FolderIconRenderer";

interface FolderCardProps {
  folder: Folder;
  isActive?: boolean;
  isPinned?: boolean;
  onClick: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  onTogglePin?: () => void;
}

export function FolderCard({ folder, isActive, isPinned, onClick, onEdit, onDelete, onTogglePin }: FolderCardProps) {
  const [showMenu, setShowMenu] = React.useState(false);

  // Safe hex to rgba converter
  const getRgba = (hex: string, alpha: number) => {
    let cleanHex = hex.replace("#", "");
    if (cleanHex.length === 3) {
      cleanHex = cleanHex.split("").map((c) => c + c).join("");
    }
    if (cleanHex.length !== 6) return `rgba(79, 129, 255, ${alpha})`; // Fallback blue
    const r = parseInt(cleanHex.slice(0, 2), 16);
    const g = parseInt(cleanHex.slice(2, 4), 16);
    const b = parseInt(cleanHex.slice(4, 6), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  };

  const bgColor = getRgba(folder.color || "#4F81FF", 0.15);

  return (
    <div
      onClick={onClick}
      className={`group relative rounded-2xl p-4 transition-all cursor-pointer flex flex-col justify-between ${
        isActive
          ? "bg-blue-50/40 border-2 border-blue-600 shadow-md ring-2 ring-blue-600/20"
          : isPinned
          ? "bg-white border-2 border-amber-400 shadow-xs hover:border-amber-500 hover:shadow-md"
          : "bg-white border border-slate-200/80 hover:border-blue-300 hover:shadow-md"
      }`}
    >
      <div className="flex items-start justify-between mb-3">
        <div
          className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl shadow-xs transition-transform ${
            isActive ? "scale-105" : ""
          }`}
          style={{ backgroundColor: bgColor, color: folder.color || "#4F81FF" }}
        >
          <FolderIconRenderer iconName={folder.icon} />
        </div>

        <div className="flex items-center gap-1">
          {isActive && (
            <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-blue-600 text-white shadow-2xs animate-in fade-in">
              ✓ เปิดอยู่
            </span>
          )}

          {/* PIN BUTTON */}
          <button
            type="button"
            title={isPinned ? "ยกเลิกปักหมุด" : "ปักหมุดโฟลเดอร์ไว้บนสุด"}
            onClick={(e) => {
              e.stopPropagation();
              onTogglePin?.();
            }}
            className={`p-1 rounded-lg transition-colors cursor-pointer ${
              isPinned
                ? "text-amber-500 bg-amber-100/80 hover:bg-amber-200"
                : "text-slate-300 hover:text-amber-500 hover:bg-slate-100"
            }`}
          >
            <Pin className={`w-3.5 h-3.5 ${isPinned ? "fill-amber-500" : ""}`} />
          </button>

          

          {folder.can_edit && (
            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity ml-1">
              {onEdit && (
                <button
                  type="button"
                  title="แก้ไข"
                  onClick={(e) => {
                    e.stopPropagation();
                    onEdit();
                  }}
                  className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors bg-white/80 backdrop-blur-sm shadow-xs border border-slate-200/50"
                >
                  <Edit2 className="w-3.5 h-3.5" />
                </button>
              )}
              {onDelete && (
                <button
                  type="button"
                  title="ลบโฟลเดอร์"
                  onClick={(e) => {
                    e.stopPropagation();
                    onDelete();
                  }}
                  className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors bg-white/80 backdrop-blur-sm shadow-xs border border-slate-200/50"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      <div>
        <h3 className="text-sm font-bold text-slate-800 group-hover:text-blue-600 transition-colors truncate">
          {folder.name}
        </h3>
        {folder.description && (
          <p className="text-xs text-slate-400 line-clamp-1 mt-0.5">{folder.description}</p>
        )}
      </div>

      <div className="mt-3 pt-2 border-t border-slate-100 flex items-center justify-between text-[11px] text-slate-400 font-medium">
        <span>{folder.creator?.full_name || "ผู้ใช้งาน"}</span>
        <span className="font-bold text-slate-600 bg-slate-100 px-2 py-0.5 rounded-md">
          {folder.document_count} เอกสาร
        </span>
      </div>
    </div>
  );
}

