"use client";

import React, { useState, useEffect } from "react";
import {
  Folder,
  FolderVisibility,
  CreateFolderPayload,
} from "@views/features/folders/types";

import { X, FolderPlus } from "lucide-react";

interface FolderCreateModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: CreateFolderPayload) => Promise<void>;
  editingFolder?: Folder | null;
  departments?: { id: string; name: string }[];
  parentFolderId?: string | null;
}

const PRESET_ICONS = [
  "📁",
  "📢",
  "📑",
  "📂",
  "💼",
  "🔒",
  "📊",
  "📝",
  "📌",
  "⭐",
];
const PRESET_COLORS = [
  "#4F81FF",
  "#22C55E",
  "#F59E0B",
  "#EF4444",
  "#8B5CF6",
  "#EC4899",
  "#06B6D4",
  "#64748B",
];

export function FolderCreateModal({
  isOpen,
  onClose,
  onSubmit,
  editingFolder,
  departments = [],
  parentFolderId,
}: FolderCreateModalProps) {
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [icon, setIcon] = useState("📁");
  const [color, setColor] = useState("#4F81FF");
  const [visibility, setVisibility] = useState<FolderVisibility>("CompanyWide");
  const [sharedDepartments, setSharedDepartments] = useState<string[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (editingFolder) {
      setName(editingFolder.name);
      setDescription(editingFolder.description || "");
      setIcon(editingFolder.icon || "📁");
      setColor(editingFolder.color || "#4F81FF");
      setVisibility(editingFolder.visibility);
      setSharedDepartments(
        (editingFolder as Folder & { shared_departments?: string[] })
          .shared_departments || [],
      );
    } else {
      setName("");
      setDescription("");
      setIcon("📁");
      setColor("#4F81FF");
      setVisibility("CompanyWide");
      setSharedDepartments([]);
    }
  }, [editingFolder, isOpen]);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    try {
      setIsSubmitting(true);
      await onSubmit({
        name: name.trim(),
        description: description.trim() || undefined,
        icon,
        color,
        visibility,
        parent_id: parentFolderId || null,
        shared_departments:
          visibility === "Shared" ? sharedDepartments : undefined,
      });
      onClose();
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-xs p-4 animate-in fade-in">
      <div className="bg-white rounded-3xl shadow-xl border border-slate-100 w-full max-w-md p-6 relative">
        <button
          type="button"
          onClick={onClose}
          className="absolute top-5 right-5 text-slate-400 hover:text-slate-600 p-1 rounded-xl hover:bg-slate-100 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>

        <div className="flex items-center gap-3 mb-5">
          <div className="w-10 h-10 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center font-bold">
            <FolderPlus className="w-5 h-5" />
          </div>
          <div>
            <h2 className="text-base font-bold text-slate-800">
              {editingFolder ? "แก้ไขโฟลเดอร์" : "สร้างโฟลเดอร์ใหม่"}
            </h2>
            <p className="text-xs text-slate-400">
              จัดระเบียบเอกสารสำหรับการทำงานร่วมกัน
            </p>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Name & Icon */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">
              ชื่อโฟลเดอร์ *
            </label>
            <div className="flex items-center gap-2">
              {/* Icon selector */}
              <select
                value={icon}
                onChange={(e) => setIcon(e.target.value)}
                className="bg-slate-50 border border-slate-200 rounded-xl px-2.5 py-2 text-base focus:outline-none cursor-pointer"
              >
                {PRESET_ICONS.map((i) => (
                  <option key={i} value={i}>
                    {i}
                  </option>
                ))}
              </select>

              <input
                type="text"
                required
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="เช่น เอกสารแผนกจัดซื้อ, สัญญาปี 2569"
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold text-slate-800 focus:outline-none focus:border-blue-500"
              />
            </div>
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">
              รายละเอียด (ถ้ามี)
            </label>
            <textarea
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="ระบุรายละเอียดสั้นๆ..."
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-xs font-medium text-slate-700 focus:outline-none focus:border-blue-500"
            />
          </div>

          {/* Preset Color Picker */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">
              สีไอคอน
            </label>
            <div className="flex items-center gap-2">
              {PRESET_COLORS.map((c) => (
                <button
                  key={c}
                  type="button"
                  onClick={() => setColor(c)}
                  className={`w-6 h-6 rounded-full transition-transform ${
                    color === c
                      ? "scale-125 ring-2 ring-blue-500 ring-offset-2"
                      : "hover:scale-110"
                  }`}
                  style={{ backgroundColor: c }}
                />
              ))}
            </div>
          </div>

          {/* Submit / Cancel Buttons */}
          <div className="flex items-center justify-end gap-2 pt-3 border-t border-slate-100">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs font-bold transition-colors cursor-pointer"
            >
              ยกเลิก
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold transition-all shadow-xs disabled:opacity-50 cursor-pointer"
            >
              {isSubmitting
                ? "กำลังบันทึก..."
                : editingFolder
                  ? "อัปเดตโฟลเดอร์"
                  : "สร้างโฟลเดอร์"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { Folder, VISIBILITY_LABEL } from "@views/features/folders/types";
import {
  Folder as FolderIcon,
  FolderPlus,
  FileText,
   
   
   
  MoreVertical,
   
  Edit2,
  Trash2,
  Lock,
  Users,
  Globe,
  Shield,
  Layers
} from "lucide-react";
import { FolderIconRenderer } from "./FolderIconRenderer";

interface FolderSidebarProps {
  folders: Folder[];
  activeFolderId: string | null | "ALL_DOCS";
  onSelectFolder: (folderId: string | null | "ALL_DOCS") => void;
  onCreateFolder: () => void;
  onEditFolder: (folder: Folder) => void;
  onDeleteFolder: (folder: Folder) => void;
  totalUnorganizedCount?: number;
  totalAllCount?: number;
}

export function FolderSidebar({
  folders,
  activeFolderId,
  onSelectFolder,
  onCreateFolder,
  onEditFolder,
  onDeleteFolder,
  totalUnorganizedCount = 0,
  totalAllCount = 0,
}: FolderSidebarProps) {
  const [activeMenuId, setActiveMenuId] = useState<string | null>(null);

  const getVisibilityIcon = (visibility: string) => {
    switch (visibility) {
      case "Private":
        return <Lock className="w-3 h-3 text-slate-400" />;
      case "Department":
        return <Users className="w-3 h-3 text-blue-500" />;
      case "Shared":
        return <Users className="w-3 h-3 text-violet-500" />;
      case "CompanyWide":
        return <Globe className="w-3 h-3 text-emerald-500" />;
      case "AdminOnly":
        return <Shield className="w-3 h-3 text-rose-500" />;
      default:
        return <Globe className="w-3 h-3 text-slate-400" />;
    }
  };

  return (
    <div className="w-64 bg-white rounded-3xl border border-slate-200/80 shadow-xs p-4 flex flex-col h-full shrink-0 select-none min-h-[600px]">
      {/* Sidebar Header */}
      <div className="flex items-center justify-between px-2 py-2 mb-2">
        <div className="flex items-center gap-2">
          <FolderIcon className="w-4 h-4 text-blue-600" />
          <span className="text-xs font-bold text-slate-700 tracking-wide uppercase">จัดการโฟลเดอร์</span>
        </div>
        <button
          type="button"
          onClick={onCreateFolder}
          className="flex items-center gap-1 text-[11px] font-bold text-blue-600 bg-blue-50 hover:bg-blue-100 border border-blue-200 px-2 py-1 rounded-lg transition-colors cursor-pointer"
        >
          <FolderPlus className="w-3.5 h-3.5" />
          <span>+ ใหม่</span>
        </button>
      </div>

      {/* Primary Fixed Views */}
      <div className="space-y-1 mb-4">
        {/* All Docs */}
        <button
          type="button"
          onClick={() => onSelectFolder("ALL_DOCS")}
          className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
            activeFolderId === "ALL_DOCS"
              ? "bg-blue-600 text-white shadow-xs"
              : "text-slate-700 hover:bg-slate-200/60"
          }`}
        >
          <div className="flex items-center gap-2">
            <Layers className="w-4 h-4" />
            <span>เอกสารทั้งหมด</span>
          </div>
          <span
            className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold ${
              activeFolderId === "ALL_DOCS" ? "bg-white/20 text-white" : "bg-slate-200 text-slate-600"
            }`}
          >
            {totalAllCount}
          </span>
        </button>

        {/* Unorganized Docs */}
        <button
          type="button"
          onClick={() => onSelectFolder(null)}
          className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
            activeFolderId === null
              ? "bg-blue-600 text-white shadow-xs"
              : "text-slate-700 hover:bg-slate-200/60"
          }`}
        >
          <div className="flex items-center gap-2">
            <FileText className="w-4 h-4" />
            <span>ไม่มีโฟลเดอร์</span>
          </div>
          <span
            className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold ${
              activeFolderId === null ? "bg-white/20 text-white" : "bg-slate-200 text-slate-600"
            }`}
          >
            {totalUnorganizedCount}
          </span>
        </button>
      </div>

      <div className="px-2 pb-1 text-[11px] font-bold text-slate-400 uppercase tracking-wider">
        โฟลเดอร์ของฉัน ({folders.length})
      </div>

      {/* Dynamic Folder List */}
      <div className="flex-1 overflow-y-auto space-y-1 pr-1">
        {folders.map((folder) => {
          const isActive = activeFolderId === folder.id;
          const isMenuOpen = activeMenuId === folder.id;

          return (
            <div key={folder.id} className="relative group">
              <div
                onClick={() => onSelectFolder(folder.id)}
                className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-medium transition-all cursor-pointer ${
                  isActive
                    ? "bg-blue-50 border border-blue-200 text-blue-700 font-bold shadow-2xs"
                    : "text-slate-700 hover:bg-slate-200/50"
                }`}
              >
                <div className="flex items-center gap-2 min-w-0 pr-2">
                  <span className="text-base shrink-0"><FolderIconRenderer iconName={folder.icon} className="w-4 h-4" /></span>
                  <span className="truncate text-xs">{folder.name}</span>
                </div>

                <div className="flex items-center gap-1 shrink-0">
                  
                  <span className="text-[10px] font-bold bg-slate-200/80 text-slate-600 px-1.5 py-0.5 rounded-md">
                    {folder.document_count}
                  </span>

                  {folder.can_edit && (
                    <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity ml-0.5">
                      <button
                        type="button"
                        title="แก้ไขโฟลเดอร์"
                        onClick={(e) => {
                          e.stopPropagation();
                          onEditFolder(folder);
                        }}
                        className="p-1 hover:bg-white rounded-lg text-slate-500 hover:text-blue-600 transition-colors cursor-pointer shadow-xs border border-slate-200/50"
                      >
                        <Edit2 className="w-3.5 h-3.5" />
                      </button>
                      <button
                        type="button"
                        title="ลบโฟลเดอร์"
                        onClick={(e) => {
                          e.stopPropagation();
                          onDeleteFolder(folder);
                        }}
                        className="p-1 hover:bg-white rounded-lg text-slate-500 hover:text-rose-600 transition-colors cursor-pointer shadow-xs border border-slate-200/50"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {folders.length === 0 && (
          <div className="py-6 text-center text-xs text-slate-400 font-medium border border-dashed border-slate-200 rounded-xl">
            ยังไม่มีโฟลเดอร์
          </div>
        )}
      </div>
    </div>
  );
}

