source:
"use client";

import React, { useState, useEffect } from "react";
import { Plus, Trash2, Save, Send, UploadCloud } from "lucide-react";
import { api } from "@/lib";
import { useAuth } from "@views/components/providers/AuthProvider";
import { formatThaiDate } from "@/lib/format-date";
import Step2Visibility, { VisibilityData } from "./Step2Visibility";
import ApprovalWorkflowSection, {
  WorkflowStepInput,
} from "./ApprovalWorkflowSection";

export interface PRItemInput {
  id: string;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
  remark: string;
}

export interface PRSubmitData {
  title: string;
  sender: string;
  department: string;
  requestedDate: string;
  requiredDate: string;
  purpose: string;
  remark: string;
  amount: string;
  items: PRItemInput[];
  attachmentFileName?: string;
  workflowSteps: WorkflowStepInput[];
  isDraft: boolean;
  visibility: VisibilityData;
}

interface PRFormProps {
  onSubmit: (data: PRSubmitData) => void;
  onCancel: () => void;
  runningNumberPreview: string;
  currentStep: number;
  onNext: () => void;
  onBack: () => void;
  initialData?: any;
  isViewer?: boolean;
  tempSignature?: boolean;
  onSignClick?: () => void;
}

const UNITS = ["ชิ้น", "เครื่อง", "ชุด", "กล่อง", "แพ็ค", "งวด", "งาน"];

export default function PRForm({
  onSubmit,
  onCancel,
  runningNumberPreview,
  currentStep,
  onNext,
  onBack,
  initialData,
  isViewer,
  tempSignature,
  onSignClick,
}: PRFormProps) {
  const { user } = useAuth();
  const defaultRequester =
    isViewer && initialData?.creator
      ? `${initialData.creator.first_name} ${initialData.creator.last_name}`
      : user?.full_name || user?.username || "";
  const defaultDept = user?.department || "";

  const todayStr = new Date().toISOString().split("T")[0];
  const nextWeekStr = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
    .toISOString()
    .split("T")[0];

  const [companySettings, setCompanySettings] = useState({
    companyName: "บริษัท นิสซุย (ประเทศไทย) จำกัด",
    companyAddress: "เลขที่ 123 อาคารนิสซุย ถนนสุขุมวิท",
  });

  const [title, setTitle] = useState("");
  const [department, setDepartment] = useState(defaultDept);
  const [requestedDate, setRequestedDate] = useState(todayStr);
  const [requiredDate, setRequiredDate] = useState(nextWeekStr);
  const [purpose, setPurpose] = useState("");
  const [remark, setRemark] = useState(
    "เอกสารใบขอซื้อฉบับนี้ใช้สำหรับขออนุมัติภายในก่อนดำเนินการจัดซื้อ",
  );

  const [items, setItems] = useState<PRItemInput[]>([
    {
      id: "1",
      description: "",
      quantity: 1,
      unit: "ชิ้น",
      unitPrice: 0,
      remark: "",
    },
  ]);

  const [visibility, setVisibility] = useState<VisibilityData>({
    type: "CompanyWide",
    departments: [],
    users: [],
  });
  const [workflowSteps, setWorkflowSteps] = useState<WorkflowStepInput[]>([]);
  React.useEffect(() => {
    if (initialData?.visibility) setVisibility(initialData.visibility);
  }, [initialData]);

  useEffect(() => {
    if (initialData?._meta?.company) {
      setCompanySettings(initialData._meta.company);
      return;
    }
    api
      .get<any>("/api/admin/settings")
      .then((res) => {
        if (res.data?.companyName) setCompanySettings(res.data);
      })
      .catch((err) => {
        console.error("Failed to fetch settings:", err);
      });
  }, []);

  useEffect(() => {
    if (initialData) {
      if (initialData.title) setTitle(initialData.title);
      if (initialData.pr_form?.purpose) setPurpose(initialData.pr_form.purpose);
      if (initialData.pr_form?.remark) setRemark(initialData.pr_form.remark);
      if (initialData.department?.name)
        setDepartment(initialData.department.name);
      else if (initialData.department) setDepartment(initialData.department);

      if (initialData.pr_form?.requested_date)
        setRequestedDate(
          new Date(initialData.pr_form.requested_date)
            .toISOString()
            .split("T")[0],
        );
      if (initialData.pr_form?.required_date) {
        const d = new Date(initialData.pr_form.required_date);
        setRequiredDate(d.toISOString().split("T")[0]);
      }

      if (
        initialData.pr_form?.items &&
        Array.isArray(initialData.pr_form.items) &&
        initialData.pr_form.items.length > 0
      ) {
        setItems(
          initialData.pr_form.items.map((item: any, idx: number) => ({
            id: String(idx + 1),
            description: item.item_name || item.description || "",
            quantity: Number(item.quantity) || 1,
            unit: item.unit || "ชิ้น",
            unitPrice: Number(item.unit_price) || 0,
            remark: item.remark || "",
          })),
        );
      }
    }
  }, [initialData]);

  useEffect(() => {
    let active = true;
    async function loadWorkflow() {
      if (isViewer && initialData?.workflow?.steps) {
        setWorkflowSteps(
          initialData.workflow.steps.map((s: any) => ({
            id: String(s.step_order),
            stepOrder: s.step_order,
            roleName: s.approver?.role?.name || "",
            approverName: s.approver
              ? `${s.approver.first_name} ${s.approver.last_name}`
              : "",
            approverId: s.approver_id,
            approver_id: s.approver_id,
            status: s.status,
            signature_url: s.signature_url || s.approver?.signature_url,
            date: s.action_date,
            isCurrentStep: s.step_order === initialData.workflow.current_step,
          })),
        );
        return;
      }
      try {
        const { adminService } =
          await import("@/controllers/services/admin.service");
        const templates = (await adminService.getWorkflowTemplates()) as any[];
        const flow = templates.find((t) => t.prefix === "PR");
        if (active)
          setWorkflowSteps(
            (flow?.steps ?? []).map((role: string, index: number) => {
              const old = initialData?.workflow?.steps?.find(
                (s: any) => s.step_order === index + 1,
              );
              return {
                id: String(index + 1),
                stepOrder: index + 1,
                roleName: role,
                approverId: old?.approver_id,
                approverName: old?.approver
                  ? `${old.approver.first_name} ${old.approver.last_name}`
                  : "",
              };
            }),
          );
      } catch {
        if (active) setWorkflowSteps([]);
      }
    }
    void loadWorkflow();
    return () => {
      active = false;
    };
  }, [initialData, isViewer]);

  const handleAddItem = () => {
    const newId = String(items.length + 1);
    setItems([
      ...items,
      {
        id: newId,
        description: "",
        quantity: 1,
        unit: "ชิ้น",
        unitPrice: 0,
        remark: "",
      },
    ]);
  };

  const handleRemoveItem = (id: string) => {
    if (items.length === 1) return;
    setItems(items.filter((item) => item.id !== id));
  };

  const handleItemChange = (
    id: string,
    field: keyof PRItemInput,
    value: string | number,
  ) => {
    setItems(
      items.map((item) => {
        if (item.id !== id) return item;
        return { ...item, [field]: value };
      }),
    );
  };

  const subTotal = items.reduce(
    (sum, item) => sum + item.quantity * item.unitPrice,
    0,
  );
  const vat = 0;
  const grandTotal = subTotal + vat;

  const handleSubmit = (isDraft: boolean) => {
    onSubmit({
      title,
      sender: defaultRequester,
      department,
      requestedDate,
      requiredDate,
      purpose,
      remark,
      amount: grandTotal.toFixed(2),
      items,
      workflowSteps,
      visibility,
      isDraft,
    });
  };

  return (
    <form className="space-y-6" onSubmit={(e) => e.preventDefault()}>
      {(currentStep === 1 || currentStep === 4) && (
        <>
          {!isViewer && (
            <div className="flex justify-between items-center bg-slate-50 p-4 rounded-xl border border-slate-200 mb-4">
              <div className="text-sm">
                <span className="font-bold text-slate-500 mr-2">
                  Preview ID:
                </span>
                <span className="font-mono text-blue-600">
                  {runningNumberPreview}
                </span>
              </div>
              <div className="text-xs text-slate-400 font-bold flex items-center gap-2">
                <UploadCloud className="w-4 h-4" />
                คลิกที่ข้อความที่มีเส้นประเพื่อพิมพ์ข้อมูลแบบออนไลน์
              </div>
            </div>
          )}

          {/* A4 WYSIWYG Editor Container */}
          <div
            className={`bg-slate-200/50 py-10 flex justify-center overflow-auto rounded-xl border border-slate-200 shadow-inner ${isViewer ? "a4-viewer pointer-events-none" : ""}`}
          >
            <div className="bg-white w-[210mm] min-h-[297mm] shadow-xl flex flex-col p-[12mm] text-[12px] text-slate-800 leading-snug font-sans relative origin-top mx-auto">
              {/* Header Block (Industrial Blue Style) */}
              <div className="flex justify-between items-start border-b-2 border-blue-800 pb-4 mb-4">
                <div className="flex items-start gap-4">
                  <div>
                    <h1 className="font-bold text-lg text-blue-900">
                      {companySettings.companyName}
                    </h1>
                    <p className="text-slate-700 mt-1 max-w-[200px] leading-tight whitespace-pre-wrap">
                      {companySettings.companyAddress}
                    </p>
                  </div>
                </div>

                <div className="flex flex-col items-end">
                  <div className="border-2 border-blue-800 px-4 py-2 mb-2 text-center w-64 bg-blue-100 text-blue-900">
                    <h2 className="text-xl font-black">
                      ใบขออนุมัติจัดซื้อ/จัดจ้าง
                    </h2>
                    <p className="text-xs font-bold uppercase">
                      PURCHASE REQUEST
                    </p>
                  </div>

                  <table className="border-collapse border border-slate-800 text-left text-[11px] w-64">
                    <tbody>
                      <tr>
                        <th className="border border-slate-800 px-2 py-1 bg-blue-50 font-bold w-1/3">
                          เลขที่ / No.
                        </th>
                        <td className="border border-slate-800 px-2 py-1 font-bold text-slate-400 text-center">
                          {runningNumberPreview}
                        </td>
                      </tr>
                      <tr>
                        <th className="border border-slate-800 px-2 py-1 bg-blue-50 font-bold">
                          วันที่ / Date
                        </th>
                        <td className="border border-slate-800 px-2 py-1 text-center font-bold text-slate-900">
                          {formatThaiDate(new Date())}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Requester & Purpose Info */}
              <div className="grid grid-cols-2 gap-4 mb-4">
                {/* Requester Info */}
                <div className="border border-slate-800 p-2">
                  <p className="font-bold border-b border-slate-800 pb-1 mb-2 text-blue-900">
                    ผู้เสนอขอจัดซื้อ / Requester
                  </p>
                  <div className="grid grid-cols-[100px_1fr] gap-x-2 gap-y-1 text-[11px]">
                    <span className="text-slate-600 font-bold">
                      ชื่อ / Name:
                    </span>
                    <span className="font-bold text-slate-900">
                      {defaultRequester}
                    </span>

                    <span className="text-slate-600 font-bold mt-1">
                      แผนก / Dept:
                    </span>
                    <span className="font-bold text-slate-900">
                      {department || "—"}
                    </span>

                    <span className="text-slate-600 font-bold mt-1">
                      เรื่อง / โครงการ:
                    </span>
                    <textarea
                      rows={1}
                      required
                      value={title}
                      onChange={(e) => setTitle(e.target.value)}
                      onInput={(e) => {
                        e.currentTarget.style.height = "auto";
                        e.currentTarget.style.height = `${e.currentTarget.scrollHeight}px`;
                      }}
                      placeholder="ระบุชื่อเรื่องที่ขอซื้อ..."
                      className="border-b border-dotted border-blue-400 pb-1 focus:outline-none focus:border-blue-600 font-bold text-slate-900 bg-blue-50/30 px-1 w-full resize-none overflow-hidden block"
                    />
                  </div>
                </div>

                {/* Purpose Info */}
                <div className="border border-slate-800 p-2">
                  <p className="font-bold border-b border-slate-800 pb-1 mb-2 text-blue-900">
                    วัตถุประสงค์ / Purpose
                  </p>
                  <div className="grid grid-cols-[100px_1fr] gap-x-2 gap-y-1 text-[11px]">
                    <span className="text-slate-600 font-bold mt-1">
                      วัตถุประสงค์:
                    </span>
                    <textarea
                      rows={2}
                      value={purpose}
                      onChange={(e) => setPurpose(e.target.value)}
                      onInput={(e) => {
                        e.currentTarget.style.height = "auto";
                        e.currentTarget.style.height = `${e.currentTarget.scrollHeight}px`;
                      }}
                      placeholder="ระบุวัตถุประสงค์/ความจำเป็น..."
                      className="border-b border-dotted border-blue-400 pb-1 focus:outline-none focus:border-blue-600 font-bold text-slate-900 bg-blue-50/30 px-1 w-full resize-none overflow-hidden block"
                    />

                    <span className="text-slate-600 font-bold mt-1">
                      วันที่ต้องการ:
                    </span>
                    <input
                      type="date"
                      value={requiredDate}
                      onChange={(e) => setRequiredDate(e.target.value)}
                      className="border-b border-dotted border-blue-400 pb-1 focus:outline-none focus:border-blue-600 font-bold text-slate-900 bg-transparent w-full"
                    />
                  </div>
                </div>
              </div>

              {/* Items Table */}
              <div className="flex-1">
                {!isViewer && (
                  <div className="flex justify-end mb-1">
                    <button
                      type="button"
                      onClick={handleAddItem}
                      className="flex items-center gap-1 text-[10px] font-bold text-blue-600 hover:text-blue-700 bg-blue-50 px-2 py-1 rounded cursor-pointer pointer-events-auto"
                    >
                      <Plus className="w-3 h-3" /> เพิ่มรายการ
                    </button>
                  </div>
                )}
                <table className="w-full border-collapse border-2 border-slate-800">
                  <thead>
                    <tr className="bg-blue-100 border-b-2 border-slate-800 text-blue-900">
                      <th className="border-r border-slate-800 py-1 px-1 text-center w-8 font-bold">
                        No.
                      </th>
                      <th className="border-r border-slate-800 py-1 px-1 text-center font-bold">
                        รายการสินค้า / บริการ
                      </th>
                      <th className="border-r border-slate-800 py-1 px-1 text-center w-14 font-bold">
                        จำนวน
                      </th>
                      <th className="border-r border-slate-800 py-1 px-1 text-center w-14 font-bold">
                        หน่วย
                      </th>
                      <th className="border-r border-slate-800 py-1 px-1 text-center w-24 font-bold">
                        ราคา/หน่วย
                      </th>
                      <th className="border-r border-slate-800 py-1 px-1 text-center w-24 font-bold">
                        จำนวนเงิน
                      </th>
                      {!isViewer && (
                        <th className="py-1 px-1 text-center w-8"></th>
                      )}
                    </tr>
                  </thead>
                  <tbody>
                    {items.map((item, idx) => {
                      const itemTotal = item.quantity * item.unitPrice;

                      return (
                        <tr
                          key={item.id}
                          className="border-b border-slate-400 group hover:bg-slate-50"
                        >
                          <td className="border-r border-slate-800 py-1 px-1 text-center align-middle">
                            {idx + 1}
                          </td>
                          <td className="border-r border-slate-800 py-1 px-1 align-top">
                            <textarea
                              rows={1}
                              required
                              value={item.description}
                              onChange={(e) =>
                                handleItemChange(
                                  item.id,
                                  "description",
                                  e.target.value,
                                )
                              }
                              onInput={(e) => {
                                e.currentTarget.style.height = "auto";
                                e.currentTarget.style.height = `${e.currentTarget.scrollHeight}px`;
                              }}
                              placeholder="ระบุชื่อสินค้า/บริการ..."
                              className="w-full bg-transparent border-none text-xs font-semibold text-slate-900 placeholder-slate-300 focus:outline-none focus:ring-1 focus:ring-blue-400 p-1 resize-none overflow-hidden block"
                            />
                            <textarea
                              rows={1}
                              value={item.remark}
                              onChange={(e) =>
                                handleItemChange(
                                  item.id,
                                  "remark",
                                  e.target.value,
                                )
                              }
                              onInput={(e) => {
                                e.currentTarget.style.height = "auto";
                                e.currentTarget.style.height = `${e.currentTarget.scrollHeight}px`;
                              }}
                              placeholder="หมายเหตุ..."
                              className="w-full bg-transparent border-none text-[10px] text-slate-500 placeholder-slate-300 focus:outline-none mt-1 px-1 resize-none overflow-hidden block"
                            />
                          </td>
                          <td className="border-r border-slate-800 py-1 px-1 align-middle text-center">
                            <input
                              type="number"
                              min="1"
                              required
                              value={item.quantity}
                              onChange={(e) =>
                                handleItemChange(
                                  item.id,
                                  "quantity",
                                  Math.max(1, parseFloat(e.target.value) || 0),
                                )
                              }
                              className="w-10 text-center bg-transparent focus:outline-none focus:bg-blue-50 p-1 font-bold text-slate-900"
                            />
                          </td>
                          <td className="border-r border-slate-800 py-1 px-1 align-middle text-center">
                            <select
                              value={item.unit}
                              onChange={(e) =>
                                handleItemChange(
                                  item.id,
                                  "unit",
                                  e.target.value,
                                )
                              }
                              className="w-14 bg-transparent focus:outline-none focus:bg-blue-50 text-[11px] p-1 cursor-pointer font-bold text-slate-900"
                            >
                              {UNITS.map((u) => (
                                <option key={u} value={u}>
                                  {u}
                                </option>
                              ))}
                            </select>
                          </td>
                          <td className="border-r border-slate-800 py-1 px-1 align-middle text-right">
                            <input
                              type="number"
                              min="0"
                              step="0.01"
                              required
                              value={item.unitPrice || ""}
                              onChange={(e) =>
                                handleItemChange(
                                  item.id,
                                  "unitPrice",
                                  Math.max(0, parseFloat(e.target.value) || 0),
                                )
                              }
                              placeholder="0"
                              className="w-20 text-right bg-transparent focus:outline-none focus:bg-blue-50 p-1 font-bold text-slate-900"
                            />
                          </td>
                          <td className="border-r border-slate-800 py-2 px-2 text-right align-middle font-bold text-slate-900">
                            {itemTotal.toLocaleString("th-TH", {
                              minimumFractionDigits: 2,
                              maximumFractionDigits: 2,
                            })}
                          </td>
                          {!isViewer && (
                            <td className="py-1 px-1 text-center align-middle">
                              <button
                                type="button"
                                onClick={() => handleRemoveItem(item.id)}
                                disabled={items.length === 1}
                                className="text-slate-300 hover:text-rose-500 disabled:opacity-30 cursor-pointer pointer-events-auto"
                              >
                                <Trash2 className="w-3.5 h-3.5" />
                              </button>
                            </td>
                          )}
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>

              {/* Footer Totals */}
              <div className="mt-4 grid grid-cols-[1fr_auto] border-2 border-slate-800 items-stretch">
                <div className="p-3 border-r-2 border-slate-800 flex flex-col justify-between">
                  <div>
                    <span className="font-bold text-slate-900">
                      หมายเหตุ / Remarks:
                    </span>
                    <textarea
                      rows={2}
                      value={remark}
                      onChange={(e) => setRemark(e.target.value)}
                      onInput={(e) => {
                        e.currentTarget.style.height = "auto";
                        e.currentTarget.style.height = `${e.currentTarget.scrollHeight}px`;
                      }}
                      placeholder="เพิ่มหมายเหตุ..."
                      className="w-full mt-1 bg-transparent focus:outline-none focus:bg-blue-50 p-1 text-[11px] text-slate-700 resize-none overflow-hidden"
                    />
                  </div>
                </div>
                <div className="w-[200px] flex flex-col">
                  <div className="grid grid-cols-[100px_1fr] px-2 py-1 border-b border-slate-800 text-[11px]">
                    <span>
                      ยอดรวม
                      <br />
                      <span className="text-[9px]">Sub Total</span>
                    </span>
                    <span className="text-right flex items-center justify-end font-bold">
                      {subTotal.toLocaleString("th-TH", {
                        minimumFractionDigits: 2,
                      })}
                    </span>
                  </div>
                  <div className="grid grid-cols-[100px_1fr] px-2 py-1 border-b border-slate-800 text-[11px]">
                    <span>
                      ภาษีมูลค่าเพิ่ม 0%
                      <br />
                      <span className="text-[9px]">VAT 0%</span>
                    </span>
                    <span className="text-right flex items-center justify-end font-bold">
                      {vat.toLocaleString("th-TH", {
                        minimumFractionDigits: 2,
                      })}
                    </span>
                  </div>
                  <div className="grid grid-cols-[100px_1fr] p-2 bg-blue-800 text-white font-bold flex-1 items-center">
                    <span>
                      ยอดสุทธิ
                      <br />
                      <span className="text-[9px] font-normal">
                        Grand Total
                      </span>
                    </span>
                    <span className="text-right text-lg">
                      ฿
                      {grandTotal.toLocaleString("th-TH", {
                        minimumFractionDigits: 2,
                      })}
                    </span>
                  </div>
                </div>
              </div>

              {/* Signatures Placeholder */}
              <div className="mt-6 grid grid-cols-3 gap-4 text-center">
                <div className="border border-slate-800 p-1 flex flex-col h-28 relative group pointer-events-auto">
                  <div className="flex-1 flex flex-col items-center justify-center relative overflow-hidden w-full bg-white/50">
                    {(() => {
                      const creatorId =
                        initialData?.creator_id ||
                        initialData?.creator?.id ||
                        user?.id;
                      const creatorSig =
                        initialData?.creator?.signature_url ||
                        (!isViewer && creatorId
                          ? `/api/users/${creatorId}/signature`
                          : null);
                      return creatorSig ? (
                        <img
                          src={creatorSig}
                          className="absolute inset-0 w-full h-full object-contain opacity-95 scale-115 p-1"
                          alt="Signature"
                          onError={(e) => {
                            e.currentTarget.style.display = "none";
                          }}
                        />
                      ) : (
                        <span className="text-[10px] text-slate-400">
                          (ระบบจะดึงลายเซ็นต์อัตโนมัติ)
                        </span>
                      );
                    })()}
                  </div>
                  <div className="w-full border-t border-slate-800 pt-1 text-center bg-white z-10 shrink-0">
                    <p className="font-bold text-slate-900 text-[11px]">
                      ผู้จัดทำ (Prepared By)
                    </p>
                    <p className="text-[10px] text-slate-700 mt-0.5">
                      วันที่{" "}
                      {initialData?.created_at
                        ? formatThaiDate(initialData.created_at)
                        : formatThaiDate(new Date())}
                    </p>
                  </div>
                </div>
                {workflowSteps.map((step: any, idx: number) => {
                  const isApproved = step.status === "Approved";
                  const isCurrentStep = step.isCurrentStep;
                  const approverId = step.approver_id || step.approver?.id;
                  const sigSrc =
                    step.signature_url ||
                    step.approver?.signature_url ||
                    (isCurrentStep && tempSignature && user?.id
                      ? `/api/users/${user.id}/signature`
                      : null);

                  return (
                    <div
                      key={idx}
                      className="border border-slate-800 p-1 flex flex-col h-28 relative group pointer-events-auto"
                    >
                      {isApproved || (isCurrentStep && tempSignature) ? (
                        <div className="flex-1 flex flex-col items-center justify-center relative overflow-hidden w-full bg-white/50">
                          <span className="absolute top-1 left-1.5 text-[7px] font-extrabold text-emerald-600 uppercase tracking-tighter z-10 bg-emerald-50/90 px-1 rounded border border-emerald-200/60 shadow-2xs">
                            {isApproved
                              ? "Signed & Approved"
                              : "Signature Preview"}
                          </span>
                          {sigSrc ? (
                            <img
                              src={sigSrc}
                              className="absolute inset-0 w-full h-full object-contain opacity-95 scale-115 p-1"
                              alt="Signature"
                              onError={(e) => {
                                e.currentTarget.style.display = "none";
                              }}
                            />
                          ) : (
                            <span className="text-base leading-tight text-center px-1 truncate max-w-[90%] text-blue-900">
                              {step.approverName ||
                                user?.full_name ||
                                "Approver"}
                            </span>
                          )}
                        </div>
                      ) : isCurrentStep && onSignClick ? (
                        <div
                          className="flex-1 flex flex-col items-center justify-center w-full cursor-pointer hover:bg-blue-50/50 transition-colors"
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            onSignClick();
                          }}
                        >
                          <p className="text-[10px] text-blue-500 font-bold group-hover:underline text-center px-2">
                            คลิกเพื่อวางลายเซ็น
                            <br />
                            <span className="text-[8px] font-normal text-slate-400">
                              (Click to Sign)
                            </span>
                          </p>
                        </div>
                      ) : (
                        <div className="flex-1 flex items-center justify-center text-[10px] text-slate-400">
                          (รออนุมัติตามสายงาน)
                        </div>
                      )}

                      <div className="w-full border-t border-slate-800 pt-1 text-center bg-white z-10 shrink-0">
                        <p
                          className="font-bold text-slate-900 text-[11px] truncate px-1"
                          title={
                            step.roleName || `ผู้อนุมัติลำดับที่ ${idx + 1}`
                          }
                        >
                          {step.roleName || `ผู้อนุมัติลำดับที่ ${idx + 1}`}
                        </p>
                        {step.approverName && (
                          <p className="text-[10px] text-blue-600 font-bold leading-tight">
                            {step.approverName}
                          </p>
                        )}
                        <p className="text-[10px] text-slate-700 mt-0.5">
                          วันที่{" "}
                          {isApproved && step.date
                            ? new Date(step.date).toLocaleDateString("th-TH")
                            : isCurrentStep && tempSignature
                              ? new Date().toLocaleDateString("th-TH")
                              : "____/____/____"}
                        </p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>

          {currentStep === 1 && !isViewer && (
            <div className="flex justify-end pt-4 border-t border-slate-100 mt-6">
              <button
                type="button"
                onClick={(e) => {
                  const form = e.currentTarget.closest("form");
                  if (form && !form.checkValidity()) {
                    form.reportValidity();
                  } else {
                    onNext();
                  }
                }}
                className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl text-sm transition-all shadow-md shadow-blue-100 cursor-pointer"
              >
                Next Step (ถัดไป)
              </button>
            </div>
          )}
          {currentStep === 4 && !isViewer && (
            <div className="flex items-center justify-between pt-4 border-t border-slate-100 mt-6">
              <button
                type="button"
                onClick={onBack}
                className="px-5 py-2.5 border border-slate-200 hover:bg-slate-50 text-slate-600 font-bold rounded-xl text-sm transition-all cursor-pointer"
              >
                Back (ย้อนกลับ)
              </button>
              <div className="flex items-center gap-3">
                <button
                  type="button"
                  onClick={() => handleSubmit(true)}
                  className="flex items-center gap-2 px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-sm transition-all cursor-pointer border border-slate-200"
                >
                  <Save className="w-4 h-4" />
                  Save as Draft (บันทึกร่าง)
                </button>
                <button
                  type="button"
                  onClick={() => handleSubmit(false)}
                  className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl text-sm transition-all shadow-md shadow-blue-100 cursor-pointer active:scale-95"
                >
                  <Send className="w-4 h-4" />
                  Submit PR Document (ส่งขออนุมัติ)
                </button>
              </div>
            </div>
          )}
        </>
      )}

      {currentStep === 2 && (
        <div className="space-y-6">
          <Step2Visibility value={visibility} onChange={setVisibility} />
          <div className="flex justify-between items-center bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
            <button
              type="button"
              onClick={onBack}
              className="px-4 py-2 border border-slate-200 text-slate-600 hover:bg-slate-50 rounded-xl text-xs font-bold transition-colors cursor-pointer"
            >
              ย้อนกลับ
            </button>
            <button
              type="button"
              onClick={(e) => {
                const form = e.currentTarget.closest("form");
                if (form && !form.checkValidity()) {
                  form.reportValidity();
                } else {
                  onNext();
                }
              }}
              className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold transition-colors shadow-xs cursor-pointer"
            >
              ถัดไป (กำหนดสายอนุมัติ)
            </button>
          </div>
        </div>
      )}

      {currentStep === 3 && (
        <div className="space-y-6">
          <ApprovalWorkflowSection
            steps={workflowSteps}
            onChange={setWorkflowSteps}
          />
          <div className="flex justify-between items-center bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
            <button
              type="button"
              onClick={onBack}
              className="px-4 py-2 border border-slate-200 text-slate-600 hover:bg-slate-50 rounded-xl text-xs font-bold transition-colors cursor-pointer"
            >
              ย้อนกลับ
            </button>
            <button
              type="button"
              onClick={(e) => {
                const form = e.currentTarget.closest("form");
                if (form && !form.checkValidity()) {
                  form.reportValidity();
                } else {
                  onNext();
                }
              }}
              className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-bold transition-colors shadow-xs cursor-pointer"
            >
              ถัดไป (ตรวจสอบพรีวิว)
            </button>
          </div>
        </div>
      )}
    </form>
  );
}

"use client";

import React from "react";
import { UploadCloud, Globe, Building, Users } from "lucide-react";

export interface VisibilityData {
  type: "CompanyWide" | "Department" | "SpecificUsers";
  departments: string[];
  users: string[];
}

interface Step2VisibilityProps {
  visibility?: VisibilityData;
  onVisibilityChange?: (data: VisibilityData) => void;
  value?: VisibilityData;
  onChange?: (data: VisibilityData) => void;
  isRequired?: boolean;
}

const DEPARTMENTS = [
  "แผนกจัดซื้อ",
  "แผนกบัญชีและการเงิน",
  "แผนกคลังสินค้าและจัดส่ง",
  "แผนกเทคโนโลยีสารสนเทศ",
  "แผนกทรัพยากรบุคคล",
  "แผนกผลิต",
];

export default function Step2Visibility({
  visibility: propVisibility,
  onVisibilityChange: propOnVisibilityChange,
  value,
  onChange,
  isRequired = false,
}: Step2VisibilityProps) {
  const [departmentsList, setDepartmentsList] = React.useState<
    { id: string; name: string }[]
  >([]);
  const [usersList, setUsersList] = React.useState<any[]>([]);
  const [userSearch, setUserSearch] = React.useState("");

  const currentVisibility: VisibilityData = value ||
    propVisibility || {
      type: "CompanyWide",
      departments: [],
      users: [],
    };

  const handleVisibilityChange = (data: VisibilityData) => {
    if (onChange) onChange(data);
    if (propOnVisibilityChange) propOnVisibilityChange(data);
  };

  const safeType = currentVisibility.type || "CompanyWide";
  const safeDepartments = currentVisibility.departments || [];
  const safeUsers = currentVisibility.users || [];

  React.useEffect(() => {
    import("@/controllers/services/admin.service").then(({ adminService }) => {
      adminService
        .getDepartmentDirectory()
        .then(setDepartmentsList)
        .catch(() => {});
      adminService
        .getUserDirectory()
        .then((res: any) => {
          setUsersList((res || []).filter((u: any) => u.is_active));
        })
        .catch(() => {});
    });
  }, []);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="bg-slate-50/50 p-6 rounded-2xl border border-slate-100">
        <label className="block text-sm font-bold text-slate-700 uppercase tracking-wider mb-4">
          กำหนดสิทธิการมองเห็นเอกสาร (Document Visibility)
        </label>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <button
            type="button"
            onClick={() =>
              handleVisibilityChange({
                ...currentVisibility,
                type: "CompanyWide",
              })
            }
            className={`p-4 rounded-xl border flex flex-col items-center text-center gap-2 transition-all cursor-pointer ${
              safeType === "CompanyWide"
                ? "border-blue-600 bg-blue-50/30 ring-2 ring-blue-600/10 text-blue-700"
                : "border-slate-200 hover:bg-white text-slate-600"
            }`}
          >
            <Globe className="w-6 h-6" />
            <span className="text-sm font-bold">ทุกคนในระบบ</span>
            <span className="text-[10px] text-slate-500 font-medium">
              Company Wide
            </span>
          </button>

          <button
            type="button"
            onClick={() =>
              handleVisibilityChange({
                ...currentVisibility,
                type: "Department",
                departments: safeDepartments,
              })
            }
            className={`p-4 rounded-xl border flex flex-col items-center text-center gap-2 transition-all cursor-pointer ${
              safeType === "Department"
                ? "border-purple-600 bg-purple-50/30 ring-2 ring-purple-600/10 text-purple-700"
                : "border-slate-200 hover:bg-white text-slate-600"
            }`}
          >
            <Building className="w-6 h-6" />
            <span className="text-sm font-bold">ระบุแผนก</span>
            <span className="text-[10px] text-slate-500 font-medium">
              Specific Departments
            </span>
          </button>

          <button
            type="button"
            onClick={() =>
              handleVisibilityChange({
                ...currentVisibility,
                type: "SpecificUsers",
                users: safeUsers,
              })
            }
            className={`p-4 rounded-xl border flex flex-col items-center text-center gap-2 transition-all cursor-pointer ${
              safeType === "SpecificUsers"
                ? "border-emerald-600 bg-emerald-50/30 ring-2 ring-emerald-600/10 text-emerald-700"
                : "border-slate-200 hover:bg-white text-slate-600"
            }`}
          >
            <Users className="w-6 h-6" />
            <span className="text-sm font-bold">ระบุบุคคล</span>
            <span className="text-[10px] text-slate-500 font-medium">
              Specific Users
            </span>
          </button>
        </div>

        {safeType === "Department" && (
          <div className="mt-4 p-4 bg-white border border-slate-200 rounded-xl">
            <p className="text-xs font-bold text-slate-500 mb-2">
              เลือกแผนกที่สามารถเห็นเอกสารได้:
            </p>
            <div className="flex flex-wrap gap-2">
              {departmentsList.map((department) => {
                const isSelected = safeDepartments.includes(department.id);
                return (
                  <button
                    key={department.id}
                    type="button"
                    onClick={() => {
                      const newDepts = isSelected
                        ? safeDepartments.filter((d) => d !== department.id)
                        : [...safeDepartments, department.id];
                      handleVisibilityChange({
                        ...currentVisibility,
                        departments: newDepts,
                      });
                    }}
                    className={`px-3 py-1.5 rounded-lg text-xs font-bold border transition-colors cursor-pointer ${
                      isSelected
                        ? "bg-purple-100 border-purple-300 text-purple-700"
                        : "bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100"
                    }`}
                  >
                    {department.name}
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {safeType === "SpecificUsers" && (
          <div className="mt-4 p-4 bg-white border border-slate-200 rounded-xl relative">
            <p className="text-xs font-bold text-slate-500 mb-2">
              เลือกผู้ใช้งานที่สามารถเห็นเอกสารได้:
            </p>

            {/* Selected Users */}
            <div className="flex flex-wrap gap-2 mb-3">
              {safeUsers.map((username) => {
                const u = usersList.find((x) => x.id === username);
                const displayName = u
                  ? `${u.first_name} ${u.last_name}`
                  : username;
                return (
                  <span
                    key={username}
                    className="inline-flex items-center gap-1 px-2.5 py-1 bg-emerald-100 text-emerald-700 text-xs font-bold rounded-lg border border-emerald-200"
                  >
                    {displayName}
                    <button
                      type="button"
                      onClick={() =>
                        handleVisibilityChange({
                          ...currentVisibility,
                          users: safeUsers.filter((x) => x !== username),
                        })
                      }
                      className="hover:text-emerald-900 cursor-pointer text-base leading-none"
                    >
                      &times;
                    </button>
                  </span>
                );
              })}
            </div>

            <div className="relative">
              <input
                type="text"
                placeholder="พิมพ์ค้นหาชื่อผู้ใช้งานเพื่อเพิ่ม..."
                value={userSearch}
                onChange={(e) => setUserSearch(e.target.value)}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-xs font-bold text-slate-700 focus:outline-none focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500"
              />
              {userSearch && (
                <div className="absolute top-full left-0 right-0 mt-1 max-h-48 overflow-y-auto bg-white border border-slate-200 rounded-lg shadow-lg z-50">
                  {usersList
                    .filter(
                      (u) =>
                        !safeUsers.includes(u.id) &&
                        (u.username
                          .toLowerCase()
                          .includes(userSearch.toLowerCase()) ||
                          `${u.first_name} ${u.last_name}`
                            .toLowerCase()
                            .includes(userSearch.toLowerCase())),
                    )
                    .map((u) => (
                      <div
                        key={u.id}
                        onClick={() => {
                          handleVisibilityChange({
                            ...currentVisibility,
                            users: [...safeUsers, u.id],
                          });
                          setUserSearch("");
                        }}
                        className="px-3 py-2 hover:bg-slate-50 text-xs font-bold cursor-pointer text-slate-700 border-b border-slate-50 last:border-0"
                      >
                        {u.first_name} {u.last_name}{" "}
                        <span className="text-slate-400 font-normal">
                          (@{u.username})
                        </span>
                      </div>
                    ))}
                  {usersList.filter(
                    (u) =>
                      !safeUsers.includes(u.id) &&
                      (u.username
                        .toLowerCase()
                        .includes(userSearch.toLowerCase()) ||
                        `${u.first_name} ${u.last_name}`
                          .toLowerCase()
                          .includes(userSearch.toLowerCase())),
                  ).length === 0 && (
                    <div className="px-3 py-2 text-xs text-slate-400 text-center">
                      ไม่พบผู้ใช้งาน
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

