"use client";

import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import {
  api,
   
   
   
} from "@/lib";
   
   

   
type AuthUser = {
  id: string;
  full_name: string;
  username: string;
  role: string;
  department: string | null;
  email?: string;
  employee_id?: string;
  position?: string;
  joined_at?: string;
  signature_url?: string | null;
  permissions?: string[];
};

type AuthContextValue = {
  user: AuthUser | null;
  loading: boolean;
  isAuthenticated: boolean;
  login: (username: string, password: string) => Promise<AuthUser>;
  logout: () => void;
};

const globalForAuth = globalThis as unknown as {
  AuthContext: React.Context<AuthContextValue | undefined>
};

const AuthContext = globalForAuth.AuthContext || createContext<AuthContextValue | undefined>(undefined);
if (process.env.NODE_ENV !== "production") {
  globalForAuth.AuthContext = AuthContext;
}

const PUBLIC_ROUTES = ["/auth/login", "/auth", "/login", "/forgot-password", "/reset-password"];

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const pathname = usePathname();

  useEffect(() => {
    api
      .get<AuthUser>("/api/auth/me")
      .then((response) => {
        setUser(response.data);
      })
      .catch(() => {
        setUser(null);
      })
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    if (loading) return;

    const isPublic = PUBLIC_ROUTES.some(
      (route) => pathname === route || pathname.startsWith(`${route}/`)
    );

    if (!user && !isPublic) {
      setTimeout(() => router.replace("/login"), 0);
      return;
    }

    if (user && (pathname === "/login" || pathname.startsWith("/auth"))) {
      setTimeout(() => router.replace("/dashboard"), 0);
    }
  }, [user, loading, pathname, router]);

  const login = async (username: string, password: string) => {
    const response = await api.post<{ user: AuthUser }>(
      "/api/auth/login",
      { username: username.trim(), password }
    );
    const profile = response.data.user;
    setUser(profile);
    return profile;
  };

  const logout = async () => {
    try {
      await api.post("/api/auth/logout");
    } catch {}
    setUser(null);
    router.replace("/login");
  };

  const value = useMemo<AuthContextValue>(
    () => ({
      user,
      loading,
      isAuthenticated: Boolean(user),
      login,
      logout,
    }),
    [user, loading]
  );

     
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuth must be used within AuthProvider");
  }
  return ctx;
}

"use client";

import React, {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  useEffect,
} from "react";

import { type SignatureRecord } from "@views/features/master-data";

type AddSignatureInput = {
  approverName: string;
  position: string;
  imageUrl?: string;
};

type SignatureContextValue = {
  signatures: SignatureRecord[];
  addSignature: (input: AddSignatureInput) => SignatureRecord;
  updateSignature: (id: string, patch: Partial<SignatureRecord>) => void;
  toggleSignatureActive: (id: string) => void;
  saveSignatureRecord: (record: SignatureRecord) => void;
  findByApproverName: (name: string) => SignatureRecord | undefined;
};

import { adminService } from "@/controllers/services/admin.service";

const globalForSignature = globalThis as unknown as {
  SignatureContext: React.Context<SignatureContextValue | undefined>;
};

const SignatureContext =
  globalForSignature.SignatureContext ||
  createContext<SignatureContextValue | undefined>(undefined);

if (process.env.NODE_ENV !== "production") {
  globalForSignature.SignatureContext = SignatureContext;
}

import { useAuth } from "@views/components/providers/AuthProvider";

export function SignatureProvider({ children }: { children: React.ReactNode }) {
  const [signatures, setSignatures] = useState<SignatureRecord[]>([]);
  const { user } = useAuth();

  useEffect(() => {
    setSignatures([]);
    if (
      user?.permissions?.some((p) =>
        ["masterdata.access:view", "masterdata.signatures:view"].includes(p),
      )
    ) {
      adminService
        .getSignaturesList()
        .then((data) => setSignatures(data as SignatureRecord[]))
        .catch(() => {});
    }
  }, [user]);

  const addSignature = useCallback((input: AddSignatureInput) => {
    const record: SignatureRecord = {
      id: String(Date.now()),
      approverName: input.approverName.trim(),
      position: input.position.trim(),
      signedCount: 0,
      isActive: true,
      imageUrl: input.imageUrl,
    };
    setSignatures((prev) => [...prev, record]);
    return record;
  }, []);

  const updateSignature = useCallback(
    (id: string, patch: Partial<SignatureRecord>) => {
      setSignatures((prev) =>
        prev.map((row) => (row.id === id ? { ...row, ...patch } : row)),
      );
    },
    [],
  );

  const toggleSignatureActive = useCallback((id: string) => {
    setSignatures((prev) =>
      prev.map((row) =>
        row.id === id ? { ...row, isActive: !row.isActive } : row,
      ),
    );
  }, []);

  const saveSignatureRecord = useCallback((record: SignatureRecord) => {
    setSignatures((prev) => {
      const idx = prev.findIndex((r) => r.id === record.id);
      if (idx >= 0) {
        const list = [...prev];
        list[idx] = record;
        return list;
      }
      return [...prev, record];
    });
  }, []);

  const findByApproverName = useCallback(
    (name: string) => signatures.find((row) => row.approverName === name),
    [signatures],
  );

  const value = useMemo(
    () => ({
      signatures,
      addSignature,
      updateSignature,
      toggleSignatureActive,
      saveSignatureRecord,
      findByApproverName,
    }),
    [
      signatures,
      addSignature,
      updateSignature,
      toggleSignatureActive,
      saveSignatureRecord,
      findByApproverName,
    ],
  );

  return (
    <SignatureContext.Provider value={value}>
      {children}
    </SignatureContext.Provider>
  );
}

export function useSignatures() {
  const ctx = useContext(SignatureContext);
  if (!ctx) {
    throw new Error("useSignatures must be used within SignatureProvider");
  }
  return ctx;
}

"use client";

import React from "react";

export interface DocTypeInfo {
  code: string;
  label: string;
  badgeClass: string;
}

export function resolveDocType(docId?: string, type?: unknown): DocTypeInfo {
  let raw = "";
  if (typeof type === "string") {
    raw = type;
  } else if (type && typeof type === "object") {
    raw =
      (type as any).prefix ||
      (type as any).code ||
      (type as any).type_name ||
      (type as any).name ||
      "";
  }
  if (!raw && docId) {
    const parts = docId.split("-");
    raw = parts[0] || "";
  }

  const upper = (raw || "").trim().toUpperCase();
  const upperId = (docId || "").trim().toUpperCase();

  if (upper.startsWith("PR") || upperId.startsWith("PR")) {
    return {
      code: "PR",
      label: "PR",
      badgeClass: "bg-blue-50 text-blue-700 border-blue-200",
    };
  }

  if (upper.startsWith("PO") || upperId.startsWith("PO")) {
    return {
      code: "PO",
      label: "PO",
      badgeClass: "bg-purple-50 text-purple-700 border-purple-200",
    };
  }

  if (
    upper.startsWith("BK") ||
    upperId.startsWith("BK") ||
    upper.includes("MEMO") ||
    upper.includes("บันทึก")
  ) {
    return {
      code: "BK",
      label: "BK",
      badgeClass: "bg-emerald-50 text-emerald-700 border-emerald-200",
    };
  }

  if (upper.startsWith("CERT") || upperId.startsWith("CERT")) {
    return {
      code: "CERT",
      label: "CERT",
      badgeClass: "bg-teal-50 text-teal-700 border-teal-200",
    };
  }

  if (
    upper.startsWith("DOC") ||
    upperId.startsWith("DOC") ||
    upper === "OTHER" ||
    upper === "GENERAL" ||
    upper.includes("ทั่วไป")
  ) {
    return {
      code: "DOC",
      label: "DOC",
      badgeClass: "bg-amber-50 text-amber-700 border-amber-200",
    };
  }

  const fallbackLabel = upper ? upper.slice(0, 4) : "DOC";
  return {
    code: fallbackLabel,
    label: fallbackLabel,
    badgeClass: "bg-slate-50 text-slate-700 border-slate-200",
  };
}

interface DocTypeBadgeProps {
  docId?: string;
  type?: unknown;
  className?: string;
}

export default function DocTypeBadge({
  docId,
  type,
  className = "",
}: DocTypeBadgeProps) {
  const info = resolveDocType(docId, type);

  return (
    <div
      className={`w-12 h-8 rounded-xl shrink-0 border flex items-center justify-center font-bold text-xs select-none shadow-2xs transition-colors ${info.badgeClass} ${className}`}
      title={`ประเภท: ${info.label}`}
    >
      {info.label}
    </div>
  );
}

