"use client";

import React, { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { usePathname, useSearchParams } from "next/navigation";
import {
  LayoutDashboard,
  FileText,
  CheckSquare,
  Database,
  BarChart3,
  Settings,
  ChevronLeft,
  ChevronRight,
  LogOut,
  FileBox,
  Folder,
  Activity,
  User,
  Send,
} from "lucide-react";
import { Avatar, AvatarFallback } from "@views/components/ui/avatar";
import { useAuth } from "@views/components/providers/AuthProvider";
import { useSidebar } from "@views/components/providers/SidebarProvider";
import useSWR from "swr";
import { getApprovals } from "@views/features/workflow/api";

type NavItem = {
  name: string;
  href: string;
  icon?: React.ElementType;
  tablerIcon?: string;
  roles?: string[];
  permission?: string;
};

type NavGroup = {
  name: string;
  href: string;
  tablerIcon?: string;
  icon?: any;
  /** permission key that must exist to see this item: "section.item:action" */
  permission?: string;
  children: NavItem[];
};

// permission key format: "section.item:action"
// no permission = visible to all authenticated users
const FLAT_NAV_ITEMS: NavItem[] = [
  { name: "แดชบอร์ด", href: "/dashboard", icon: LayoutDashboard },
  {
    name: "ส่งเรื่องขออนุมัติ",
    href: "/submissions",
    icon: Send,
    roles: [],
    permission: "submissions.view_list:view",
  },
  {
    name: "รายการรออนุมัติ",
    href: "/approvals",
    icon: CheckSquare,
    roles: [],
    permission: "approvals.view_list:view",
  },
  {
    name: "Master Data",
    href: "/admin/master-data",
    icon: Database,
    roles: [],
    permission: "masterdata.access:view",
  },
  {
    name: "Reports",
    href: "/admin/reports",
    icon: BarChart3,
    roles: [],
    permission: "reports.access:view",
  },
  {
    name: "Audit Logs",
    href: "/admin/audit-logs",
    icon: Activity,
    roles: [],
    permission: "auditlog.access:view",
  },
  { name: "Profile", href: "/profile", icon: User },
];

const DOCUMENTS_GROUP: NavGroup = {
  name: "คลังเอกสาร",
  href: "/documents",
  icon: FileBox,
  children: [
    { name: "เอกสารทั้งหมด", href: "/documents", icon: FileText, roles: [] },
    { name: "โฟลเดอร์", href: "/folders", icon: Folder, roles: [] },
  ],
};

const CONFIG_GROUP: NavGroup = {
  name: "Config",
  href: "/admin/config",
  tablerIcon: "settings-2",
  permission: "config.access:view",
  children: [
    {
      name: "General",
      href: "/admin/config/general",
      tablerIcon: "adjustments",
      roles: [],
      permission: "config.access:view",
    },
    {
      name: "Roles",
      href: "/admin/config/roles",
      tablerIcon: "shield-lock",
      roles: [],
      permission: "config.role_management:view",
    },
    {
      name: "Users",
      href: "/admin/config/users",
      tablerIcon: "users",
      roles: [],
      permission: "config.user_management:view",
    },
  ],
};

function hasAccess(
  item: { roles?: string[]; permission?: string },
  userRole?: string,
  permissions?: string[],
) {
  // If item has a permission key, check it
  if (item.permission) {
    return permissions?.includes(item.permission) ?? false;
  }
  // No restrictions
  return true;
}

function isDocsRoute(pathname: string) {
  return (
    pathname === "/documents" ||
    pathname.startsWith("/documents/") ||
    pathname === "/folders" ||
    pathname.startsWith("/folders/")
  );
}

function isConfigRoute(pathname: string) {
  return pathname === "/admin/config" || pathname.startsWith("/admin/config/");
}

function isNavItemActive(pathname: string, href: string) {
  if (isConfigRoute(pathname) || isDocsRoute(pathname)) return false;
  if (pathname === href) return true;
  return pathname.startsWith(`${href}/`);
}

function isChildNavActive(pathname: string, href: string) {
  if (pathname === href) return true;
  return pathname.startsWith(`${href}/`);
}

const NAV_ICON = "size-5 shrink-0";
const TABLER_ICON = `ti flex ${NAV_ICON} items-center justify-center text-[1.25rem] leading-none`;

function navItemClass(isActive: boolean, isOpen: boolean, isChild = false) {
  const layout = isOpen
    ? isChild
      ? "gap-3.5 py-2.5 pl-12 pr-4"
      : "gap-3.5 px-4 py-2.5"
    : "justify-center p-3";

  const activeCls = isChild
    ? "bg-blue-50 font-semibold text-blue-600"
    : "border-blue-600 bg-blue-50 font-semibold text-blue-600";
  const inactiveCls = isChild
    ? "text-slate-500 hover:bg-slate-50 hover:text-slate-900"
    : "border-transparent text-slate-500 hover:bg-slate-50 hover:text-slate-900";

  return `flex items-center rounded-xl text-sm font-medium transition-colors ${isChild ? "" : "border-l-2"} ${layout} ${
    isActive ? activeCls : inactiveCls
  }`;
}

export default function Sidebar() {
  const { isOpen, toggle } = useSidebar();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const folderId = searchParams?.get("folderId");
  const source = searchParams?.get("source");

  const { user, logout } = useAuth();
  const { data: approvals } = useSWR(
    user?.permissions?.includes("approvals.view_list:view")
      ? ["approvals-sidebar", user.id]
      : null,
    getApprovals,
    { refreshInterval: 15000 },
  );
  const [lastViewed, setLastViewed] = useState(0);

  useEffect(() => {
    if (typeof window !== "undefined") {
      setLastViewed(
        parseInt(localStorage.getItem("lastViewedApprovals") || "0", 10),
      );
    }
  }, []);

  useEffect(() => {
    if (pathname === "/approvals") {
      const now = Date.now();
      localStorage.setItem("lastViewedApprovals", now.toString());
      setLastViewed(now);
    }
  }, [pathname]);
  const [configExpanded, setConfigExpanded] = useState(() =>
    isConfigRoute(pathname),
  );
  const [docsExpanded, setDocsExpanded] = useState(
    () => isDocsRoute(pathname) && source !== "submissions",
  );

  useEffect(() => {
    if (isConfigRoute(pathname)) {
      setConfigExpanded(true);
    }
    if (isDocsRoute(pathname) && source !== "submissions") {
      setDocsExpanded(true);
    }
  }, [pathname, source]);

  useEffect(() => {
    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href =
      "https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@latest/tabler-icons.min.css";
    document.head.appendChild(link);
    return () => {
      document.head.removeChild(link);
    };
  }, []);

  const displayName = user?.full_name || user?.username || "User";
  const displaySub = user?.username || "user@dms.local";
  const initials = useMemo(() => {
    const sourceStr = (displayName || displaySub).trim();
    return sourceStr ? sourceStr.charAt(0).toUpperCase() : "U";
  }, [displayName, displaySub]);

  const unseenCount = useMemo(() => {
    if (!approvals) return 0;
    return approvals.filter(
      (a) => a.status === "Pending" && (a.rawSubmittedDate || 0) > lastViewed,
    ).length;
  }, [approvals, lastViewed]);

  // Highlight parent IF route matches AND (sidebar closed OR menu collapsed)
  const isConfigActive =
    isConfigRoute(pathname) && (!isOpen || !configExpanded);
  const isDocsActive =
    isDocsRoute(pathname) &&
    source !== "submissions" &&
    (!isOpen || !docsExpanded);

  return (
    <aside
      className={`fixed left-0 top-0 z-30 h-screen bg-white border-r border-slate-100 flex flex-col transition-all duration-200 ease-in-out ${
        isOpen ? "w-64" : "w-20"
      }`}
    >
      <div className="p-6 flex-shrink-0">
        <div
          className={`flex items-center ${isOpen ? "gap-3" : "justify-center"}`}
        >
          <div className="w-10 h-10 rounded-xl bg-indigo-600 flex items-center justify-center text-white shadow-sm flex-shrink-0">
            <FileBox className="w-6 h-6" />
          </div>
          {isOpen && (
            <div className="min-w-0">
              <h1 className="font-bold text-slate-900 leading-tight truncate">
                DMS Electronic
              </h1>
              <p className="text-xs text-slate-400 font-semibold truncate">
                Approval System
              </p>
            </div>
          )}
        </div>
      </div>

      <nav className="flex-1 space-y-2 overflow-y-auto px-4 py-2">
        {FLAT_NAV_ITEMS.slice(0, 3)
          .filter((item) => hasAccess(item, user?.role, user?.permissions))
          .map((item) => {
            const Icon = item.icon;
            let isActive = isNavItemActive(pathname, item.href);
            if (item.href === "/submissions" && source === "submissions")
              isActive = true;
            if (item.href === "/approvals" && source === "submissions")
              isActive = false;

            return (
              <Link
                key={item.name}
                href={item.href}
