                      }`}
                    />
                    {!isOpen &&
                      item.href === "/approvals" &&
                      unseenCount > 0 && (
                        <span className="absolute -top-1 -right-1 flex h-3 w-3 items-center justify-center rounded-full bg-red-500 text-[8px] font-bold text-white ring-2 ring-white" />
