"use client";

import type { ApprovalSignatureInput } from "@models";
import React, { useState } from "react";
import { Check, X, Loader2, AlertTriangle, RotateCcw, Ban } from "lucide-react";
import { submitApprove, submitReject } from "@views/features/workflow/api";
import { useRouter } from "next/navigation";
import { useToast } from "@views/components/providers/ToastProvider";
import { swalConfirm, swalError } from "@/lib/swal";
import { mutate } from "swr";

interface ApprovalActionsProps {
  documentId: string;
  signaturePlaced: boolean;
  signatureData?: ApprovalSignatureInput;
  documentVersion: number;
  canApprove?: boolean;
  canReject?: boolean;
  canReturn?: boolean;
  canComment?: boolean;
  activeApproverName?: string;
  currentStep?: number;
}

export function ApprovalActions({
  documentId,
  signaturePlaced,
  signatureData,
  documentVersion,
  canApprove = true,
  canReject = true,
  canReturn = true,
  canComment = true,
  activeApproverName,
  currentStep = 1,
}: ApprovalActionsProps) {
  const [comment, setComment] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectType, setRejectType] = useState<"return" | "cancel">("return");
  const [returnToStep, setReturnToStep] = useState<number>(1);
  const router = useRouter();
  const { showToast } = useToast();

  const handleApprove = async () => {
    if (!signaturePlaced) {
      swalError(
        "ต้องประทับลายเซ็นก่อนอนุมัติ",
        "กรุณาวางลายเซ็นบนเอกสาร (หรือกดปุ่มประทับลายเซ็น) ใน PDF Viewer ก่อนทำการอนุมัติ",
      );
      return;
    }

    const confirmed = await swalConfirm({
      title: "ยืนยันการอนุมัติเอกสาร?",
      text: "คุณต้องการอนุมัติเอกสารนี้และส่งไปยังขั้นตอนถัดไปหรือไม่?",
      confirmButtonText: "อนุมัติเอกสาร",
      cancelButtonText: "ยกเลิก",
      icon: "question",
      confirmButtonColor: "#2563eb",
    });
    if (!confirmed) return;

    setIsSubmitting(true);
    try {
      await submitApprove(documentId, comment, {
        ...signatureData,
        expected_step: currentStep,
        expected_version: documentVersion,
      });
      showToast("อนุมัติเอกสารเรียบร้อยแล้ว", "success");
      mutate("documents");
      mutate("dashboard");
      router.push("/approvals");
      router.refresh();
    } catch (error: any) {
      showToast(
        (error instanceof Error ? error.message : String(error)) ||
          "เกิดข้อผิดพลาดในการดำเนินการ",
        "error",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRejectSubmit = async () => {
    if (!comment.trim()) {
      showToast("กรุณาระบุเหตุผลในการไม่อนุมัติ", "error");
      return;
    }

    setIsSubmitting(true);
    try {
      await submitReject(
        documentId,
        comment,
        rejectType,
        1,
        currentStep,
        documentVersion,
      );
      showToast(
        rejectType === "return"
          ? "ตีกลับเอกสารเพื่อแก้ไขเรียบร้อยแล้ว"
          : "ปฏิเสธเอกสารถาวรเรียบร้อยแล้ว",
        "success",
      );
      setShowRejectModal(false);
      mutate("documents");
      mutate("dashboard");
      router.push("/approvals");
      router.refresh();
    } catch (error: any) {
      showToast(
        (error instanceof Error ? error.message : String(error)) ||
          "เกิดข้อผิดพลาดในการดำเนินการ",
        "error",
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!canApprove && !canReject && !canReturn) {
    return (
      <div className="bg-slate-50 rounded-2xl border border-slate-200/80 p-5 shadow-2xs space-y-2">
        <div className="flex items-center gap-2 text-slate-700 font-bold text-xs">
          <AlertTriangle className="w-4 h-4 text-amber-500" />
          <span>อยู่ระหว่างการรออนุมัติ (Step {currentStep})</span>
        </div>
        <p className="text-xs text-slate-500 font-medium leading-relaxed">
          เอกสารฉบับนี้อยู่ในระหว่างการรอพิจารณาโดย{" "}
          <strong className="text-slate-800">
            {activeApproverName || "ผู้อนุมัติประจำขั้นตอน"}
          </strong>
        </p>
        <div className="text-[11px] text-slate-400 pt-1">
          🔒
          ปุ่มอนุมัติและลายเซ็นจะเปิดให้ใช้งานเมื่อเป็นลำดับสิทธิ์ของคุณเท่านั้น
        </div>
      </div>
    );
  }

  return (
    <>
      <div className="bg-white rounded-2xl border border-slate-100/80 p-6 shadow-sm space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">
            ดำเนินการพิจารณา (Approval Decision)
          </h3>
          {!signaturePlaced && (
            <span className="flex items-center gap-1 text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full border border-amber-200">
              <AlertTriangle className="w-3 h-3" />
              ต้องวางลายเซ็นก่อนอนุมัติ
            </span>
          )}
        </div>

        <div className="space-y-4">
          {/* Comment field — requires add_comment:edit */}
          {canComment ? (
            <div>
              <label className="block text-xs font-semibold text-slate-600 mb-1.5">
                ความคิดเห็น / หมายเหตุประกอบการพิจารณา (Comment)
              </label>
              <textarea
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                className="w-full px-3.5 py-2.5 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all resize-none text-xs font-semibold text-slate-700 placeholder-slate-400"
                rows={3}
                placeholder="ระบุความคิดเห็น... (จำเป็นต้องระบุหากไม่อนุมัติ)"
                disabled={isSubmitting}
              />
            </div>
          ) : (
            <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 text-xs text-slate-400 font-medium">
              🔒 ไม่มีสิทธิ์เพิ่มความคิดเห็น
            </div>
          )}

          <div className="flex gap-3 pt-2">
            {/* Reject button — requires reject_document:approve OR return_document:approve */}
            {canReject || canReturn ? (
              <button
                type="button"
                onClick={() => setShowRejectModal(true)}
                disabled={isSubmitting}
                className="flex-1 flex items-center justify-center gap-2 py-2.5 px-4 bg-white border border-rose-200 text-rose-600 hover:bg-rose-50 font-bold rounded-xl text-xs transition-all disabled:opacity-50 cursor-pointer"
              >
                <X className="w-4 h-4" />
                ปฏิเสธ / ตีกลับ (Reject)
              </button>
            ) : null}

            {/* Approve button — requires approve_document:approve */}
            {canApprove ? (
              <button
                type="button"
                onClick={handleApprove}
                disabled={isSubmitting}
                className={`flex-1 flex items-center justify-center gap-2 py-2.5 px-4 text-white font-bold rounded-xl text-xs transition-all shadow-sm disabled:opacity-50 cursor-pointer ${
                  signaturePlaced
                    ? "bg-emerald-600 hover:bg-emerald-700 shadow-emerald-100"
                    : "bg-slate-400 hover:bg-slate-500 cursor-not-allowed"
                }`}
              >
                {isSubmitting ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Check className="w-4 h-4" />
                )}
                อนุมัติ (Approve)
              </button>
            ) : null}
          </div>
        </div>
      </div>

      {/* REJECT OPTIONS MODAL */}
      {showRejectModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-xs p-4">
          <div className="bg-white rounded-2xl border border-slate-100 shadow-xl max-w-md w-full p-6 space-y-5 animate-in fade-in zoom-in-95 duration-150">
            <div className="flex items-center justify-between border-b border-slate-100 pb-3">
              <h3 className="text-sm font-bold text-slate-800 flex items-center gap-2">
                <X className="w-4 h-4 text-rose-600" />
                เลือกรูปแบบการปฏิเสธเอกสาร
              </h3>
              <button
                type="button"
                onClick={() => setShowRejectModal(false)}
                className="text-slate-400 hover:text-slate-600 text-xs font-bold"
              >
                ✕
              </button>
            </div>

            <div className="space-y-3">
              {/* Return option — requires return_document:approve */}
              {canReturn && (
                <label
                  onClick={() => setRejectType("return")}
                  className={`flex items-start gap-3 p-3.5 rounded-xl border cursor-pointer transition-all ${
                    rejectType === "return"
                      ? "border-amber-500 bg-amber-50/50 shadow-xs"
                      : "border-slate-200 bg-white hover:bg-slate-50"
                  }`}
                >
                  <input
                    type="radio"
                    name="reject_type"
                    checked={rejectType === "return"}
                    onChange={() => setRejectType("return")}
                    className="mt-0.5 text-amber-600 focus:ring-amber-500"
                  />
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-1.5 text-xs font-bold text-slate-800">
                      <RotateCcw className="w-3.5 h-3.5 text-amber-600" />
                      ตีกลับให้ผู้สร้างแก้ไข (Reject & Return)
                    </div>
                    <p className="text-[11px] text-slate-500 font-medium">
                      สถานะเอกสารจะเปลี่ยนเป็น Returned (ส่งกลับแก้ไข)
                      เพื่อให้ผู้สร้างแก้ไขและส่งขออนุมัติใหม่ได้
                    </p>
                  </div>
                </label>
              )}

              {/* Reject-cancel option — requires reject_document:approve */}
              {canReject && (
                <label
                  onClick={() => setRejectType("cancel")}
                  className={`flex items-start gap-3 p-3.5 rounded-xl border cursor-pointer transition-all ${
                    rejectType === "cancel"
                      ? "border-rose-500 bg-rose-50/50 shadow-xs"
                      : "border-slate-200 bg-white hover:bg-slate-50"
                  }`}
                >
                  <input
                    type="radio"
                    name="reject_type"
                    checked={rejectType === "cancel"}
                    onChange={() => setRejectType("cancel")}
                    className="mt-0.5 text-rose-600 focus:ring-rose-500"
                  />
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-1.5 text-xs font-bold text-slate-800">
                      <Ban className="w-3.5 h-3.5 text-rose-600" />
                      ปฏิเสธถาวร (Reject & Cancel)
                    </div>
                    <p className="text-[11px] text-slate-500 font-medium">
                      ปิดขั้นตอนอนุมัติถาวร เอกสารจะอยู่ในสถานะ Rejected
                      ไม่สามารถแก้ไขหรือส่งใหม่ได้
                    </p>
                  </div>
                </label>
              )}
            </div>

            <div className="flex gap-3 pt-2 border-t border-slate-100">
              <button
                type="button"
                onClick={() => setShowRejectModal(false)}
                className="flex-1 py-2 px-4 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs transition-all"
              >
                ยกเลิก
              </button>

              <button
                type="button"
                onClick={handleRejectSubmit}
                disabled={isSubmitting}
                className="flex-1 flex items-center justify-center gap-2 py-2 px-4 bg-rose-600 hover:bg-rose-700 text-white font-bold rounded-xl text-xs transition-all disabled:opacity-50"
              >
                {isSubmitting ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  "ยืนยันปฏิเสธ"
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import Link from "next/link";
import { Download, PenLine } from "lucide-react";
import { usersService } from "@/controllers/services/users.service";
import { DocumentPreview } from "../documents/DocumentPreview";
import type { ApprovalSignatureInput } from "@models";

interface Props {
  documentId: string;
  documentName: string;
  version: string;
  initialStatus: string;
  signaturePlaced: boolean;
  onSignatureChange?: (placed: boolean, input?: ApprovalSignatureInput) => void;
  doc?: unknown;
  canSign?: boolean;
  activeApproverName?: string;
  currentStep?: number;
}
export function DocumentSignerViewer({
  documentId,
  doc,
  canSign = false,
  signaturePlaced,
  onSignatureChange,
  currentStep = 1,
  activeApproverName,
}: Props) {
  const [signature, setSignature] = useState<string | null>(null);
  const [input, setInput] = useState<ApprovalSignatureInput>({
    signature_page: 1,
    signature_width: 120,
    signature_height: 60,
    signature_x: 36 + ((currentStep - 1) % 3) * 170,
    signature_y: 60 + Math.floor((currentStep - 1) / 3) * 90,
    annotation_text: "",
    date_stamp: false,
  });
  const document = doc as
    | {
        real_id?: string;
        type?: string;
        versions?: { version_number: number; file_extension?: string }[];
      }
    | undefined;
  const uploaded =
    !!document &&
    !["PR", "PO", "BK", "MEMO", "บันทึก"].includes(document.type ?? "");
  useEffect(() => {
    if (canSign)
      usersService
        .getMySignatureUrl()
        .then((value) => setSignature(value.url))
        .catch(() => setSignature(null));
  }, [canSign]);
  const change = (patch: Partial<ApprovalSignatureInput>) => {
    const next = { ...input, ...patch };
    setInput(next);
    onSignatureChange?.(signaturePlaced, next);
  };
  const place = () => {
    if (canSign && signature) onSignatureChange?.(true, input);
  };
  const url = `/api/documents/${encodeURIComponent(document?.real_id || documentId)}/download`;
  return (
    <section className="rounded-2xl border border-slate-200 bg-white p-5 space-y-4">
      <div className="flex flex-wrap justify-between gap-3 items-center">
        <h3 className="font-bold text-slate-800">เอกสารและลายเซ็นอนุมัติ</h3>
        <a
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="text-sm text-blue-700 flex items-center gap-2"
        >
          <Download className="size-4" />
          เปิด PDF ฉบับจริง
        </a>
      </div>
      {canSign ? (
        <div className="space-y-3 rounded-xl bg-blue-50 p-4">
          {signature ? (
            <div className="flex gap-4 items-center">
              <img
                src={signature}
                alt="ลายเซ็นของคุณ"
                className="h-14 max-w-40 object-contain"
              />
              <button
                type="button"
                onClick={place}
                className="rounded-lg bg-blue-600 px-4 py-2 text-white flex gap-2 items-center"
              >
                <PenLine className="size-4" />
                {signaturePlaced ? "เลือกลายเซ็นแล้ว" : "ใช้ลายเซ็นนี้อนุมัติ"}
              </button>
            </div>
          ) : (
            <p className="text-sm text-amber-800">
              กรุณา{" "}
              <Link className="underline" href="/profile">
                บันทึกลายเซ็นในโปรไฟล์
              </Link>{" "}
              ก่อนอนุมัติ
            </p>
          )}
          {uploaded && (
            <div className="grid grid-cols-3 gap-3 text-xs">
              <label>
                หน้า PDF
                <input
                  aria-label="หน้าลายเซ็น"
                  type="number"
                  min="1"
                  value={input.signature_page}
                  onChange={(e) =>
                    change({ signature_page: Number(e.target.value) })
                  }
                  className="block w-full border rounded-lg p-2 mt-1"
                />
              </label>
              <label>
                X จากซ้าย (point)
                <input
                  aria-label="พิกัด X"
                  type="number"
                  min="0"
                  value={input.signature_x}
                  onChange={(e) =>
                    change({ signature_x: Number(e.target.value) })
                  }
                  className="block w-full border rounded-lg p-2 mt-1"
                />
              </label>
              <label>
                Y จากล่าง (point)
                <input
                  aria-label="พิกัด Y"
                  type="number"
                  min="0"
                  value={input.signature_y}
                  onChange={(e) =>
                    change({ signature_y: Number(e.target.value) })
                  }
                  className="block w-full border rounded-lg p-2 mt-1"
                />
              </label>
            </div>
          )}
          <label className="block text-sm">
            ข้อความที่บันทึกลง PDF
            <textarea
              aria-label="ข้อความบน PDF"
              maxLength={1000}
              value={input.annotation_text}
              onChange={(e) => change({ annotation_text: e.target.value })}
              className="block w-full border rounded-lg p-2 mt-1"
            />
          </label>
          <label className="flex gap-2 text-sm">
            <input
              type="checkbox"
              checked={input.date_stamp}
              onChange={(e) => change({ date_stamp: e.target.checked })}
            />
            เพิ่มวันที่และเวลาลงนามลง PDF
          </label>
          <p className="text-xs text-slate-600">
            {uploaded
              ? "ลายเซ็นจะบันทึกบนหน้าและพิกัดที่ระบุเมื่อกดอนุมัติ"
              : "ลายเซ็นจะลงในช่องของผู้อนุมัติขั้นปัจจุบัน และบันทึกเป็น PDF version ใหม่"}
          </p>
        </div>
      ) : (
        <p className="text-sm text-slate-500">
          ดูเอกสาร:{" "}
          {activeApproverName
            ? `รอ ${activeApproverName}`
            : "ยังไม่ถึงขั้นของคุณ"}
        </p>
      )}
      {uploaded ? (
        <iframe
          src={url}
          title="PDF สำหรับอนุมัติ"
          className="h-[650px] w-full border rounded-lg"
        />
      ) : (
        <DocumentPreview
          doc={doc}
          hideHeader
          isViewer
          tempSignature={signaturePlaced}
          onSignClick={place}
        />
      )}
    </section>
  );
}

"use client";

import React from "react";
import { CheckCircle2, Circle, Clock, XCircle } from "lucide-react";
import type { WorkflowData } from '@views/features/workflow/api';

interface WorkflowTrackerProps {
  workflow: WorkflowData;
}

export function WorkflowTracker({ workflow }: WorkflowTrackerProps) {
  if (!workflow || !workflow.steps) return null;

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-6 shadow-sm">
      <h3 className="text-lg font-bold text-gray-900 mb-6">สถานะการอนุมัติ (Workflow Tracker)</h3>
      
      <div className="relative pl-6 sm:pl-8 before:absolute before:inset-0 before:ml-4 sm:before:ml-6 before:-translate-x-px before:h-full before:w-0.5 before:bg-gradient-to-b before:from-gray-200 before:via-gray-200 before:to-transparent space-y-8">
        {workflow.steps.map((step, index) => {
          let Icon = Circle;
          let iconColor = "text-gray-300";
          let bgColor = "bg-white";
          let borderColor = "border-gray-100";
          
          if (step.status === "Approved") {
            Icon = CheckCircle2;
            iconColor = "text-emerald-500";
            bgColor = "bg-emerald-50/50";
            borderColor = "border-emerald-100";
          } else if (step.status === "Rejected") {
            Icon = XCircle;
            iconColor = "text-rose-500";
            bgColor = "bg-rose-50/50";
            borderColor = "border-rose-100";
          } else if (step.status === "Pending") {
            if (step.stepOrder === workflow.currentStep) {
              Icon = Clock;
              iconColor = "text-blue-500";
              bgColor = "bg-blue-50/50";
              borderColor = "border-blue-100";
            } else {
              Icon = Circle;
              iconColor = "text-gray-300";
              bgColor = "bg-gray-50/50";
              borderColor = "border-gray-100";
            }
          }

          return (
            <div key={step.id} className="relative flex items-start group">
              {/* Timeline dot */}
              <div className="absolute -left-6 sm:-left-8 flex items-center justify-center w-8 h-8 rounded-full border-[3px] border-white bg-white shadow-sm shrink-0 z-10 top-1">
                <Icon className={`w-4 h-4 sm:w-5 sm:h-5 ${iconColor}`} />
              </div>
              
              {/* Content Card */}
              <div className={`w-full p-4 sm:p-5 rounded-xl border ${borderColor} ${bgColor} shadow-sm transition-all hover:shadow-md ml-2`}>
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-3">
                  <h4 className="font-bold text-gray-900 text-base">{step.roleName}</h4>
                  <span className={`text-xs font-bold px-3 py-1 rounded-full w-fit ${
                    step.status === 'Approved' ? 'bg-emerald-100 text-emerald-700' :
                    step.status === 'Rejected' ? 'bg-rose-100 text-rose-700' :
                    step.status === 'Pending' && step.stepOrder === workflow.currentStep ? 'bg-blue-100 text-blue-700' :
                    'bg-gray-100 text-gray-500'
                  }`}>
                    {step.status === "Pending" && step.stepOrder !== workflow.currentStep ? "Waiting" : step.status}
                  </span>
                </div>
                
                <div className="space-y-1.5 text-sm">
                  {step.approverName && (
                    <div className="flex items-start gap-1.5 text-slate-600">
                      <span className="text-slate-400 font-medium shrink-0">ผู้อนุมัติ:</span>
                      <span className="font-bold text-slate-800 leading-snug">{step.approverName}</span>
                    </div>
                  )}
                  
                  {step.actionDate && (
                    <div className="flex items-center gap-1.5 text-xs text-slate-400">
                      <Clock className="w-3.5 h-3.5 shrink-0" />
                      <span>{step.actionDate}</span>
                    </div>
                  )}
                </div>
                
                {step.comment && (
                  <div className="mt-4 p-3.5 bg-white rounded-lg border border-gray-100 relative shadow-sm">
                    <div className="absolute -top-1.5 left-4 w-3 h-3 bg-white border-t border-l border-gray-100 rotate-45"></div>
  { }
                    <p className="text-sm text-gray-700 relative z-10 font-medium">"{step.comment}"</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

