"use client";

import { useEffect, useMemo, useState } from "react";
import { AlertCircle, ChevronRight, Loader2, Plus, Trash2, X } from "lucide-react";
import {
  ROLE_OPTIONS,
  type ApprovalMatrixState,
  type DocumentTypeRecord,
  type RoleOption,
} from '@views/features/master-data';
import { MD_SIDEBAR_PANEL, MD_TABLE_CARD } from '@views/components/ui/admin';

type Props = {
  matrix: ApprovalMatrixState;
  docTypes: DocumentTypeRecord[];
  selectedKey: string;
  onSelectKey: (key: string) => void;
  onMatrixChange: (next: ApprovalMatrixState) => void;
  showToast: (message: string, type: "success" | "error") => void;
  setupNotice: string | null;
  onDismissSetupNotice: () => void;
};

function findDuplicateRoles(steps: RoleOption[]): Set<RoleOption> {
  const seen = new Set<RoleOption>();
  const dupes = new Set<RoleOption>();
  steps.forEach((role) => {
    if (seen.has(role)) dupes.add(role);
    seen.add(role);
  });
  return dupes;
}

const FIXED_STEP_TYPES: Record<string, number> = {
  PR: 3,
  PO: 4,
};

function isStepCountLocked(key: string): boolean {
  return key in FIXED_STEP_TYPES;
}

function getFixedStepCount(key: string): number | null {
  return FIXED_STEP_TYPES[key] ?? null;
}

function normalizeStepsForKey(key: string, steps: RoleOption[]): RoleOption[] {
  const fixed = getFixedStepCount(key);
  if (fixed === null) return [...steps];
  const normalized = [...steps];
  while (normalized.length < fixed) normalized.push(ROLE_OPTIONS[0]);
  return normalized.slice(0, fixed);
}

function lockedStepHelperText(key: string): string | null {
  if (key === "PR") return "PR ใช้สายการอนุมัติแบบ 3 ระดับตายตัวตามข้อกำหนดระบบ";
  if (key === "PO") return "PO ใช้สายการอนุมัติแบบ 4 ระดับตายตัวตามข้อกำหนดระบบ";
  return null;
}

function StepFlowPreview({ steps }: { steps: RoleOption[] }) {
  if (steps.length === 0) return null;

  return (
    <div className="overflow-x-auto rounded-lg border border-blue-100 bg-blue-50/40 px-4 py-3">
      <p className="mb-2 text-xs font-medium uppercase tracking-wide text-blue-600/80">
        ตัวอย่างสายอนุมัติ
      </p>
      <div className="flex min-w-max flex-wrap items-center gap-1.5">
        {steps.map((role, index) => (
          <span key={`${role}-${index}`} className="flex items-center gap-1.5">
            <span className="rounded-full border border-blue-200 bg-white px-3 py-1 text-xs font-medium text-blue-800 shadow-sm">
              {role}
            </span>
            {index < steps.length - 1 && (
              <ChevronRight className="size-4 shrink-0 text-blue-400" aria-hidden />
            )}
          </span>
        ))}
      </div>
    </div>
  );
}

export default function ApprovalMatrixTab({
  matrix,
  docTypes,
  selectedKey,
  onSelectKey,
  onMatrixChange,
  showToast,
  setupNotice,
  onDismissSetupNotice,
}: Props) {
  const [draftSteps, setDraftSteps] = useState<RoleOption[]>([]);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);

  const activeTypes = useMemo(() => docTypes, [docTypes]);

  const selectedEntry = matrix[selectedKey];
  const selectedType = docTypes.find((d) => d.key === selectedKey);
  const stepCountLocked = isStepCountLocked(selectedKey);
  const fixedStepCount = getFixedStepCount(selectedKey);
  const lockedHelperText = lockedStepHelperText(selectedKey);

  const isUnconfigured = (key: string) => (matrix[key]?.steps.length ?? 0) === 0;

  const syncDraft = (key: string) => {
    const steps = matrix[key]?.steps ?? [];
    setDraftSteps(normalizeStepsForKey(key, steps));
    setDirty(false);
  };

  useEffect(() => {
    if (selectedKey && matrix[selectedKey]) {
   
      syncDraft(selectedKey);
    }
  }, [selectedKey, matrix]);

  const duplicateRoles = findDuplicateRoles(draftSteps);
  const hasDuplicate = duplicateRoles.size > 0;

  const canSave = stepCountLocked
    ? draftSteps.every((s) => s) && !hasDuplicate && dirty
    : draftSteps.length >= 1 &&
      draftSteps.length <= 4 &&
      draftSteps.every((s) => s) &&
      !hasDuplicate &&
      dirty;

  const updateStep = (index: number, role: RoleOption) => {
    setDraftSteps((prev) => {
      const next = [...prev];
      next[index] = role;
      return next;
    });
    setDirty(true);
  };

  const removeStep = (index: number) => {
    if (stepCountLocked || draftSteps.length <= 1) return;
    setDraftSteps((prev) => prev.filter((_, i) => i !== index));
    setDirty(true);
  };

  const addStep = () => {
    if (stepCountLocked || draftSteps.length >= 4) return;
    setDraftSteps((prev) => [...prev, ROLE_OPTIONS[0]]);
    setDirty(true);
  };

  const handleSave = async () => {
    if (!canSave || !selectedEntry) return;
    setSaving(true);
    await new Promise((r) => setTimeout(r, 500));

    onMatrixChange({
      ...matrix,
      [selectedKey]: {
        ...selectedEntry,
        steps: normalizeStepsForKey(selectedKey, draftSteps),
      },
    });

    setSaving(false);
    setDirty(false);
    showToast("บันทึกสายการอนุมัติสำเร็จ", "success");
  };

  const handleSelectKey = (key: string) => {
    onSelectKey(key);
    syncDraft(key);
  };

  if (activeTypes.length === 0) {
    return (
      <div className={`${MD_TABLE_CARD} p-12 text-center`}>
        <p className="text-sm text-slate-500">
          ไม่มีประเภทเอกสารที่ใช้งาน — เพิ่มประเภทเอกสารในแท็บแรกก่อน
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-4 pb-24 md:flex-row md:gap-6 md:pb-0">
      <div className="md:hidden">
        <label className="mb-1.5 block text-xs font-medium text-slate-500">ประเภทเอกสาร</label>
        <select
          value={selectedKey}
          onChange={(e) => handleSelectKey(e.target.value)}
          className="w-full rounded-md border border-gray-200 bg-white px-3 py-2.5 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
        >
          {activeTypes.map((type) => (
            <option key={type.key} value={type.key}>
              {type.typeName}
              {isUnconfigured(type.key) ? " — ยังไม่ตั้งค่า" : ""}
            </option>
          ))}
        </select>
      </div>

      <aside className={`hidden w-[220px] shrink-0 md:block ${MD_SIDEBAR_PANEL}`}>
        <div className="space-y-1 p-4">
        <p className="mb-2 px-2 text-xs font-bold uppercase tracking-wider text-slate-400">
          ประเภทเอกสาร
        </p>
        {activeTypes.map((type) => {
          const unconfigured = isUnconfigured(type.key);
          return (
            <button
              key={type.key}
              type="button"
              onClick={() => handleSelectKey(type.key)}
              className={`flex w-full items-start gap-2 rounded-md border-l-2 px-3 py-2 text-left text-sm transition-colors ${
                selectedKey === type.key
                  ? "border-blue-600 bg-blue-50 font-semibold text-blue-700"
                  : "border-transparent text-slate-600 hover:bg-gray-50 hover:text-slate-800"
              } ${!type.isActive ? "opacity-50" : ""}`}
            >
              {unconfigured && (
                <span
                  className="mt-1.5 size-2 shrink-0 rounded-full bg-red-500"
                  title="ยังไม่ตั้งค่าสายอนุมัติ"
                />
              )}
              <span className="min-w-0 flex-1">
                <span className="flex flex-wrap items-center gap-1.5">
                  <span className="truncate">{type.typeName}</span>
                  {unconfigured && (
                    <span className="rounded bg-red-50 px-1.5 py-0.5 text-[10px] font-medium text-red-600">
                      ยังไม่ตั้งค่า
                    </span>
                  )}
                </span>
                <span className="text-xs font-normal text-slate-400">{type.prefix}</span>
              </span>
            </button>
          );
        })}
        </div>
      </aside>

      <section className="min-w-0 flex-1 space-y-4">
        {setupNotice && (
          <div className="flex items-start gap-3 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3">
            <AlertCircle className="mt-0.5 size-4 shrink-0 text-amber-600" />
            <p className="flex-1 text-sm text-amber-900">
              กรุณาตั้งค่าสายการอนุมัติสำหรับ <strong>{setupNotice}</strong> ก่อนใช้งาน
            </p>
            <button
              type="button"
              onClick={onDismissSetupNotice}
              className="rounded p-1 text-amber-600 transition-colors hover:bg-amber-100"
              aria-label="ปิดแจ้งเตือน"
            >
              <X className="size-4" />
            </button>
          </div>
        )}

        <div className="flex items-center justify-between">
          <h2 className="text-sm font-medium text-slate-800">
            สายการอนุมัติ — {selectedType?.typeName ?? "—"}
          </h2>
          <span className="rounded-md bg-slate-100 px-2 py-0.5 text-xs text-slate-500">
            {stepCountLocked && fixedStepCount !== null
              ? `${fixedStepCount}/${fixedStepCount} ขั้น (ตายตัว)`
              : `${draftSteps.length}/4 ขั้น`}
          </span>
        </div>

        <div className={`${MD_TABLE_CARD} space-y-3 p-4 md:p-6`}>
          {draftSteps.length === 0 && (
            <p className="py-4 text-center text-sm text-slate-400">
              ยังไม่ได้กำหนดสายอนุมัติ — กดเพิ่มขั้นอนุมัติเพื่อเริ่มต้น
            </p>
          )}
          {draftSteps.map((role, index) => {
            const isDupe = duplicateRoles.has(role);
            return (
              <div
                key={`${selectedKey}-step-${index}`}
                className={`rounded-lg border p-4 ${
                  isDupe ? "border-amber-300 bg-amber-50/50" : "border-gray-200 bg-gray-50/50"
                }`}
              >
                <div className="flex items-center gap-3">
                  <span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-blue-600 text-xs font-semibold text-white">
                    {index + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <label className="mb-1 block text-xs text-slate-500">บทบาทผู้อนุมัติ</label>
                    <select
                      value={role}
                      onChange={(e) => updateStep(index, e.target.value as RoleOption)}
                      className="w-full rounded-md border border-gray-200 bg-white px-3 py-2 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
                    >
                      {ROLE_OPTIONS.map((opt) => (
                        <option key={opt} value={opt}>
                          {opt}
                        </option>
                      ))}
                    </select>
                    {isDupe && (
                      <p className="mt-1 text-xs text-amber-700">
                        บทบาทซ้ำในสายเดียวกัน — กรุณาเลือกบทบาทอื่น
                      </p>
                    )}
                  </div>
                  {!stepCountLocked && (
                    <button
                      type="button"
                      onClick={() => removeStep(index)}
                      disabled={draftSteps.length <= 1}
                      title={draftSteps.length <= 1 ? "ต้องมีอย่างน้อย 1 ขั้น" : "ลบขั้นนี้"}
                      className="mt-5 rounded-md p-2 text-slate-400 transition-colors hover:bg-red-50 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      <Trash2 className="size-4" />
                    </button>
                  )}
                </div>
              </div>
            );
          })}

          {!stepCountLocked && (
            <button
              type="button"
              onClick={addStep}
              disabled={draftSteps.length >= 4}
              title={draftSteps.length >= 4 ? "สูงสุด 4 ขั้น" : "เพิ่มขั้นอนุมัติ"}
              className="hidden w-full items-center justify-center gap-2 rounded-lg border border-dashed border-gray-300 py-3 text-sm text-slate-500 transition-colors hover:border-blue-400 hover:bg-blue-50/50 hover:text-blue-600 disabled:cursor-not-allowed disabled:opacity-40 md:flex"
            >
              <Plus className="size-4" />
              เพิ่มขั้นอนุมัติ
            </button>
          )}

          {lockedHelperText && (
            <p className="text-xs text-slate-500">{lockedHelperText}</p>
          )}
        </div>

        {draftSteps.length > 0 ? (
          <StepFlowPreview steps={draftSteps} />
        ) : selectedType ? (
          <p className="rounded-lg border border-amber-100 bg-amber-50/60 px-4 py-3 text-sm text-amber-800">
            {selectedType.typeName} ยังไม่พร้อมใช้งาน — กำหนดสายอนุมัติอย่างน้อย 1 ขั้นก่อน
          </p>
        ) : null}

        <div className="hidden justify-end md:flex">
          <button
            type="button"
            onClick={handleSave}
            disabled={saving || !canSave}
            className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-bold text-white shadow-sm transition-colors hover:bg-blue-700 disabled:opacity-60"
          >
            {saving && <Loader2 className="size-4 animate-spin" />}
            {saving ? "กำลังบันทึก..." : "บันทึกสายอนุมัติ"}
          </button>
        </div>
      </section>

      <div className="fixed inset-x-0 bottom-0 z-20 flex gap-2 border-t border-gray-200 bg-white p-4 shadow-[0_-4px_12px_rgba(0,0,0,0.06)] md:hidden">
        {!stepCountLocked && (
          <button
            type="button"
            onClick={addStep}
            disabled={draftSteps.length >= 4}
            className="flex flex-1 items-center justify-center gap-2 rounded-md border border-gray-200 py-3 text-sm font-medium text-slate-700 transition-colors hover:bg-gray-50 disabled:opacity-40"
          >
            <Plus className="size-4" />
            เพิ่มขั้นอนุมัติ
          </button>
        )}
        <button
          type="button"
          onClick={handleSave}
          disabled={saving || !canSave}
          className={`flex items-center justify-center gap-2 rounded-md bg-blue-600 py-3 text-sm font-medium text-white transition-colors hover:bg-blue-700 disabled:opacity-60 ${
            stepCountLocked ? "w-full" : "flex-1"
          }`}
        >
          {saving && <Loader2 className="size-4 animate-spin" />}
          {saving ? "กำลังบันทึก..." : "บันทึก"}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { api } from "@/lib";
import { usePermission } from "@/controllers/hooks/usePermission";
import { Hash, Inbox, Loader2, X } from "lucide-react";
import { swalConfirm } from "@/lib/swal";
import { useSidebar } from "@views/components/providers/SidebarProvider";
import {
  RESET_CYCLE_LABELS,
  YEAR_FORMAT_LABELS,
  formatRunningPattern,
  getRunningConfigs,
  updateRunningConfig,
  type DocumentRunningConfig,
  type ResetCycle,
  type RunningDigits,
  type RunningSeparator,
  type YearFormat,
} from "@views/features/master-data";
import {
  InactiveFilterCheckbox,
  MasterDataMobileCardList,
  MasterDataTableWrap,
  MD_TD,
  MD_TD_ACTION,
  MD_TD_MUTED,
  MD_TD_NUM_RIGHT,
  MD_TD_STICKY,
  MD_TD_STATUS,
  MD_TH,
  MD_TH_ACTION,
  MD_TH_RIGHT,
  MD_TH_STICKY,
  MD_TH_STATUS,
  MD_TABLE,
  MD_THEAD,
  MD_TR,
  RowActions,
  StatCards,
  StatusBadge,
  StatusFormToggle,
} from "@views/components/ui/admin";

type Props = {
  showToast: (message: string, type: "success" | "error") => void;
};

type RunningFormState = {
  yearFormat: YearFormat;
  runningDigits: RunningDigits;
  separator: RunningSeparator;
  resetCycle: ResetCycle;
  isActive: boolean;
};

function runningFormSnapshot(form: RunningFormState): string {
  return JSON.stringify(form);
}

const thCls = MD_TH;
const tdCls = MD_TD;
const tdMuted = MD_TD_MUTED;
const tdNum = MD_TD_NUM_RIGHT;
const inputCls =
  "w-full rounded-md border border-gray-200 px-3 py-2 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500";

export default function DocumentRunningTab({ showToast }: Props) {
  const { isOpen } = useSidebar();
  const [configs, setConfigs] = useState<DocumentRunningConfig[]>([]);
  const { canAny } = usePermission();
  const canEdit = canAny([
    "masterdata.running_numbers:edit",
    "masterdata.access:edit",
  ]);
  useEffect(() => {
    api
      .get<DocumentRunningConfig[]>("/api/admin/running-numbers")
      .then((r) => setConfigs(r.data))
      .catch((error) => showToast(String(error), "error"));
  }, []);
  const [showInactive, setShowInactive] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingKey, setEditingKey] = useState<string | null>(null);
  const [form, setForm] = useState<RunningFormState>({
    yearFormat: "be4",
    runningDigits: 4,
    separator: "-",
    resetCycle: "yearly",
    isActive: true,
  });
  const [baseline, setBaseline] = useState("");
  const [saving, setSaving] = useState(false);

  const editingRow = configs.find((c) => c.matrixKey === editingKey) ?? null;

  const rows = useMemo(
    () =>
      showInactive
        ? configs.filter((c) => !c.isActive)
        : configs.filter((c) => c.isActive),
    [configs, showInactive],
  );

  const stats = useMemo(
    () => ({
      total: configs.length,
      active: configs.filter((c) => c.isActive).length,
      inactive: configs.filter((c) => !c.isActive).length,
    }),
    [configs],
  );

  const preview = useMemo(() => {
    if (!editingRow) return { pattern: "", example: "" };
    return formatRunningPattern(
      {
        prefix: editingRow.prefix,
        yearFormat: form.yearFormat,
        runningDigits: form.runningDigits,
        separator: form.separator,
      },
      editingRow.currentCounter + 1,
    );
  }, [editingRow, form]);

  const isDirty = modalOpen && runningFormSnapshot(form) !== baseline;
  const showPatternWarning =
    !!editingRow && editingRow.currentCounter > 0 && isDirty;

  const openEdit = (matrixKey: string) => {
    const row = configs.find((c) => c.matrixKey === matrixKey);
    if (!row) return;
    const nextForm: RunningFormState = {
      yearFormat: row.yearFormat,
      runningDigits: row.runningDigits,
      separator: row.separator,
      resetCycle: row.resetCycle,
      isActive: row.isActive,
    };
    setEditingKey(matrixKey);
    setForm(nextForm);
    setBaseline(runningFormSnapshot(nextForm));
    setModalOpen(true);
  };

  const closeModal = async () => {
    if (isDirty) {
      const confirmed = await swalConfirm({
        title: "ปิดหน้าต่างโดยไม่บันทึก?",
        text: "ข้อมูลที่คุณแก้ไขยังไม่ได้บันทึก คุณต้องการปิดหน้าต่างนี้หรือไม่?",
        confirmButtonText: "ปิดหน้าต่าง",
        cancelButtonText: "ยกเลิก",
        icon: "warning",
      });
      if (!confirmed) return;
    }
    setModalOpen(false);
    setEditingKey(null);
    setBaseline("");
  };

  const handleSave = async () => {
    if (!editingKey || !editingRow) return;
    setSaving(true);

    const patch = {
      yearFormat: form.yearFormat,
      runningDigits: form.runningDigits,
      separator: form.separator,
      resetCycle: form.resetCycle,
      isActive: form.isActive,
    };

    try {
      await api.patch(`/api/admin/running-numbers/${editingRow.id}`, patch);
    } catch (error) {
      setSaving(false);
      showToast(
        error instanceof Error ? error.message : String(error),
        "error",
      );
      return;
    }
    setConfigs((prev) =>
      prev.map((c) => (c.matrixKey === editingKey ? { ...c, ...patch } : c)),
    );

    setSaving(false);
    setModalOpen(false);
    setEditingKey(null);
    setBaseline("");
    showToast("บันทึกรูปแบบเลขที่เอกสารสำเร็จ", "success");
  };

  const mobileRows = useMemo(
    () =>
      rows.map((row) => {
        const { pattern, example } = formatRunningPattern(
          row,
          row.currentCounter + 1,
        );
        return {
          id: row.matrixKey,
          title: row.typeName,
          badge: <StatusBadge active={row.isActive} />,
          fields: [
            {
              label: "รูปแบบ",
              value: (
                <>
                  <p className="font-mono text-xs text-slate-600">{pattern}</p>
                  <p className="mt-0.5 text-xs text-slate-400">
                    ตัวอย่าง: {example}
                  </p>
                </>
              ),
            },
            {
              label: "รอบรีเซ็ตเลขที่",
              value: RESET_CYCLE_LABELS[row.resetCycle],
            },
            { label: "เลขที่ปัจจุบัน", value: row.currentCounter },
          ],
          actions: (
            <RowActions
              onEdit={canEdit ? () => openEdit(row.matrixKey) : undefined}
            />
          ),
        };
      }),
    [rows],
  );

  return (
    <div className="space-y-6">
      {modalOpen && editingRow ? (
        <div className="rounded-xl border border-slate-200 bg-white p-6 shadow-xs">
          <div className="flex items-center justify-between pb-4 border-b border-slate-100 mb-6">
            <div>
              <h3 className="text-base font-bold text-slate-800">
                แก้ไขรูปแบบเลขที่ — {editingRow.typeName}
              </h3>
              <p className="text-xs text-slate-400 mt-1">
                กรอกรายละเอียดการตั้งค่าการออกเลขที่เอกสารสำหรับ{" "}
                {editingRow.typeName}
              </p>
            </div>
            <button
              type="button"
              onClick={closeModal}
              disabled={saving}
              className="rounded-md p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600 disabled:opacity-50"
              aria-label="ปิด"
            >
              <X className="size-4" />
            </button>
          </div>

          <div className="space-y-4 max-w-md">
            <div>
              <label className="mb-1.5 block text-xs text-slate-500">
                Prefix
              </label>
              <div className="w-full rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-slate-500">
                {editingRow.prefix}
              </div>
              <p className="mt-1 text-xs text-slate-400">
                แก้ Prefix ได้ที่แท็บประเภทเอกสารเท่านั้น
              </p>
            </div>

            <div>
              <label className="mb-1.5 block text-xs text-slate-500">
                ส่วนปี
              </label>
              <select
                className={inputCls}
                value={form.yearFormat}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    yearFormat: e.target.value as YearFormat,
                  }))
                }
              >
                {(Object.keys(YEAR_FORMAT_LABELS) as YearFormat[]).map(
                  (key) => (
                    <option key={key} value={key}>
                      {YEAR_FORMAT_LABELS[key]}
                    </option>
                  ),
                )}
              </select>
            </div>

            <div>
              <label className="mb-1.5 block text-xs text-slate-500">
                จำนวนหลัก Running Number
              </label>
              <select
                className={inputCls}
                value={form.runningDigits}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    runningDigits: Number(e.target.value) as RunningDigits,
                  }))
                }
              >
                <option value={3}>3 หลัก</option>
                <option value={4}>4 หลัก</option>
                <option value={5}>5 หลัก</option>
              </select>
            </div>

            <div>
              <label className="mb-1.5 block text-xs text-slate-500">
                ตัวคั่น (Separator)
              </label>
              <select
                className={inputCls}
                value={form.separator}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    separator: e.target.value as RunningSeparator,
                  }))
                }
              >
                <option value="-">- (ขีดกลาง)</option>
                <option value="none">ไม่มี</option>
              </select>
            </div>

            <div>
              <label className="mb-1.5 block text-xs text-slate-500">
                รอบรีเซ็ตเลขที่
              </label>
              <select
                className={inputCls}
                value={form.resetCycle}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    resetCycle: e.target.value as ResetCycle,
                  }))
                }
              >
                {(Object.keys(RESET_CYCLE_LABELS) as ResetCycle[]).map(
                  (key) => (
                    <option key={key} value={key}>
                      {RESET_CYCLE_LABELS[key]}
                    </option>
                  ),
                )}
              </select>
            </div>

            <div>
              <label className="mb-1.5 block text-xs text-slate-500">
                เลขที่ปัจจุบัน
              </label>
              <div className="w-full rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-slate-500 tabular-nums">
                {editingRow.currentCounter}
              </div>
              <p className="mt-1 text-xs text-slate-400">
                นับอัตโนมัติจากเอกสารที่ออกเลขแล้ว
              </p>
            </div>

            <StatusFormToggle
              active={form.isActive}
              onChange={(isActive) => setForm((f) => ({ ...f, isActive }))}
            />

            <div className="rounded-lg border border-blue-100 bg-blue-50/60 px-4 py-3">
              <p className="text-xs text-slate-500">ตัวอย่างเลขที่</p>
              <p className="mt-1 font-mono text-sm font-medium text-blue-800">
                {preview.example}
              </p>
              <p className="mt-1 font-mono text-xs text-slate-500">
                {preview.pattern}
              </p>
            </div>

            {showPatternWarning && (
              <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-800">
                การเปลี่ยนรูปแบบจะมีผลกับเอกสารใหม่เท่านั้น
                เอกสารเดิมจะไม่เปลี่ยนเลขที่
              </p>
            )}
          </div>

          <div className="mt-8 pt-4 border-t border-slate-100 flex justify-end gap-2">
            <button
              type="button"
              onClick={closeModal}
              disabled={saving}
              className="rounded-xl px-5 py-2.5 text-sm font-bold text-slate-600 transition-colors hover:bg-slate-100 disabled:opacity-50"
            >
              ยกเลิก
            </button>
            <button
              type="button"
              onClick={handleSave}
              disabled={saving}
              className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-bold text-white transition-colors hover:bg-blue-700 disabled:opacity-60"
            >
              {saving && <Loader2 className="size-4 animate-spin" />}
              {saving ? "กำลังบันทึก..." : "บันทึกข้อมูล"}
            </button>
          </div>
        </div>
      ) : (
        <>
          <div className="flex flex-wrap items-center justify-between gap-4">
            <h2 className="text-sm font-medium text-slate-800">
              รูปแบบเลขที่เอกสาร
            </h2>
            <InactiveFilterCheckbox
              checked={showInactive}
              onChange={setShowInactive}
            />
          </div>

          <MasterDataTableWrap
            empty={rows.length === 0}
            emptyContent={
              <div className="flex flex-col items-center justify-center gap-3 px-6 py-12 text-center">
                <Inbox className="size-10 text-slate-300" />
                <p className="text-sm text-slate-500">
                  {showInactive ? "ไม่มีรายการที่ปิดใช้งาน" : "ไม่มีข้อมูล"}
                </p>
              </div>
            }
            mobile={<MasterDataMobileCardList rows={mobileRows} />}
          >
            <table className={MD_TABLE}>
              <thead className={MD_THEAD}>
                <tr>
                  <th className={MD_TH_STICKY}>ประเภทเอกสาร</th>
                  <th className={thCls}>รูปแบบ</th>
                  <th className={thCls}>รอบรีเซ็ตเลขที่</th>
                  <th className={MD_TH_RIGHT}>เลขที่ปัจจุบัน</th>
                  <th className={MD_TH_STATUS}>สถานะ</th>
                  <th className={MD_TH_ACTION}>จัดการ</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row) => {
                  const { pattern, example } = formatRunningPattern(
                    row,
                    row.currentCounter + 1,
                  );
                  return (
                    <tr key={row.matrixKey} className={`group ${MD_TR}`}>
                      <td className={MD_TD_STICKY}>{row.typeName}</td>
                      <td className={tdCls}>
                        <p className="font-mono text-xs text-slate-600">
                          {pattern}
                        </p>
                        <p className="mt-0.5 text-xs text-slate-400">
                          ตัวอย่าง: {example}
                        </p>
                      </td>
                      <td className={tdMuted}>
                        {RESET_CYCLE_LABELS[row.resetCycle]}
                      </td>
                      <td className={tdNum}>{row.currentCounter}</td>
                      <td className={MD_TD_STATUS}>
                        <StatusBadge active={row.isActive} />
                      </td>
                      <td className={MD_TD_ACTION}>
                        <RowActions
                          onEdit={
                            canEdit ? () => openEdit(row.matrixKey) : undefined
                          }
                        />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </MasterDataTableWrap>

          <StatCards
            total={stats.total}
            active={stats.active}
            inactive={stats.inactive}
            icon={Hash}
          />
        </>
      )}
    </div>
  );
}

