export function RolePermissionPanel({
  role,
  onChange,
}: {
  role: RoleFormState;
  onChange: (next: RoleFormState) => void;
}) {
  const [expanded, setExpanded] = useState<Record<string, boolean>>(() =>
    Object.fromEntries(PERMISSION_SCHEMA.map((s) => [s.key, true])),
  );
  const [searchQuery, setSearchQuery] = useState("");

  const summary = useMemo(() => countAll(role.permissions), [role.permissions]);
  const pageSelectState = useMemo(
    () => checkState(summary.granted, summary.total),
    [summary],
  );

  const normalizedSearch = searchQuery.trim().toLowerCase();

  const visibleSections = useMemo(() => {
    if (!normalizedSearch) return PERMISSION_SCHEMA;
    return PERMISSION_SCHEMA.filter((section) =>
      section.items.some((item) =>
        item.label.toLowerCase().includes(normalizedSearch),
      ),
    );
  }, [normalizedSearch]);

  useEffect(() => {
    if (!normalizedSearch) return;

    setExpanded((prev) => {
      const next = { ...prev };
      for (const section of PERMISSION_SCHEMA) {
        if (
          section.items.some((item) =>
            item.label.toLowerCase().includes(normalizedSearch),
          )
        ) {
          next[section.key] = true;
        }
      }
      return next;
    });
  }, [normalizedSearch]);

  const toggleSection = (key: string) => {
    setExpanded((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const setPermission = (
    moduleKey: string,
    itemKey: string,
    action: ActionKey,
    value: boolean,
  ) => {
    const nextPermissions = {
      ...role.permissions,
      [moduleKey]: {
        ...role.permissions[moduleKey],
        [itemKey]: {
          ...role.permissions[moduleKey]?.[itemKey],
          [action]: value,
        },
      },
    };

    if (action === "view" && !value) {
      const section = PERMISSION_SCHEMA.find((s) => s.key === moduleKey);
      if (section) {
        const dependents = section.items.filter((i) => i.dependsOn === itemKey);
        for (const child of dependents) {
          nextPermissions[moduleKey][child.key] = emptyRow();
        }
      }
    }

    onChange({
      ...role,
      permissions: nextPermissions,
    });
  };

  const applyPermissions = (checked: boolean, moduleKey?: string) => {
    const next: PermissionMatrix = { ...role.permissions };
    const sections = moduleKey
      ? PERMISSION_SCHEMA.filter((s) => s.key === moduleKey)
      : PERMISSION_SCHEMA;
    for (const section of sections) {
      next[section.key] = { ...next[section.key] };
      for (const item of section.items) {
        const row = emptyRow();
        for (const action of PERMISSION_ACTIONS) {
          row[action.key] = item.actions.includes(action.key) ? checked : false;
        }
        next[section.key][item.key] = row;
      }
    }
    onChange({ ...role, permissions: next });
  };

  const applySubGroupPermissions = (
    checked: boolean,
    sectionKey: string,
    subGroupLabel: string,
  ) => {
    const next: PermissionMatrix = { ...role.permissions };
    const section = PERMISSION_SCHEMA.find((s) => s.key === sectionKey);
    if (section) {
      next[sectionKey] = { ...next[sectionKey] };
      const items = section.items.filter(
        (item) => item.subGroup === subGroupLabel,
      );
      for (const item of items) {
        const row = emptyRow();
        for (const action of PERMISSION_ACTIONS) {
          row[action.key] = item.actions.includes(action.key) ? checked : false;
        }
        next[sectionKey][item.key] = row;
      }
    }
    onChange({ ...role, permissions: next });
  };

  return (
    <>
      <div className="relative mt-6">
        <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400" />
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="ค้นหารายการ..."
          className="w-full rounded-xl border border-slate-200 bg-white py-2.5 pl-9 pr-3 text-sm text-slate-700 shadow-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
        />
      </div>

      <div className="mt-4 overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm">
        <div className="flex items-center border-b border-slate-100 px-6 py-4">
          <h2 className="min-w-0 flex-1 text-sm font-bold text-slate-800">
            สิทธิ์การใช้งาน
          </h2>
          <span className={`${countPillCls} mr-4 hidden sm:inline-flex`}>
            เปิดใช้ {summary.granted}/{summary.total} สิทธิ์
          </span>
          <label
            className={`flex ${ACTION_COLS_W} shrink-0 items-center justify-end gap-2 text-sm font-medium text-slate-600`}
          >
            <IndeterminateCheckbox
              state={pageSelectState}
              onChange={(checked) => applyPermissions(checked)}
              className={checkboxCls}
            />
            เลือกทั้งหมด
          </label>
        </div>
        <div className="border-b border-slate-100 px-6 py-2 sm:hidden">
          <span className={countPillCls}>
            เปิดใช้ {summary.granted}/{summary.total} สิทธิ์
          </span>
        </div>

        <div className="divide-y divide-slate-100">
          {visibleSections.map((section) => {
            const sectionCounts = countSection(section.key, role.permissions);
            const sectionState = sectionCheckState(
              section.key,
              role.permissions,
            );
            const filteredItems = normalizedSearch
              ? section.items.filter((item) =>
                  item.label.toLowerCase().includes(normalizedSearch),
                )
              : section.items;

            if (filteredItems.length === 0) return null;

            // Group filtered items by subGroup
            const subGroups: {
              label: string | undefined;
              items: PermissionItem[];
            }[] = [];
            let currentSubGroup: string | undefined = undefined;
            let currentItems: PermissionItem[] = [];

            for (const item of filteredItems) {
              if (item.subGroup !== currentSubGroup) {
                if (currentItems.length > 0) {
                  subGroups.push({
                    label: currentSubGroup,
                    items: currentItems,
                  });
                }
                currentSubGroup = item.subGroup;
                currentItems = [item];
              } else {
                currentItems.push(item);
              }
            }
            if (currentItems.length > 0) {
              subGroups.push({ label: currentSubGroup, items: currentItems });
            }

            return (
              <div key={section.key}>
                <div className="flex items-center bg-blue-50/50 border-t border-b border-blue-100 px-6 py-3">
                  <button
                    type="button"
                    onClick={() => toggleSection(section.key)}
                    className="flex min-w-0 flex-1 items-center gap-2 text-left text-sm font-bold text-blue-900"
                  >
                    <ChevronRight
                      className={`size-4 shrink-0 text-blue-500 transition-transform duration-200 ${
                        expanded[section.key] ? "rotate-90" : ""
                      }`}
                    />
                    <span>{section.label}</span>
                    <span className={countPillCls}>
                      {sectionCounts.granted}/{sectionCounts.total}
                    </span>
                  </button>
                  <label
                    className={`flex ${ACTION_COLS_W} shrink-0 items-center justify-end gap-2 text-xs font-medium text-blue-600`}
                  >
                    <IndeterminateCheckbox
                      state={sectionState}
                      onChange={(checked) =>
                        applyPermissions(checked, section.key)
                      }
                      className={checkboxCls}
                    />
                    เลือกทั้งหมด
                  </label>
                </div>

                {expanded[section.key] && (
                  <div className="overflow-x-auto">
                    <table className="w-full table-fixed text-sm">
                      <colgroup>
                        <col />
                        {PERMISSION_ACTIONS.map((action) => (
                          <col key={action.key} style={{ width: "5rem" }} />
                        ))}
                      </colgroup>
                      <thead className={MD_THEAD}>
                        <tr>
                          <th className={`${MD_TH} font-normal text-slate-400`}>
                            รายการ
                          </th>
                          {PERMISSION_ACTIONS.map((action) => (
                            <th
                              key={action.key}
                              className={PERM_MATRIX_ACTION_TH}
                            >
                              {action.label}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-slate-100">
                        {subGroups.map((group, gIdx) => (
                          <Fragment key={gIdx}>
                            {group.label && (
                              <tr className="bg-slate-50/80">
                                <td
                                  colSpan={1}
                                  className="px-6 py-2.5 text-xs font-bold text-slate-700 uppercase tracking-wide"
                                >
                                  {group.label}
                                </td>
                                <td
                                  colSpan={5}
                                  className="px-2 py-2.5 text-right"
                                >
                                  <label className="inline-flex items-center justify-end gap-2 text-xs font-semibold text-slate-500 hover:text-slate-700 cursor-pointer pr-4">
                                    <IndeterminateCheckbox
                                      state={checkState(
                                        group.items.reduce(
                                          (acc, item) =>
                                            acc +
                                            item.actions.filter(
                                              (a) =>
                                                role.permissions[section.key]?.[
                                                  item.key
                                                ]?.[a],
                                            ).length,
                                          0,
                                        ),
                                        group.items.reduce(
                                          (acc, item) =>
                                            acc + item.actions.length,
                                          0,
                                        ),
                                      )}
                                      onChange={(checked) =>
                                        applySubGroupPermissions(
                                          checked,
                                          section.key,
                                          group.label!,
                                        )
                                      }
                                      className={checkboxCls}
                                    />
                                    เลือกหมวดนี้
                                  </label>
                                </td>
                              </tr>
                            )}
                            {group.items.map((item) => {
                              const parentChecked = item.dependsOn
                                ? !!role.permissions[section.key]?.[
                                    item.dependsOn
                                  ]?.["view"]
                                : true;
                              const isDisabled = !parentChecked;

                              return (
                                <tr
                                  key={item.key}
                                  className={`${MD_TR} ${isDisabled ? "opacity-50" : ""}`}
                                >
                                  <td
                                    className={`px-6 py-3.5 text-sm font-medium ${isDisabled ? "text-slate-400" : "text-slate-700"} ${group.label ? "pl-10" : ""}`}
                                  >
                                    {item.label}
                                  </td>
                                  {PERMISSION_ACTIONS.map((action) => {
                                    const isSupported = item.actions.includes(
                                      action.key,
                                    );
                                    return (
                                      <td
                                        key={action.key}
                                        className={PERM_MATRIX_ACTION_TD}
                                      >
                                        {isSupported ? (
                                          <input
                                            type="checkbox"
                                            disabled={isDisabled}
                                            checked={
                                              !!role.permissions[section.key]?.[
                                                item.key
                                              ]?.[action.key]
                                            }
                                            onChange={(e) =>
                                              setPermission(
                                                section.key,
                                                item.key,
                                                action.key,
                                                e.target.checked,
                                              )
                                            }
                                            className={`${checkboxCls} mx-auto block ${isDisabled ? "cursor-not-allowed opacity-50" : ""}`}
                                          />
                                        ) : (
                                          <span className="text-slate-300 select-none">
                                            -
                                          </span>
                                        )}
                                      </td>
                                    );
                                  })}
                                </tr>
                              );
                            })}
                          </Fragment>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </>
  );
}

export function RoleProductTypesField({
  productTypes,
  onChange,
}: {
  productTypes: Record<ProductKey, boolean>;
  onChange: (next: Record<ProductKey, boolean>) => void;
}) {
  const toggleProductType = (key: ProductKey, checked: boolean) => {
    if (key === "all") {
      onChange({
        all: checked,
        dms: checked,
        esign: checked,
        reports: checked,
        archive: checked,
      });
      return;
    }
    const next = { ...productTypes, [key]: checked };
    next.all = PRODUCT_TYPES.filter((p) => p.key !== "all").every(
      (p) => next[p.key],
    );
    onChange(next);
  };

  return (
    <div>
      <p className="mb-2 text-xs text-slate-500">ประเภทผลิตภัณฑ์</p>
      <div className="flex flex-wrap gap-4">
        {PRODUCT_TYPES.map(({ key, label }) => (
          <label
            key={key}
            className="flex items-center gap-2 text-sm text-slate-600"
          >
            <input
              type="checkbox"
              checked={productTypes[key]}
              onChange={(e) => toggleProductType(key, e.target.checked)}
              className={checkboxCls}
            />
            {label}
          </label>
        ))}
      </div>
    </div>
  );
}

export function countUsersInDepartment(deptName: string, users: any[] = []) {
  return users.filter(u => u.department === deptName).length;
}

export function countUsersWithPosition(posName: string, users: any[] = []) {
  return users.filter(u => u.position === posName).length;
}

export function formatApproverLabel(user: any) {
  if (!user) return "-";
  return `${user.first_name} ${user.last_name} (${user.position || "-"})`;
}

export function getApproverUsers(users: any[]) {
  return users.filter(u => u.is_active);
}

export function countUsersByRole(roleName: string, users: any[] = []) {
  if (!users || users.length === 0) return 0;
  return users.filter((u) => {
    const rName = u.role?.name || u.role_name || u.role || "";
    return rName.toLowerCase() === roleName.toLowerCase();
  }).length;
}

