function NavLink({ item, depth = 0 }: { item: NavItem; depth?: number }) {
  const pathname = usePathname();
  const [open, setOpen] = useState(() =>
    item.children?.some((child) => child.href && pathname.startsWith(child.href)) ?? false
  );

  const isActive = item.href
    ? item.href === "/dashboard"
      ? pathname === item.href
      : pathname.startsWith(item.href)
    : false;

  if (item.children) {
    return (
      <li>
        <button
          onClick={() => setOpen((v) => !v)}
          className={cn(
            "flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors",
            "text-[--color-sidebar-text] hover:bg-[--color-sidebar-hover] hover:text-white",
            depth > 0 && "pl-10"
          )}
        >
          <item.icon className="size-4 shrink-0" />
          <span className="flex-1 text-left">{item.label}</span>
          {open ? (
            <ChevronDown className="size-3.5 text-slate-500" />
          ) : (
            <ChevronRight className="size-3.5 text-slate-500" />
          )}
        </button>
        {open && (
          <ul className="mt-0.5 space-y-0.5">
            {item.children.map((child) => (
              <NavLink key={child.href ?? child.label} item={child} depth={depth + 1} />
            ))}
          </ul>
        )}
      </li>
    );
  }

  return (
    <li>
      <Link
        href={item.href!}
        className={cn(
          "flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors",
          isActive
            ? "bg-[--color-sidebar-active] text-white shadow-sm"
            : "text-[--color-sidebar-text] hover:bg-[--color-sidebar-hover] hover:text-white",
          depth > 0 && "pl-10"
        )}
      >
        <item.icon className="size-4 shrink-0" />
        <span>{item.label}</span>
      </Link>
    </li>
  );
}

export function Sidebar() {
  const { user } = useAuth();
  
  // Get Initials
  const getInitials = (name?: string) => {
    if (!name) return "U";
    const parts = name.split(" ");
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`;
    return name.slice(0, 2);
  };

  return (
    <aside className="flex h-full w-64 flex-col bg-[--color-sidebar-bg]">
      {/* Logo */}
      <Link href="/dashboard" className="flex items-center gap-3 border-b border-[--color-sidebar-border] px-5 py-4 cursor-pointer hover:bg-[--color-sidebar-hover] transition-colors">
        <div className="flex size-8 items-center justify-center rounded-lg bg-blue-600">
          <FileStack className="size-4 text-white" />
        </div>
        <div>
          <p className="text-sm font-bold text-white">DMS</p>
          <p className="text-[10px] text-slate-500">Document Management</p>
        </div>
      </Link>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto px-3 py-4">
        <ul className="space-y-0.5">
          {NAV_ITEMS.map((item) => (
            <NavLink key={item.href ?? item.label} item={item} />
