        </ul>
      </nav>

      {/* Bottom User Info */}
      <div className="border-t border-[--color-sidebar-border] px-4 py-3">
        <Link href="/profile" className="flex items-center gap-3 cursor-pointer group hover:bg-[--color-sidebar-hover] p-1.5 rounded-lg transition-colors">
